BACKUP_FILE="${SSAID_FILE}.bak"
NEW_ID_LENGTH=16
CODEV_DIR="/storage/emulated/0/Android/data/com.tencent.tmgp.codev"
CODEV_DATA_DIR="/data/user/0/com.tencent.tmgp.codev"
GROUP_LINK="https://qm.qq.com/q/G9hcBM63SM"  # 瓦手缓存清理1⃣️群链接

# ========================== 核心修复：保留版本凭证（防重下关键） ==========================
# 这些文件被删会导致游戏认为是新安装，必须保留！
KEEP_CRITICAL_FILES=(
    "Manifest_UFSFiles_Android.txt"       # 下载清单（关键！）
    "NotAllowedUnattendedBugReports"      # 行为报告配置
    "Version.cfg"                         # 本地版本号
    "ClearFlag_*"                         # 清理标记（版本相关）
    "BagSkinCache_*.json"                 # 皮肤缓存配置
    "PlayerData.cfg"                      # 玩家数据
    "PCache.meta"                         # 缓存元数据
    "Manifest.ini"                        # 配置清单
)
# 颜色函数（兼容sh）
red() { echo -e "\033[31m$1\033[0m"; }
green() { echo -e "\033[32m$1\033[0m"; }
yellow() { echo -e "\033[33m$1\033[0m"; }
# ==========================================================================================

# 4. 前置检查：文件与工具依赖
if [ ! -f "$SSAID_FILE" ]; then
    red "错误：安卓ID配置文件不存在！"
    exit 1
fi

for tool in uuidgen sed strings; do
    if ! command -v $tool >/dev/null 2>&1; then
        red "错误：缺少工具 $tool"
        exit 1
    fi
done

# 5. 提取原有SSAID（关键）
yellow "正在提取原安卓ID..."
ID=$(strings "$SSAID_FILE" | grep -A 1 "$PKG" | grep -oE '[0-9a-fA-F]{16}')

if [ -z "$ID" ] || [ ${#ID} -ne 16 ]; then
    yellow "未找到专属ID，尝试提取通用ID..."
    ID=$(strings "$SSAID_FILE" | grep -oE '[0-9a-fA-F]{16}' | head -n 1)
    if [ -z "$ID" ]; then
        red "提取失败！"
        exit 1
    fi
fi
green "原安卓ID：\033[1m$ID\033[0m"

# 6. 生成新的16位随机ID（兼容sh）
yellow "正在生成新ID..."
NEW_ID=$(date +%s%N | md5sum | head -c $NEW_ID_LENGTH)
green "新安卓ID：\033[1m$NEW_ID\033[0m"

# 7. 备份原文件
yellow "正在备份配置文件..."
cp -f "$SSAID_FILE" "$BACKUP_FILE" || {
    red "备份失败！"
