}

# 8. 执行替换（核心修改）
yellow "正在修改安卓ID..."
sed -i "s/$ID/$NEW_ID/g" "$SSAID_FILE" || {
    red "修改失败！正在恢复备份..."
    cp -f "$BACKUP_FILE" "$SSAID_FILE"
    exit 1
}

# 9. 验证修改结果
