# ==== 第三步：清理CodeV目录（保留版本凭证） ====
yellow "正在清理CodeV目录（保留核心凭证）..."
find "$CODEV_DIR/files/UE4Game/CodeV/" -maxdepth 1 -type f | while read file; do
    filename=$(basename "$file")
    keep=0
    # 遍历需要保留的关键文件
    for pattern in "${KEEP_CRITICAL_FILES[@]}"; do
        case "$filename" in
            $pattern) keep=1; break ;;
        esac
    done
    if [ $keep -eq 0 ]; then
        rm -f "$file"
        echo "  删除文件：$file"
    else
        echo "  \033[32m保留凭证：$file\033[0m"
