    local pkg=$1; local name=$2; local bs=$3; local count=$4
    dd if=/dev/zero of="${MEDIA_PATH}/${pkg}/cache/${name}" bs=$bs count=$count 2>/dev/null
}

# 3. 写入文本到文件
write_txt() {
    local path=$1; local content=$2
    # 自动创建父目录，防止路径不存在报错
    mkdir -p "$(dirname "$path")"
    echo "$content" > "$path" 2>/dev/null
}

# 4. 注入 WAL
inject_wal() {
    local pkg=$1
    local wal="${USER_PATH}/${pkg}/files/cache4.db-wal"
    touch "$wal"
    if ! grep -q -a "HLWNB" "$wal"; then
        echo "HLWNB" >> "$wal"
        echo -e "${pkg} >>>${CYAN}写入成功${RESET}"
    else
        echo "${pkg}已存在"
    fi
}

