# 一、空目录清理模块
# ======================================
TARGET_PATHS=(
    "/data/media/0/Android/data"
    "/data/media/0/Android/media" 
    "/data/media/0/Android/obb"
)
EXCLUDE_DIRS=("com.termux" "com.android.providers.downloads")

clean_empty_dirs() {
    echo -e "\n=== 空目录清理开始 ==="
    local total_cleaned=0
    
    for path in "${TARGET_PATHS[@]}"; do
        echo "处理路径: $path"
        if [ ! -d "$path" ]; then
            echo "❌ 目录不存在: $path"
            continue
        fi
        
        local path_cleaned=0
        find "$path" -mindepth 1 -maxdepth 1 -type d | while IFS= read -r dir; do
            local dir_name=${dir##*/}
            local exclude=0
            
            # 检查是否在排除列表中
            for exclude_dir in "${EXCLUDE_DIRS[@]}"; do
                if [ "$dir_name" = "$exclude_dir" ]; then
                    echo "🛡️ 保护跳过: $dir_name"
                    exclude=1
                    break
                fi
            done
            
            if [ "$exclude" -eq 0 ]; then
                if [ -z "$(ls -A "$dir" 2>/dev/null)" ]; then
                    echo "🗑️ 删除空目录: $dir"
                    if rm -rf -- "$dir" 2>/dev/null; then
                        echo "✅ 删除成功"
                        path_cleaned=$((path_cleaned + 1))
                    else
                        echo "❌ 删除失败"
                    fi
                fi
            fi
        done
        
        if [ "$path_cleaned" -gt 0 ]; then
            echo "📊 本路径共清理 $path_cleaned 个空目录"
            total_cleaned=$((total_cleaned + path_cleaned))
        fi
    done
    
    echo "📈 空目录清理完成，总计清理 $total_cleaned 个空目录"
    sleep 3
}

# ======================================
# 二、小文件目录清理模块
# ======================================
SMALL_TARGET_DIRS=(
    "/storage/emulated/0/Android/data"
    "/storage/emulated/0/Android/media"
    "/storage/emulated/0/Android/obb"
)
SIZE_LIMIT=20  # KB
PROTECT_PATTERNS=("com.android.*" "com.google.*" "android" "*.nomedia" "*.obb")

clean_small_dirsm() {
    echo -e "\n=== 小文件目录清理开始 ==="
    for dir in "${SMALL_TARGET_DIRS[@]}"; do
        [ ! -d "$dir" ] && {
            echo "⚠️ 目录不存在: $dir"
            continue
        }
        echo "🔍 扫描目录: $dir"
        find "$dir" -mindepth 1 -maxdepth 1 -type d | while IFS= read -r dir_path; do
            local name=${dir_path##*/}
            # 保护规则匹配（case语法完全兼容POSIX）
            for pattern in "${PROTECT_PATTERNS[@]}"; do
                case "$name" in $pattern)
                    echo "🛡️ 受保护目录: $name"
                    continue 2
                esac
            done
            # 大小计算
            local size=$(du -sk "$dir_path" | cut -f1)
            [[ "$size" -lt "$SIZE_LIMIT" ]] && {
                echo "🗑️ 删除 ${size}KB 目录: $name"
                rm -rf -- "$dir_path"
            }
        done
    done
}

