not_found_count=0
failed_count=0

# 进度显示函数
show_progress() {
    current=$((cleaned_count + not_found_count + failed_count))
    progress=$((100 * current / total_count))
    bars=$((progress / 4))
    spaces=$((25 - bars))
    
    # 构建进度条字符串
    bar_str=""
    i=0
    while [ $i -lt $bars ]; do
        bar_str="${bar_str}■"
        i=$((i + 1))
    done
    
    # 构建空格字符串
    space_str=""
    i=0
    while [ $i -lt $spaces ]; do
        space_str="${space_str} "
        i=$((i + 1))
    done
    
    printf "\r${RED}[${bar_str}${space_str}] ${progress}%%${NC}"
}



# 清理函数
clean_path() {
    local path=$1
    
    if [[ -f "$path" ]]; then
        if rm -f "$path" 2>/dev/null; then
            return 0
        else
            return 2
        fi
    elif [[ -d "$path" ]]; then
        if rm -rf "$path" 2>/dev/null; then
            return 0
        else
            return 2
        fi
    else
        return 1
    fi
}

