# 函数：判断希腊字母
is_greek_char() {
    local char="$1"
    case "$char" in
        [Α-Ωα-ω]) return 0;;
        *) return 1;;
    esac
}

# 函数：统计字符串中的希腊字母个数
count_greek_chars() {
    local input="$1"
    local count=0
    local i=0
    local len=${#input}
    
    while [ $i -lt $len ]; do
        char="${input:$i:1}"
        if is_greek_char "$char"; then
            count=$((count + 1))
        fi
        i=$((i + 1))
    done
    
    echo "$count"
}

# 函数：映射规则，将单个小写拉丁字母转换为希腊字母
map_single_latin_to_greek() {
    local char="$1"
    case "$char" in
        # 仅处理小写拉丁字母 → 希腊小写字母
        a) echo "α";;
        b) echo "β";;
        c) echo "κ";;
        d) echo "δ";;
        e) echo "ε";;
        f) echo "φ";;
        g) echo "γ";;
        h) echo "η";;
        i) echo "ι";;
        j) echo "ι";;
        k) echo "κ";;
        l) echo "λ";;
        m) echo "μ";;
        n) echo "ν";;
        o) echo "ο";;
        p) echo "π";;
        q) echo "κ";;
        r) echo "ρ";;
        s) echo "σ";;
        t) echo "τ";;
        u) echo "υ";;
        v) echo "υ";;
        w) echo "ω";;
        x) echo "χ";;
        y) echo "υ";;
        z) echo "ζ";;

        # 其他字符（包括大写字母）保持不变
        *) echo "$char";;
    esac
}

# 函数：替换成希腊字母（仅替换小写字母）
replace_latin_with_greek_mapping() {
    local input="$1"
    local count="$2"
    local len=${#input}
    chars=()
    is_latin=()
    latin_positions=()
    latin_chars=()

    # 扫描字符串，仅识别小写字母
    i=0
    while [ $i -lt $len ]; do
        char="${input:$i:1}"
        chars+=("$char")
        # 仅识别小写字母，且排除希腊字母
        if echo "$char" | grep -q '[a-z]' && ! is_greek_char "$char"; then
            latin_positions+=("$i")
            latin_chars+=("$char")
        fi
        i=$((i + 1))
    done

    total_latin=${#latin_positions[@]}

    if [ "$total_latin" -eq 0 ]; then
        echo "$input"
        return
    fi

    # 确保不超过可用字母数量
    if [ "$count" -gt "$total_latin" ]; then
        count="$total_latin"
    fi

    # 随机选择指定数量的字母
    selected_indices=()
    i=0
    while [ $i -lt $count ]; do
        idx=$(( RANDOM % total_latin ))
        selected_indices+=("$idx")
        i=$((i + 1))
    done

    # 去重复
    unique_indices=($(echo "${selected_indices[@]}" | tr ' ' '\n' | sort -u | tr '\n' ' '))

    # 构建新字符数组
    new_chars=("${chars[@]}")

    for idx_in_latin in "${unique_indices[@]}"; do
        pos=${latin_positions[$idx_in_latin]}
        old_char=${latin_chars[$idx_in_latin]}

        # 按映射规则替换这个小写字母
        new_char=$(map_single_latin_to_greek "$old_char")
        new_chars[$pos]="$new_char"
    done

    # 拼接成最终字符串
    echo "${new_chars[*]}" | tr -d ' '
}

