        *) return 1;;
    esac
}

# 函数：映射规则，将小写希腊字母还原为小写拉丁字母
map_greek_to_latin() {
    local char="$1"
    case "$char" in
        # 仅处理小写希腊字母 → 小写拉丁字母
        "α") echo "a";;
        "β") echo "b";;
        "κ") echo "c";;
        "δ") echo "d";;
        "ε") echo "e";;
        "φ") echo "f";;
        "γ") echo "g";;
        "η") echo "h";;
        "ι") echo "i";;
        "λ") echo "l";;
        "μ") echo "m";;
        "ν") echo "n";;
        "ο") echo "o";;
        "π") echo "p";;
        "ρ") echo "r";;
        "σ") echo "s";;
        "τ") echo "t";;
        "υ") echo "u";;
        "ω") echo "w";;
        "χ") echo "x";;
        "ζ") echo "z";;

        *) echo "$char";; # 非小写希腊字母保持不变
    esac
}

# 函数：恢复指纹（仅将小写希腊字母还原为小写拉丁字母）
restore_fingerprint() {
    local current_fp="$1"
    local len=${#current_fp}
    local restored_fp=""
    
    i=0
    while [ $i -lt $len ]; do
        char="${current_fp:$i:1}"
        if is_greek_char "$char"; then
            # 仅处理小写希腊字母
            restored_char=$(map_greek_to_latin "$char")
            restored_fp="${restored_fp}${restored_char}"
        else
            # 大写希腊字母和其他字符保持不变
            restored_fp="${restored_fp}${char}"
        fi
        i=$((i+1))
    done
    
    echo "$restored_fp"
}

