            echo "当前tmp的inode号为: $INODE"
 
            # 判断 inode 号是否小于或等于 10000
            if [ "$INODE" -le 10000 ]; then
                echo "无需执行，强制停止。"
                exit 0
            else
                echo "达到执行标准，开始执行。"
                sleep 2
            fi
