    create_low_inode_dir() {
        # 创建新目录
        mkdir -p "${NEW_DIR}"
    
        # 获取目录的inode号
        inode=$(ls -id "${NEW_DIR}" | awk '{print $1}')
    
        # 检查inode是否大于10000
        if [ "$inode" -gt 10000 ]; then
            # 删除目录并返回1表示需要重试
            rm -rf "${NEW_DIR}"
            return 1
        else
            # 返回0表示成功
            return 0
        fi
    }

    # 循环直到找到inode低于10000的目录
    while true; do
        if create_low_inode_dir; then
            break
        fi
    done

    # 删除旧的tmp目录（如果存在）
    rm -rf "${TMP_DIR}"

    # 将新目录重命名为tmp
    mv "${NEW_DIR}" "${TMP_DIR}"

    # 设置权限和所有者
