#!/system/bin/sh
# ============================================
# USB/ADB调试控制器 - 管理工具 
# 作者: Fish)
# 版本: v2.2
# 日期: 2026-03-15
# 免责声明: 本脚本仅供学习交流，使用风险自负，请谨慎操作！
# 功能：管理开机自动关闭/开启USB调试(ADB)
# 机制：通过开启标记（空文件）控制，存在标记则开，不存在标记则关
# 环境：需Root权限(Magisk/KernelSU/APatch)
# 更新：自动探测resetprop路径，适配各类终端环境
# ============================================

VERSION="2.2"
SCRIPT_PATH="/data/adb/service.d/adb-controller.sh"
FLAG_FILE="/data/local/tmp/enable_adb"
LOG_FILE="/data/local/tmp/adb_control.log"
BACKUP_DIR="/data/local/tmp/adb_controller_backup"
LOG_MAX_LINES=200

# 探测 resetprop 可执行路径
# 适配 Magisk / KernelSU / SukiSU / APatch 及各类终端环境
# MT管理器、ZeroTermux 等终端的 su 环境 PATH 可能不含 root 工具目录
RESETPROP=""
find_resetprop() {
    # 1) 已在 PATH 中（开机 service.d 环境通常如此）
    if command -v resetprop >/dev/null 2>&1; then
        RESETPROP="resetprop"
        return
    fi

    # 2) 已知路径逐一检查（覆盖主流 root 方案的各版本）
    for p in \
        /data/adb/ksu/bin/resetprop \
        /data/adb/magisk/resetprop \
        /data/adb/ap/bin/resetprop \
        /data/adb/apatch/resetprop \
        /sbin/resetprop \
        /sbin/.magisk/resetprop \
        /system/bin/resetprop \
        /debug_ramdisk/resetprop; do
        if [ -x "$p" ]; then
            RESETPROP="$p"
            return
        fi
    done

    # 3) Magisk 特殊情况：resetprop 可能是 magisk 主二进制的子命令
    #    某些精简安装下没有 resetprop 符号链接，但 magisk 本体可用
    for magisk_bin in /data/adb/magisk/magisk64 /data/adb/magisk/magisk32 /data/adb/magisk/magisk; do
        if [ -x "$magisk_bin" ]; then
            # 验证 resetprop 子命令是否可用
            if "$magisk_bin" resetprop ro.build.display.id >/dev/null 2>&1; then
                RESETPROP="${magisk_bin} resetprop"
                return
            fi
        fi
    done

    # 4) 兜底搜索（较慢，只在上面都找不到时执行）
    _found=$(find /data/adb -name resetprop -type f -o -name resetprop -type l 2>/dev/null | head -n 1)
    if [ -n "$_found" ] && [ -x "$_found" ]; then
        RESETPROP="$_found"
        return
    fi

    # 5) 均未找到，降级使用 setprop
    RESETPROP="setprop"
}
find_resetprop

check_root() {
    if [ "$(id -u)" -ne 0 ]; then
        echo "错误: 需要Root权限才能运行！"
        echo "请先执行 'su' 切换Root"
        exit 1
    fi
}

# 日志轮转：超过 LOG_MAX_LINES 行时自动截断保留后半部分
trim_log() {
    if [ -f "$LOG_FILE" ]; then
        line_count=$(wc -l < "$LOG_FILE" 2>/dev/null)
        if [ "$line_count" -gt "$LOG_MAX_LINES" ] 2>/dev/null; then
            tail -n $((LOG_MAX_LINES / 2)) "$LOG_FILE" > "${LOG_FILE}.tmp"
            mv "${LOG_FILE}.tmp" "$LOG_FILE"
        fi
    fi
}

# 获取已安装脚本中"关闭分支"的开发者选项配置
# 返回值写入全局变量 INSTALLED_DEV_SETTING（"0" 或 "1"）
# 原理：用唯一注释标记来精确定位关闭分支的那一行，避免误匹配开启分支
get_installed_dev_config() {
    INSTALLED_DEV_SETTING=""
    if [ -f "$SCRIPT_PATH" ]; then
        # 匹配带有 #DISABLE_DEV_CFG 标记的行
        _cfg_line=$(grep '#DISABLE_DEV_CFG' "$SCRIPT_PATH" 2>/dev/null)
        if echo "$_cfg_line" | grep -q "development_settings_enabled 1"; then
            INSTALLED_DEV_SETTING="1"
        else
            INSTALLED_DEV_SETTING="0"
        fi
    fi
}

show_menu() {
    clear
    echo "======================================="
    echo "   USB/ADB调试控制器 v${VERSION}"
    echo "   by Fish  TG: @FCNHPD"
    echo "======================================="
    echo ""
    
    if [ -f "$SCRIPT_PATH" ]; then
