# 功能1: 安装
do_install() {
    echo "正在安装..."
    
    if [ -f "$SCRIPT_PATH" ]; then
        echo -n "已存在,是否覆盖? [y/N]: "
        read confirm
        [ "$confirm" != "y" ] && [ "$confirm" != "Y" ] && { echo "已取消"; return; }
        mkdir -p "$BACKUP_DIR" 2>/dev/null
        cp "$SCRIPT_PATH" "$BACKUP_DIR/backup_$(date +%Y%m%d_%H%M%S).sh" 2>/dev/null
    fi
    
    mkdir -p /data/adb/service.d
    
    echo ""
    echo "选择开发者选项处理方式："
    echo "1) 关闭USB调试(ADB)时隐藏开发者选项（更安全）"
    echo "2) 关闭USB调试(ADB)时保留开发者选项（更方便）"
    echo -n "选择[1-2] (默认1): "
    read choice
    
    [ "$choice" = "2" ] && DEV_SETTING="1" || DEV_SETTING="0"
    
    # 注意：#DISABLE_DEV_CFG 标记用于精确定位关闭分支的配置行
    # do_config 和 do_status 通过此标记来读取/修改配置，避免误匹配开启分支
    cat > "$SCRIPT_PATH" << EOF
#!/system/bin/sh
# ADB控制器 - 开机自动管理USB调试(ADB)状态 v${VERSION}
sleep 60
LOG_FILE="/data/local/tmp/adb_control.log"
[ ! -d "/data/local/tmp" ] && mkdir -p /data/local/tmp
echo "[\$(date)] Script started" >> "\$LOG_FILE"

# 探测 resetprop（开机环境通常在 PATH 中，但保险起见仍做探测）
RESETPROP=""
if command -v resetprop >/dev/null 2>&1; then
    RESETPROP="resetprop"
else
    for p in /data/adb/ksu/bin/resetprop /data/adb/magisk/resetprop /data/adb/ap/bin/resetprop /data/adb/apatch/resetprop /sbin/resetprop /sbin/.magisk/resetprop /system/bin/resetprop; do
        if [ -x "\$p" ]; then RESETPROP="\$p"; break; fi
    done
fi
if [ -z "\$RESETPROP" ]; then
    for mb in /data/adb/magisk/magisk64 /data/adb/magisk/magisk32 /data/adb/magisk/magisk; do
        if [ -x "\$mb" ] && "\$mb" resetprop ro.build.display.id >/dev/null 2>&1; then
            RESETPROP="\$mb resetprop"; break
        fi
    done
fi
[ -z "\$RESETPROP" ] && RESETPROP="setprop"
echo "[\$(date)] Using: \$RESETPROP" >> "\$LOG_FILE"

if [ -f "/data/local/tmp/enable_adb" ]; then
    echo "[\$(date)] Mode: ENABLE ADB" >> "\$LOG_FILE"
    settings put global development_settings_enabled 1
    settings put global adb_enabled 1
    \$RESETPROP persist.sys.usb.config mtp,adb
    \$RESETPROP sys.usb.config mtp,adb
    start adbd 2>/dev/null
    echo "[\$(date)] ADB Enabled" >> "\$LOG_FILE"
else
    echo "[\$(date)] Mode: DISABLE ADB" >> "\$LOG_FILE"
    settings put global adb_enabled 0
    settings put global development_settings_enabled $DEV_SETTING #DISABLE_DEV_CFG

    USB_CONFIG=\$(getprop persist.sys.usb.config)
    NEW_CONFIG=\$(echo "\$USB_CONFIG" | sed 's/,adb//g; s/adb,//g; s/^adb\$//g')
    [ -z "\$NEW_CONFIG" ] && NEW_CONFIG="mtp"

    \$RESETPROP persist.sys.usb.config "\$NEW_CONFIG"
    \$RESETPROP sys.usb.config "\$NEW_CONFIG"
    stop adbd 2>/dev/null

    for PROP in sys.usb.adb.disabled persist.security.adbinput persist.service.adb.enable persist.security.adbinstall; do
        \$RESETPROP "\$PROP" "" 2>/dev/null
    done
    echo "[\$(date)] ADB Disabled" >> "\$LOG_FILE"
fi
exit 0
EOF

    chmod +x "$SCRIPT_PATH"
    
    if [ -x "$SCRIPT_PATH" ]; then
        echo ""
        echo "安装成功!"
        [ "$DEV_SETTING" = "1" ] && echo "配置: 关闭USB调试(ADB)时保留开发者选项" || echo "配置: 关闭USB调试(ADB)时隐藏开发者选项"
        echo "请重启手机生效"
    else
        echo "安装失败"
    fi
}

# 功能2: 卸载(含二级菜单)
do_uninstall() {
    if [ ! -f "$SCRIPT_PATH" ]; then
        echo "控制器未安装"
        echo -n "是否清理可能存在的残留文件? [y/N]: "
        read c
        if [ "$c" = "y" ] || [ "$c" = "Y" ]; then
            rm -f "$FLAG_FILE" "$LOG_FILE" 2>/dev/null
            rm -rf "$BACKUP_DIR" 2>/dev/null
            echo "已清理残留"
        fi
        return
    fi
    
    echo ""
    echo "卸载模式："
    echo "1) 标准卸载 - 删除脚本和标记，保留日志"
    echo "2) 深度清理 - 删除所有文件，纯净无残留（推荐）"
    echo "3) 仅删除标记 - 保留脚本，下次启动走关闭分支"
    echo "0) 取消"
    echo ""
    echo -n "选择[0-3]: "
    read mode
    
    case $mode in
        1)
            rm -f "$SCRIPT_PATH" "$FLAG_FILE"
            echo "已卸载，日志保留在 $LOG_FILE"
            echo "重启后恢复系统默认状态"
            ;;
        2)
            echo ""
            echo "警告：将删除所有相关文件包括日志！"
            echo -n "确认请输入 yes: "
            read confirm
            if [ "$confirm" = "yes" ]; then
                stop adbd 2>/dev/null
                rm -f "$SCRIPT_PATH" "$FLAG_FILE" "$LOG_FILE"
                rm -rf "$BACKUP_DIR"
                echo ""
                echo "深度清理完成："
                [ -f "$SCRIPT_PATH" ] && echo "  ! 主脚本删除失败" || echo "  ✓ 主脚本已删除"
                [ -f "$FLAG_FILE" ] && echo "  ! 开启标记删除失败" || echo "  ✓ 开启标记已删除"
                [ -f "$LOG_FILE" ] && echo "  ! 日志文件删除失败" || echo "  ✓ 日志文件已删除"
                [ -d "$BACKUP_DIR" ] && echo "  ! 备份目录删除失败" || echo "  ✓ 备份目录已删除"
                echo "系统已恢复纯净状态"
            else
                echo "已取消"
            fi
            ;;
        3)
            rm -f "$FLAG_FILE"
            echo "已删除标记（脚本保留，下次启动将走关闭分支）"
            echo "如需彻底卸载，请选标准卸载或深度清理"
            ;;
        0) echo "取消" ;;
        *) echo "无效选择" ;;
    esac
}

# 功能3: 创建开启标记（开启USB调试/ADB）
do_enable() {
    if [ ! -f "$SCRIPT_PATH" ]; then
        echo "请先安装控制器（选项1）"
        return
    fi
    if [ -f "$FLAG_FILE" ]; then
        echo "开启标记已存在，无需重复创建"
        echo "重启后USB调试(ADB)将自动开启"
        return
    fi
    touch "$FLAG_FILE"
    if [ -f "$FLAG_FILE" ]; then
        echo "已创建'开启标记'（空文件）"
        echo "重启后USB调试(ADB)将自动开启"
        echo ""
        echo "提示：也可选择'立即执行测试'(选项7)立即生效，无需重启"
    else
        echo "创建失败，请检查 /data/local/tmp 目录权限"
    fi
}

# 功能4: 删除开启标记（关闭USB调试/ADB）
do_disable() {
    if [ ! -f "$SCRIPT_PATH" ]; then
        echo "控制器未安装，删除标记无意义"
        echo "请先安装控制器（选项1）"
        return
    fi
    if [ ! -f "$FLAG_FILE" ]; then
        echo "已是默认关闭状态，无需操作"
        return
    fi
    rm -f "$FLAG_FILE"
    if [ -f "$FLAG_FILE" ]; then
        echo "删除失败，请检查权限"
    else
        echo "已删除'开启标记'"
        echo "重启后USB调试(ADB)将自动关闭"
    fi
}

# 功能5: 状态
do_status() {
    echo "=== 状态检查 ==="
    echo ""
    
    if [ -f "$SCRIPT_PATH" ]; then
        # 读取已安装脚本中的版本号
        installed_ver=$(grep '# ADB控制器.*v' "$SCRIPT_PATH" 2>/dev/null | sed 's/.*v\([0-9.]*\).*/\1/')
        [ -n "$installed_ver" ] && echo "[*] 控制器: 已安装 (v${installed_ver})" || echo "[*] 控制器: 已安装"
    else
        echo "[*] 控制器: 未安装"
    fi
    echo "[*] 管理工具: v${VERSION}"
    echo "[*] resetprop: $RESETPROP"
    
    if [ -f "$FLAG_FILE" ]; then
        echo "[*] 开启标记: 存在(下次启动将开启USB调试/ADB)"
    else
        echo "[*] 开启标记: 不存在(下次启动将关闭USB调试/ADB)"
    fi
    
    echo ""
    echo "当前系统状态："
    ADB_STATUS=$(settings get global adb_enabled 2>/dev/null)
    DEV_STATUS=$(settings get global development_settings_enabled 2>/dev/null)
    
    [ "$ADB_STATUS" = "1" ] && echo "  USB调试(ADB): 开启" || echo "  USB调试(ADB): 关闭"
    [ "$DEV_STATUS" = "1" ] && echo "  开发者选项: 显示" || echo "  开发者选项: 隐藏"
    
    if [ -f "$SCRIPT_PATH" ]; then
        echo ""
        get_installed_dev_config
        if [ "$INSTALLED_DEV_SETTING" = "1" ]; then
            echo "脚本配置: 关闭USB调试(ADB)时保留开发者选项"
        else
            echo "脚本配置: 关闭USB调试(ADB)时隐藏开发者选项"
        fi
    fi
    
    echo ""
    if [ -f "$LOG_FILE" ]; then
        echo "最近日志（最后3行）："
        tail -n 3 "$LOG_FILE"
    else
        echo "暂无日志记录"
    fi
}

# 功能6: 配置(含二级菜单)
do_config() {
    if [ ! -f "$SCRIPT_PATH" ]; then
        echo "控制器未安装"
        return
    fi
    
    get_installed_dev_config
    echo "当前配置："
    if [ "$INSTALLED_DEV_SETTING" = "1" ]; then
        echo "  关闭USB调试/ADB时：保留开发者选项菜单"
    else
        echo "  关闭USB调试/ADB时：隐藏开发者选项菜单"
    fi
    
    echo ""
    echo "修改为："
    echo "1) 关闭时隐藏开发者选项（更安全，推荐）"
    echo "2) 关闭时保留开发者选项（方便调整其他设置）"
    echo "0) 取消"
    echo -n "选择[0-2]: "
    read cfg
    
    case $cfg in
        1) 
            # 只替换带 #DISABLE_DEV_CFG 标记的行
            sed -i '/#DISABLE_DEV_CFG/s/development_settings_enabled [01]/development_settings_enabled 0/' "$SCRIPT_PATH"
            echo "已修改：下次关闭USB调试(ADB)时将隐藏开发者选项"
            ;;
        2)
            sed -i '/#DISABLE_DEV_CFG/s/development_settings_enabled [01]/development_settings_enabled 1/' "$SCRIPT_PATH"
            echo "已修改：下次关闭USB调试(ADB)时将保留开发者选项"
            ;;
        0) echo "取消" ;;
        *) echo "无效选择" ;;
    esac
    echo ""
    echo "提示：修改将在下次重启后生效（或选'立即执行测试'）"
}

# 功能7: 立即执行（与开机脚本逻辑完全一致）
do_execute() {
    if [ ! -f "$SCRIPT_PATH" ]; then
        echo "控制器未安装"
        return
    fi
    
    echo "正在立即执行（跳过60秒延迟）..."
    if [ "$RESETPROP" = "setprop" ]; then
        echo "注意: 未找到resetprop，使用setprop替代（persist属性可能不持久）"
    else
        echo "工具: $RESETPROP"
    fi
    echo ""
    
    if [ -f "$FLAG_FILE" ]; then
        settings put global development_settings_enabled 1
        settings put global adb_enabled 1
        $RESETPROP persist.sys.usb.config mtp,adb
        $RESETPROP sys.usb.config mtp,adb
        start adbd 2>/dev/null
        echo "✓ 已开启USB调试(ADB)"
        echo "[$(date)] Manual Enable" >> "$LOG_FILE"
    else
        settings put global adb_enabled 0
        
        # 读取配置决定开发者选项处理方式
        get_installed_dev_config
        settings put global development_settings_enabled "$INSTALLED_DEV_SETTING"
        
        # 清理 USB config 中的 adb（与开机脚本一致）
        USB_CONFIG=$(getprop persist.sys.usb.config)
        NEW_CONFIG=$(echo "$USB_CONFIG" | sed 's/,adb//g; s/adb,//g; s/^adb$//g')
        [ -z "$NEW_CONFIG" ] && NEW_CONFIG="mtp"
        $RESETPROP persist.sys.usb.config "$NEW_CONFIG"
        $RESETPROP sys.usb.config "$NEW_CONFIG"
        stop adbd 2>/dev/null
        
        # 清理安全相关属性
        for PROP in sys.usb.adb.disabled persist.security.adbinput persist.service.adb.enable persist.security.adbinstall; do
            $RESETPROP "$PROP" "" 2>/dev/null
        done
        
        echo "✓ 已关闭USB调试(ADB)"
        echo "[$(date)] Manual Disable" >> "$LOG_FILE"
    fi
    
    trim_log
    echo ""
    echo "请检查设置查看实际效果"
}

# 功能8: 清理(含二级菜单)
do_clean() {
    echo "清理选项："
    echo "1) 清空日志文件（释放存储空间）"
    echo "2) 重置所有状态（删除开启标记，立即关闭USB调试(ADB)）"
    echo "3) 清理旧备份文件"
    echo "0) 返回"
    echo -n "选择[0-3]: "
    read c
    
    case $c in
        1)
            if [ -f "$LOG_FILE" ]; then
                size=$(ls -lh "$LOG_FILE" 2>/dev/null | awk '{print $5}')
                lines=$(wc -l < "$LOG_FILE" 2>/dev/null)
                echo "当前日志: ${size}, ${lines} 行"
                echo -n "确认清空? [y/N]: "
                read confirm
                if [ "$confirm" = "y" ] || [ "$confirm" = "Y" ]; then
                    > "$LOG_FILE"
                    echo "[$(date)] Log cleaned by user" >> "$LOG_FILE"
                    echo "日志已清空"
                fi
            else
                echo "无日志文件"
            fi
            ;;
        2)
            echo "此操作将："
            echo "  - 删除开启标记（空文件）"
            echo "  - 立即关闭USB调试(ADB)（无需重启）"
            echo -n "确认? [y/N]: "
            read confirm
            if [ "$confirm" = "y" ] || [ "$confirm" = "Y" ]; then
                rm -f "$FLAG_FILE"
                settings put global adb_enabled 0 2>/dev/null
                stop adbd 2>/dev/null
                echo "已重置为默认关闭状态"
                echo "下次重启后ADB将保持关闭"
            fi
            ;;
        3)
            if [ -d "$BACKUP_DIR" ]; then
                count=$(find "$BACKUP_DIR" -maxdepth 1 -type f -name '*.sh' 2>/dev/null | wc -l)
                if [ "$count" -gt 0 ]; then
                    echo "发现 $count 个备份"
                    echo -n "删除除最新外的所有备份? [y/N]: "
                    read confirm
                    if [ "$confirm" = "y" ] || [ "$confirm" = "Y" ]; then
                        # 安全删除：用 find + sort 避免文件名空格问题
                        ls -1t "$BACKUP_DIR"/*.sh 2>/dev/null | tail -n +2 | while IFS= read -r f; do
                            rm -f "$f"
                        done
                        echo "旧备份已清理"
                    fi
                else
                    echo "无备份文件"
                fi
            else
                echo "无备份目录"
            fi
            ;;
        0) ;;
        *) echo "无效选择" ;;
    esac
}

