 #!/bin/sh

# 颜色支持（仅在终端时启用）
if [ -t 1 ]; then
    RED='\033[0;31m'
    YELLOW='\033[0;33m'
    BLUE='\033[0;34m'
    NC='\033[0m'
else
    RED=''
    YELLOW=''
    BLUE=''
    NC=''
fi

TMPDIR=""

cleanup() {
    [ -n "$TMPDIR" ] && [ -d "$TMPDIR" ] && rm -rf "$TMPDIR"
}
trap cleanup EXIT INT TERM

usage() {
    printf "用法: %s <文件路径(.zip 或 .sh)>\n" "$0"
    exit 1
}

check_cmd() {
    command -v "$1" >/dev/null 2>&1
}

is_shell_script() {
    f="$1"
    case "$f" in
        *.sh) return 0 ;;
    esac
    head -1 "$f" 2>/dev/null | grep -Eq '^#!\s*/.*sh'
}

create_tmpdir() {
    TMPDIR=$(mktemp -d 2>/dev/null) || TMPDIR=$(mktemp -d /tmp/magiskcheck.XXXXXX 2>/dev/null)
    if [ -z "$TMPDIR" ] || [ ! -d "$TMPDIR" ]; then
        printf "${RED}错误: 无法创建临时目录${NC}\n" >&2
        exit 1
    fi
}

check_archive_path_safety() {
    archive="$1"
    case "$archive" in
        *.zip)
            check_cmd unzip && unzip -l "$archive" 2>/dev/null | awk 'NF>=4 {for(i=4;i<=NF;i++) printf "%s ", $i; print ""}' | grep -Eq '(^|\s)/|[.][.]/' && return 1
            ;;
        *.tar|*.tar.gz|*.tgz|*.tar.bz2|*.tbz2|*.tar.xz|*.txz)
            check_cmd tar && tar -tf "$archive" 2>/dev/null | grep -Eq '(^|\s)/|[.][.]/' && return 1
            ;;
        *.7z)
            check_cmd 7z && 7z l "$archive" 2>/dev/null | grep -Eq '(^|\s)/|[.][.]/' && return 1
            ;;
        *.rar)
            check_cmd unrar && unrar l "$archive" 2>/dev/null | grep -Eq '(^|\s)/|[.][.]/' && return 1
            ;;
    esac
    return 0
}

unzip_safe() {
    out=$(unzip -o "$1" -d "$2" 2>&1) || {
        if echo "$out" | grep -qi "incorrect password\|password required\|password\|encrypted"; then
            printf "${RED}警告: %s 有密码保护，跳过${NC}\n" "$1"
            return 2
        else
            printf "${RED}解压失败: %s${NC}\n" "$out"
            return 1
        fi
    }
    return 0
}

extract_recursive() {
    basedir="$1"
    _filelist=$(mktemp /tmp/extract_list.XXXXXX) || return
    find "$basedir" -type f \( -iname "*.zip" -o -iname "*.tar" -o -iname "*.tar.gz" \
        -o -iname "*.tgz" -o -iname "*.tar.bz2" -o -iname "*.tbz2" \
        -o -iname "*.tar.xz" -o -iname "*.txz" -o -iname "*.7z" -o -iname "*.rar" \) > "$_filelist"

    while IFS= read -r archive; do
        [ -f "$archive" ] || continue
        printf "正在解压: %s\n" "$archive"

        if ! check_archive_path_safety "$archive"; then
            printf "${RED}安全警告: %s 包含路径穿越（..）或绝对路径，跳过！${NC}\n" "$archive"
            continue
        fi

        dir="${archive%.*}"
        mkdir -p "$dir" || continue

        case "$archive" in
            *.zip)
                unzip_safe "$archive" "$dir" && rm -f "$archive"
                ;;
            *.tar|*.tar.gz|*.tgz|*.tar.bz2|*.tbz2|*.tar.xz|*.txz)
                if tar -xf "$archive" -C "$dir" 2>&1 | grep -qi "encrypted\|password"; then
                    printf "${RED}警告: %s 可能加密，跳过${NC}\n" "$archive"
                else
                    rm -f "$archive"
                fi
                ;;
            *.7z)
                if check_cmd 7z; then
                    if 7z x "$archive" -o"$dir" -y 2>&1 | grep -qi "password\|encrypted"; then
                        printf "${RED}警告: %s 有密码，跳过${NC}\n" "$archive"
                    else
                        rm -f "$archive"
                    fi
                else
                    printf "${YELLOW}未找到7z命令，跳过: %s${NC}\n" "$archive"
                fi
                ;;
            *.rar)
                if check_cmd unrar; then
                    if unrar x "$archive" "$dir/" 2>&1 | grep -qi "password\|encrypted"; then
                        printf "${RED}警告: %s 有密码，跳过${NC}\n" "$archive"
                    else
                        rm -f "$archive"
                    fi
                else
                    printf "${YELLOW}未找到unrar命令，跳过: %s${NC}\n" "$archive"
                fi
                ;;
        esac
        extract_recursive "$dir"
    done < "$_filelist"
    rm -f "$_filelist"
}

# ================= 直接危险命令检测 =================
check_dangerous() {
    printf "${BLUE}==================== 直接危险命令检测 ====================${NC}\n"
    _filelist=$(mktemp /tmp/danger_files.XXXXXX) || return
    find "$TMPDIR" -type f > "$_filelist"
    found=0

    while IFS= read -r f; do
        [ -r "$f" ] || continue
        is_shell_script "$f" || continue

        matches=$(grep -n -a -E \
            '\brm\b|\bdd[[:space:]]+if\b|\bcat\b|\becho\b|\bcp\b|\bmv\b|\beval\b|\bexec\b' \
            "$f" 2>/dev/null)

        if [ -n "$matches" ]; then
            found=1
            total_lines=$(echo "$matches" | wc -l)
            rel=$(echo "$f" | sed "s|^$TMPDIR/||")
            printf "文件: ./%s (危险命令匹配 %s 处)\n" "$rel" "$total_lines"

            destructive=$(echo "$matches" | grep -E 'rm[[:space:]]+-rf|dd[[:space:]]+if' | head -n 3)
            [ -n "$destructive" ] && echo "$destructive" | while IFS= read -r line; do
                printf "  ${RED}%s${NC}\n" "$line"
            done

            normal=$(echo "$matches" | grep -vE 'rm[[:space:]]+-rf|dd[[:space:]]+if' | head -n 3)
            [ -n "$normal" ] && echo "$normal" | while IFS= read -r line; do
                printf "  %s\n" "$line"
            done

            if [ "$total_lines" -gt 3 ]; then
                printf "  ... 共 %s 条匹配，已截断显示\n" "$total_lines"
            fi
            printf "  ${YELLOW}请审计以上代码是否合理${NC}\n"
        fi
    done < "$_filelist"
    rm -f "$_filelist"

    if [ $found -eq 0 ]; then
        printf "未检测到直接危险命令。\n"
    fi
}

# ================= 混淆危险命令检测（修复 found 传递） =================
check_obfuscated_dangerous() {
    printf "${BLUE}==================== 混淆危险命令检测 ====================${NC}\n"
    _filelist=$(mktemp /tmp/obf_danger_files.XXXXXX) || return
    find "$TMPDIR" -type f > "$_filelist"
    _obf_flag=$(mktemp /tmp/obf_found.XXXXXX)   # 标志文件，只要非空就代表发现过

    while IFS= read -r f; do
        [ -r "$f" ] || continue
        is_shell_script "$f" || continue

        rel=$(echo "$f" | sed "s|^$TMPDIR/||")

        # ---- 预处理：提取本文件中的简单变量赋值 ----
        tmpvars=$(mktemp /tmp/vars.XXXXXX)
        grep -E '^[[:space:]]*[a-zA-Z_][a-zA-Z0-9_]*=".*"$' "$f" > "$tmpvars" 2>/dev/null
        grep -E '^[[:space:]]*[a-zA-Z_][a-zA-Z0-9_]*='"'"'.*'"'"'$' "$f" >> "$tmpvars" 2>/dev/null
        grep -E '^[[:space:]]*[a-zA-Z_][a-zA-Z0-9_]*=[^"'"'"'[:space:]]+$' "$f" >> "$tmpvars" 2>/dev/null

        # ---- 1. 直接 Base64 长字符串解码执行 ----
        lines_b64=$(grep -n -E 'base64.*-[dD].*(\\|.*(sh|bash|eval|source))' "$f" 2>/dev/null || true)
        if [ -n "$lines_b64" ]; then
            echo "$lines_b64" | while IFS= read -r line; do
                lineno=$(echo "$line" | cut -d: -f1)
                content=$(echo "$line" | cut -d: -f2-)
                b64=$(echo "$content" | grep -oE '[A-Za-z0-9+/=]{20,}' | tail -1)
                if [ -n "$b64" ]; then
                    decoded=$(echo "$b64" | base64 -d 2>/dev/null)
                    if [ -n "$decoded" ] && echo "$decoded" | grep -qE '\brm\b|\bdd\b|\bcat\b|\becho\b|\bcp\b|\bmv\b|\beval\b|\bexec\b'; then
                        echo 1 >> "$_obf_flag"
                        printf "${RED}检测到 Base64 混淆的危险命令：${NC}\n"
                        printf "文件: ./%s 行 %s\n" "$rel" "$lineno"
                        printf "  原始行: %s\n" "$content"
                        printf "  解码后: %s\n" "$decoded"
                        printf "  ${YELLOW}请审计！${NC}\n"
                    fi
                fi
            done
        fi

        # ---- 2. 变量拼接 Base64 解码执行 ----
        lines_mix=$(grep -n -E 'base64.*-[dD]' "$f" | grep -E 'eval|sh |bash|source' || true)
        if [ -n "$lines_mix" ] && [ -s "$tmpvars" ]; then
            echo "$lines_mix" | while IFS= read -r line; do
                lineno=$(echo "$line" | cut -d: -f1)
                content=$(echo "$line" | cut -d: -f2-)
                echo_part=$(echo "$content" | sed -n 's/.*echo[[:space:]]\+\([^|]*\)[[:space:]]*|.*base64.*/\1/p')
                [ -z "$echo_part" ] && echo_part=$(echo "$content" | sed -n 's/.*printf[[:space:]]\+[^ ]*[[:space:]]\+\([^|]*\)[[:space:]]*|.*base64.*/\1/p')
                [ -z "$echo_part" ] && continue
                echo_part=$(echo "$echo_part" | sed -e 's/^"//' -e 's/"$//' -e "s/^'//" -e "s/'$//")
                expanded=$(echo "$echo_part" | awk -F= '
                    NR==FNR {
                        gsub(/"/, "", $2); gsub(/'"'"'/, "", $2)
                        vars[$1]=$2; next
                    }
                    {
                        for (v in vars) {
                            gsub("\\$\\{" v "\\}", vars[v])
                            gsub("\\$" v, vars[v])
                        }
                        print
                    }
                ' "$tmpvars" - 2>/dev/null)
                [ -z "$expanded" ] && continue
                decoded=$(echo "$expanded" | base64 -d 2>/dev/null)
                if [ -n "$decoded" ] && echo "$decoded" | grep -qE '\brm\b|\bdd\b|\bcat\b|\becho\b|\bcp\b|\bmv\b|\beval\b|\bexec\b'; then
                    echo 1 >> "$_obf_flag"
                    printf "${RED}检测到变量拼接 Base64 混淆的危险命令：${NC}\n"
                    printf "文件: ./%s 行 %s\n" "$rel" "$lineno"
                    printf "  原始行: %s\n" "$content"
                    printf "  拼接后 Base64: %s\n" "$expanded"
                    printf "  解码后: %s\n" "$decoded"
                    printf "  ${YELLOW}请审计！${NC}\n"
                fi
            done
        fi

        # ---- 3. 十六进制转义混淆 ----
        hex_lines=$(grep -n -a -E '(\\x[0-9a-fA-F]{2}[[:space:]]*){2,}' "$f" 2>/dev/null)
        if [ -n "$hex_lines" ]; then
            echo "$hex_lines" | while IFS= read -r line; do
                content=$(echo "$line" | sed 's/^[0-9]*://')
                hex_seq=$(echo "$content" | grep -oE '\\x[0-9a-fA-F]{2}' | tr -d '\\x' | tr '\n' ' ' | sed 's/ //g')
                printf_arg=""
                i=1
                while [ $i -le ${#hex_seq} ]; do
                    byte=$(echo "$hex_seq" | cut -c$i-$((i+1)))
                    printf_arg="$printf_arg\\x$byte"
                    i=$((i+2))
                done
                decoded=$(printf "%b" "$printf_arg" 2>/dev/null)
                if [ -n "$decoded" ] && echo "$decoded" | grep -qE '\brm\b|\bdd\b|\bcat\b|\becho\b|\bcp\b|\bmv\b|\beval\b|\bexec\b'; then
                    echo 1 >> "$_obf_flag"
                    printf "${RED}检测到十六进制转义混淆的危险命令：${NC}\n"
                    printf "文件: ./%s 行 %s\n" "$rel" "$(echo "$line" | cut -d: -f1)"
                    printf "  原始行: %s\n" "$content"
                    printf "  解码后: %s\n" "$decoded"
                    printf "  ${YELLOW}请审计！${NC}\n"
                fi
            done
        fi

        # ---- 4. xxd / hexdump 还原执行 ----
        xxd_lines=$(grep -n -E '(xxd|hexdump).*-[rR].*\|.*(sh|bash|eval|source)' "$f" 2>/dev/null)
        if [ -n "$xxd_lines" ]; then
            echo "$xxd_lines" | while IFS= read -r line; do
                echo 1 >> "$_obf_flag"
                printf "${RED}检测到通过 xxd/hexdump 还原并执行的可疑模式：${NC}\n"
                printf "文件: ./%s\n" "$rel"
                printf "  %s\n" "$line"
                printf "  ${YELLOW}请审计！${NC}\n"
            done
        fi

        rm -f "$tmpvars"
    done < "$_filelist"

    # 最后判断是否有任何发现
    if [ ! -s "$_obf_flag" ]; then
        printf "未检测到混淆的危险命令。\n"
    fi

    rm -f "$_filelist" "$_obf_flag"
}

# ================= 主程序 =================
printf "恶意Magisk模块/脚本检测 (含混淆危险命令)\n"
printf "=========================================\n"

if [ $# -ge 1 ]; then
    FILE="$1"
else
    printf "请输入要检测的文件路径(.zip 或 .sh): "
    read -r FILE
fi

[ -f "$FILE" ] || { printf "${RED}错误: 文件不存在${NC}\n"; exit 1; }

# 获取文件扩展名（小写）
ext=$(echo "$FILE" | awk -F . '{print tolower($NF)}')

case "$ext" in
    sh)
        create_tmpdir
        printf "临时目录: %s\n" "$TMPDIR"
        printf "正在复制脚本: %s\n" "$FILE"
        cp "$FILE" "$TMPDIR/" || { printf "${RED}错误: 无法复制脚本文件${NC}\n"; exit 1; }
        ;;
    zip)
        if ! check_cmd unzip; then
            printf "${RED}错误: 未找到 unzip 命令，无法解压 zip 文件。${NC}\n"
            exit 1
        fi
        create_tmpdir
        printf "临时目录: %s\n" "$TMPDIR"

        if ! check_archive_path_safety "$FILE"; then
            printf "${RED}错误: 主模块包含危险路径（.. 或绝对路径），拒绝解压。${NC}\n"
            exit 1
        fi

        printf "正在解压主模块: %s\n" "$FILE"
        unzip_output=$(unzip -o "$FILE" -d "$TMPDIR" 2>&1)
        unzip_ret=$?

        if echo "$unzip_output" | grep -qi "incorrect password\|password required\|password\|encrypted"; then
            printf "${RED}错误: zip文件有密码保护，本脚本只检测无密码模块。${NC}\n"
            exit 1
        fi

        if [ $unzip_ret -ne 0 ]; then
            printf "${RED}解压失败：unzip 返回错误码 %d${NC}\n" $unzip_ret
            printf "${RED}unzip 输出如下:${NC}\n%s\n" "$unzip_output"
            exit 1
        fi

        if ! ls -A "$TMPDIR" >/dev/null 2>&1; then
            printf "${RED}解压失败：临时目录为空。${NC}\n"
            printf "${RED}unzip 输出如下:${NC}\n%s\n" "$unzip_output"
            exit 1
        fi

        printf "正在递归解压内部压缩文件...\n"
        extract_recursive "$TMPDIR"
        ;;
    *)
        printf "${RED}错误: 不支持的文件格式，请提供 .zip 或 .sh 文件。${NC}\n"
        exit 1
        ;;
esac

printf "解压/复制后的文件数量: "
find "$TMPDIR" -type f | wc -l

# 执行检测
check_dangerous
check_obfuscated_dangerous 
                      
        ;;       
            
        "改机型脚本")            

