if command -v curl >/dev/null 2>&1; then
    curl -s -L -o "$LIST_FILE" "$API_URL"
elif command -v wget >/dev/null 2>&1; then
    wget -q -O "$LIST_FILE" "$API_URL"
else
    echo "错误：未找到 curl 或 wget"
    exit 1
fi

if [ ! -s "$LIST_FILE" ]; then
    echo "错误：模块列表获取失败"
    exit 1
fi

ROOT_TYPE=""
ROOT_BIN=""

for p in \
    /sbin/magisk \
    /debug_ramdisk/magisk \
    /data/adb/magisk/magisk \
    /system/bin/magisk \
    /system/xbin/magisk
do
    if [ -x "$p" ]; then
        ROOT_TYPE="magisk"
        ROOT_BIN="$p"
        break
    fi
done

if [ -z "$ROOT_BIN" ] && command -v magisk >/dev/null 2>&1; then
    ROOT_TYPE="magisk"
    ROOT_BIN="$(command -v magisk)"
fi

if [ -z "$ROOT_BIN" ]; then
    for p in \
        /data/adb/ksud \
        /system/bin/ksud \
        /system/xbin/ksud
    do
        if [ -x "$p" ]; then
            ROOT_TYPE="ksu"
            ROOT_BIN="$p"
            break
        fi
    done
fi

if [ -z "$ROOT_BIN" ] && command -v ksud >/dev/null 2>&1; then
    ROOT_TYPE="ksu"
    ROOT_BIN="$(command -v ksud)"
fi

if [ -z "$ROOT_BIN" ]; then
    for p in \
        /data/adb/ap/bin/apd \
        /data/adb/apd \
        /system/bin/apd \
        /system/xbin/apd
    do
        if [ -x "$p" ]; then
            ROOT_TYPE="apatch"
            ROOT_BIN="$p"
            break
        fi
    done
fi

if [ -z "$ROOT_BIN" ] && command -v apd >/dev/null 2>&1; then
    ROOT_TYPE="apatch"
    ROOT_BIN="$(command -v apd)"
fi

if [ -z "$ROOT_BIN" ]; then
    echo "错误：未检测到 Magisk / KernelSU / APatch"
    echo "请确认已获取 root 后再执行：su"
    exit 1
fi

install_module() {
    zip_file="$1"

    case "$ROOT_TYPE" in
        magisk)
            "$ROOT_BIN" --install-module "$zip_file"
            ;;
        ksu)
            "$ROOT_BIN" module install "$zip_file"
            ;;
        apatch)
            "$ROOT_BIN" module install "$zip_file"
            ;;
        *)
            echo "未知 Root 管理器：$ROOT_TYPE"
            return 1
            ;;
    esac
}

download_file() {
    url="$1"
    out="$2"

    if command -v curl >/dev/null 2>&1; then
        curl -s -L -o "$out" "$url"
    else
        wget -q -O "$out" "$url"
    fi
}

after_install_menu() {
    while true; do
        echo ""
        echo "安装完成，建议重启设备。"
        echo "1. 立即重启"
        echo "2. 暂不重启"
        echo "0. 退出"
        echo "------------------------"
        echo -n "请选择："
        read r

        case "$r" in
            1)
                reboot
                exit 0
                ;;
            2|0)
                echo "已退出，请稍后手动重启。"
                exit 0
                ;;
            *)
                echo "输入无效"
                ;;
        esac
    done
}

download_and_install() {
    name="$1"
    url="$2"

    filename=$(basename "$url")
    zip_path="$TMP_DIR/$filename"

    while true; do
        echo ""
        echo "你选择了：$name"
        echo "1. 确认安装"
        echo "b. 返回"
        echo "0. 退出"
        echo "------------------------"
        echo -n "请选择："
        read c

        case "$c" in
            1)
                break
                ;;
            b|B)
                return 2
                ;;
            0)
                echo "已退出"
                exit 0
                ;;
            *)
                echo "输入无效"
                ;;
        esac
    done

    echo ""
    echo "正在下载：$filename"
    rm -f "$zip_path"

    download_file "$url" "$zip_path"

    if [ ! -s "$zip_path" ]; then
        echo "下载失败：$filename"
        return 1
    fi

    echo "正在刷入：$filename"

    install_module "$zip_path"

    if [ "$?" -eq 0 ]; then
        echo "安装成功：$filename"
        after_install_menu
    else
        echo "安装失败：$filename"
        return 1
    fi
}

build_main_menu() {
    grep -E '^(SINGLE|CATEGORY)	' "$LIST_FILE" > "$MAIN_MENU"
}

show_main_menu() {
    build_main_menu

    COUNT=$(wc -l < "$MAIN_MENU" | tr -d ' ')

    if [ "$COUNT" -eq 0 ]; then
        echo "没有找到任何模块"
        exit 1
    fi

    while true; do
        echo ""
        echo "可用模块列表："
        echo "------------------------"

        i=1
        while IFS="$(printf '\t')" read -r type name url; do
            if [ "$type" = "CATEGORY" ]; then
                echo "$i. $name/"
            else
                echo "$i. $name"
            fi
            i=$((i + 1))
        done < "$MAIN_MENU"

        echo "------------------------"
        echo "0. 退出"
        echo "------------------------"
        echo -n "请输入序号："
        read CHOICE

        case "$CHOICE" in
            0)
                echo "已退出"
                exit 0
                ;;
            ''|*[!0-9]*)
                echo "输入无效"
                continue
                ;;
        esac

        if [ "$CHOICE" -lt 1 ] || [ "$CHOICE" -gt "$COUNT" ]; then
            echo "序号超出范围"
            continue
        fi

        SELECTED_LINE=$(sed -n "${CHOICE}p" "$MAIN_MENU")
        TYPE=$(echo "$SELECTED_LINE" | cut -f1)
        NAME=$(echo "$SELECTED_LINE" | cut -f2)
        URL=$(echo "$SELECTED_LINE" | cut -f3-)

        if [ "$TYPE" = "SINGLE" ]; then
            download_and_install "$NAME" "$URL"
        elif [ "$TYPE" = "CATEGORY" ]; then
            show_sub_menu "$NAME"
        fi
    done
}

show_sub_menu() {
    category="$1"

    grep "^MODULE	$category	" "$LIST_FILE" > "$SUB_MENU"

    SUB_COUNT=$(wc -l < "$SUB_MENU" | tr -d ' ')

    if [ "$SUB_COUNT" -eq 0 ]; then
        echo "该分类下没有模块"
        return
    fi

    while true; do
        echo ""
        echo "分类：$category"
        echo "------------------------"

        i=1
        while IFS="$(printf '\t')" read -r type cat modname modurl; do
            echo "$i. $modname"
            i=$((i + 1))
        done < "$SUB_MENU"

        echo "------------------------"
        echo "b. 返回上一级"
        echo "0. 退出"
        echo "------------------------"
        echo -n "请输入要安装的模块序号："
        read SUB_CHOICE

        case "$SUB_CHOICE" in
            b|B)
                return
                ;;
            0)
                echo "已退出"
                exit 0
                ;;
            ''|*[!0-9]*)
                echo "输入无效"
                continue
                ;;
        esac

        if [ "$SUB_CHOICE" -lt 1 ] || [ "$SUB_CHOICE" -gt "$SUB_COUNT" ]; then
            echo "序号超出范围"
            continue
        fi

        SUB_SELECTED=$(sed -n "${SUB_CHOICE}p" "$SUB_MENU")
        MOD_NAME=$(echo "$SUB_SELECTED" | cut -f3)
        MOD_URL=$(echo "$SUB_SELECTED" | cut -f4-)

        download_and_install "$MOD_NAME" "$MOD_URL"

        ret=$?
        if [ "$ret" = "2" ]; then
            continue
        fi
    done
}

