#!/system/bin/sh
# KernelSU 专属 /data/local/tmp 伪装脚本 v4.0
# 核心目标：inode=1 + 权限771 + 属主shell:shell + 修复时间 + KSU开机自启
# 原理：tmpfs 挂载，inode 从1开始分配，100%稳定，无循环卡死

# 核心路径与配置
TMP_PATH="/data/local/tmp"
FAKE_TMP="/data/local/fake_tmp"
AUTOSTART_SCRIPT="/data/adb/service.d/00_tmp_fake.sh"
TARGET_PERM="771"
TARGET_OWNER="shell:shell"

# 彩色输出函数
red_echo() { echo -e "\033[31m$1\033[0m"; }
green_echo() { echo -e "\033[32m$1\033[0m"; }
yellow_echo() { echo -e "\033[33m$1\033[0m"; }
blue_echo() { echo -e "\033[36m$1\033[0m"; }

# 检查Root权限
check_root() {
    if [ $(id -u) -ne 0 ]; then
        red_echo "❌ 错误：请使用ROOT权限运行此脚本！"
        exit 1
    fi
}

echo  核心目标：inode=1 + 权限771 + 属主shell:shell + 修复时间 + KSU开机自启
echo  原理：tmpfs 挂载，inode 从1开始分配，100%稳定，无循环卡死

# 1. 强制终止占用 + 卸载挂载（解决Device busy）
stop_occupy() {
    yellow_echo "[1/4] 终止$TMP_PATH进程占用并卸载挂载..."
    lsof $TMP_PATH | awk 'NR>1 {print $2}' | xargs kill -9 2>/dev/null
    fuser -k $TMP_PATH 2>/dev/null
    umount -l $TMP_PATH 2>/dev/null
}

# 2. 挂载tmpfs（inode必为1）+ 配置权限771 + 属主shell
mount_tmpfs() {
    yellow_echo "[2/4] 挂载tmpfs（inode=1）并配置权限$TARGET_PERM、属主$TARGET_OWNER..."
    mkdir -p $FAKE_TMP
    # 挂载tmpfs，第一个目录inode固定为1，100%成功
    mount -t tmpfs tmpfs $TMP_PATH
    # 按要求设置权限771
    chmod $TARGET_PERM $TMP_PATH
    # 按要求设置属主shell:shell
    chown $TARGET_OWNER $TMP_PATH
}

# 3. 全项验证（inode=1 + 权限771 + 属主shell）
verify_all() {
    yellow_echo "[3/4] 全项验证配置结果..."
    FINAL_INODE=$(ls -id $TMP_PATH | awk '{print $1}')
    FINAL_PERM=$(stat -c "%a" $TMP_PATH 2>/dev/null || stat -f "%Lp" $TMP_PATH)
    FINAL_OWNER=$(stat -c "%U:%G" $TMP_PATH 2>/dev/null || stat -f "%Su:%Sg" $TMP_PATH)

    if [ "$FINAL_INODE" -eq 1 ] && [ "$FINAL_PERM" = "$TARGET_PERM" ] && [ "$FINAL_OWNER" = "$TARGET_OWNER" ]; then
        green_echo "✅ 全项验证通过！"
        blue_echo "📌 inode：$FINAL_INODE（目标：1）"
        blue_echo "📌 权限：$FINAL_PERM（目标：$TARGET_PERM）"
        blue_echo "📌 属主：$FINAL_OWNER（目标：$TARGET_OWNER）"
        blue_echo "📌 by.fish"
    else
        red_echo "❌ 验证失败！"
        red_echo "📌 实际inode：$FINAL_INODE（目标：1）"
        red_echo "📌 实际权限：$FINAL_PERM（目标：$TARGET_PERM）"
        red_echo "📌 实际属主：$FINAL_OWNER（目标：$TARGET_OWNER）"
        exit 1
    fi
}

# 4. 创建KSU开机自启脚本（重启自动恢复，永久生效）
create_autostart() {
    yellow_echo "[4/4] 配置KSU开机自启（重启不失效）..."
    cat > $AUTOSTART_SCRIPT << 'EOF'
#!/system/bin/sh
# KSU 开机自动恢复 /data/local/tmp 配置（inode=1+771+shell）
# 制作作者：爱你么么哒qcjl哟（酷安ID）
TMP_PATH="/data/local/tmp"
FAKE_TMP="/data/local/fake_tmp"
TARGET_PERM="771"
TARGET_OWNER="shell:shell"

# 延迟5秒，等待系统启动完成
sleep 5

# 终止占用+卸载
lsof $TMP_PATH | awk 'NR>1 {print $2}' | xargs kill -9 2>/dev/null
fuser -k $TMP_PATH 2>/dev/null
umount -l $TMP_PATH 2>/dev/null

# 挂载tmpfs（inode=1）+ 配置权限/属主
mkdir -p $FAKE_TMP
mount -t tmpfs tmpfs $TMP_PATH
chmod $TARGET_PERM $TMP_PATH
chown $TARGET_OWNER $TMP_PATH
EOF
    chmod 0755 $AUTOSTART_SCRIPT
    green_echo "✅ 开机自启脚本已创建：$AUTOSTART_SCRIPT"
}

# 主执行流程
main() {
    clear
    blue_echo "========================"
    blue_echo "KSU TMP 伪装脚本"
    blue_echo "核心目标：inode=1 | 权限771 | 属主shell"
    blue_echo ""
    blue_echo "========================\n"
    check_root
    stop_occupy
    mount_tmpfs
    verify_all
    create_autostart
    echo -e "\n\033[32m========================"
    green_echo "✅ 所有操作执行完成！"
    blue_echo "📌 验证inode：ls -id $TMP_PATH"
    blue_echo "📌 验证权限/属主：ls -ld $TMP_PATH"
    blue_echo "📌 by.fish"
    green_echo "========================\033[0m"
}

# 启动脚本
main
exit 0


 
