#!/system/bin/sh



# 配色
GREEN="\033[1;32m"
RED="\033[1;31m"
YELLOW="\033[1;33m"
CYAN="\033[1;36m"
BLUE="\033[1;34m"
PURPLE="\033[1;35m"
BOLD="\033[1m"
RESET="\033[0m"
DIM="\033[2m"
LINE="${BLUE}------------------------------------------------${RESET}"

# 辅助函数
path_exists() { [ -e "$1" ] 2>/dev/null; }
csv_has() { [ -n "$1" ] && echo ",$1," | grep -q ",$2,"; }

# 清屏
clear

# 头部
echo -e "\n${CYAN}${BOLD}     Fish的环境检测工具 v1.0${RESET}"
echo -e "${BLUE}--------------------------------------------------${RESET}"
echo -e "${YELLOW} 设备:${RESET} $(getprop ro.product.model 2>/dev/null || echo "未知")"
echo -e "${YELLOW} 系统:${RESET} Android $(getprop ro.build.version.release 2>/dev/null || echo "未知")"
echo -e "${LINE}\n"

# ========== 检测函数 ==========

detect_root() {
    if [ "$(id -u)" -eq 0 ]; then
        echo "${RED}✗ 已Root (当前Shell)${RESET}"
        return 1
    fi
    if command -v su >/dev/null 2>&1 && su -c id 2>/dev/null | grep -q "uid=0"; then
        echo "${RED}✗ 已Root (su命令可用)${RESET}"
        return 1
    fi
    echo "${GREEN}✓ 未检测到Root${RESET}"
    return 0
}

detect_bl() {
    local unlock=0 lock=0
    local props="ro.boot.verifiedbootstate ro.boot.flash.locked ro.boot.vbmeta.device_state"
    for p in $props; do
        val=$(getprop "$p" 2>/dev/null)
        case "$val" in
            orange|yellow|0|unlocked) unlock=$((unlock+1)) ;;
            green|1|locked) lock=$((lock+1)) ;;
        esac
    done
    if [ $unlock -gt $lock ]; then
        echo "${RED}🔓 已解锁${RESET}"
        return 1
    elif [ $lock -gt $unlock ]; then
        echo "${GREEN}🔒 已锁定${RESET}"
        return 0
    else
        echo "${RED}❓ 无法判断${RESET}"
        return 1
    fi
}

detect_mt2_folder() {
    if path_exists "/storage/emulated/0/MT2"; then
        echo "${RED}⚠ 检测到MT2文件夹 (/storage/emulated/0/MT2)${RESET}"
        return 1
    else
        echo "${GREEN}✓ 未检测到MT2文件夹${RESET}"
        return 0
    fi
}

detect_mt_manager() {
    local pkgs="bin.mt.plus bin.mt.plus.canary"
    for p in $pkgs; do
        if path_exists "/storage/emulated/0/Android/data/$p"; then
            echo "${RED}⚠ 检测到MT管理器 (/storage/emulated/0/Android/data/$p)${RESET}"
            return 1
        fi
        if command -v pm >/dev/null 2>&1 && pm list packages 2>/dev/null | grep -q "^package:$p$"; then
            echo "${RED}⚠ 检测到MT管理器 (已安装: $p)${RESET}"
            return 1
        fi
    done
    echo "${GREEN}✓ 未检测到MT管理器${RESET}"
    return 0
}

