detect_tampered_attestation() {
    fp=$(getprop ro.build.fingerprint 2>/dev/null)
    if echo "$fp" | grep -q '[Α-Ωα-ω]'; then
        echo "${RED}⚠ 检测到指纹包含希腊字母 (可能被篡改): $fp${RESET}"
        return 1
    else
        echo "${GREEN}✓ 指纹无希腊字母篡改${RESET}"
