detect_syscall_hooking() {
    if [ -r /proc/self/status ]; then
        tracer=$(grep "TracerPid:" /proc/self/status 2>/dev/null | awk '{print $2}')
        if [ -n "$tracer" ] && [ "$tracer" -ne 0 ]; then
            echo "${RED}⚠ 检测到进程被跟踪 (TracerPid=$tracer)${RESET}"
            return 1
        fi
    fi
    if [ -r /proc/self/maps ]; then
        if grep -q "frida\|lsposed\|riru\|xposed" /proc/self/maps 2>/dev/null; then
            echo "${RED}⚠ 检测到Hook库注入:${RESET}"
            grep "frida\|lsposed\|riru\|xposed" /proc/self/maps 2>/dev/null | head -3 | while read line; do
                echo "    $line"
            done
            return 1
        fi
    fi
    echo "${GREEN}✓ 未检测到系统调用层Hook痕迹${RESET}"
    return 0
}

