detect_suspicious_mounts() {
    local mountinfo_file="/proc/self/mountinfo"
    [ -r "$mountinfo_file" ] || { echo "${RED}⚠ 无法读取挂载信息${RESET}"; return 1; }

    local awk_scan='
BEGIN {
    ro_prefix_regex = "^(/system(/|$)|/system_root(/|$)|/system_ext(/|$)|/vendor(/|$)|/product(/|$)|/odm(/|$)|/vendor_dlkm(/|$)|/odm_dlkm(/|$)|/system_dlkm(/|$))"
    critical_regex = "^/(system|system_root|system_ext|vendor|product|odm)(/|$).*(/(bin|xbin|framework|priv-app|app|etc/permissions|lib|lib64)(/|$)|^/(system|system_root|system_ext|vendor|product|odm)$)"
    writable_root_regex = "(data|cache|metadata|mnt/user|mnt/runtime|storage|sdcard|persist|mnt/expand|mnt/media_rw)"
    sus_kw_regex = "magisk|\\.magisk|zygisk|kernelsu|ksu|ksud|apatch|lspd|lsposed|riru|edxp|taichi|xposed|substrate|frida|dobby|sandhook|shadowhook|bytehook|xhook|mount_mask|mount_mark"
    vendor_ro_ovl_regex = "/mnt/(opex|oplus|oneplus|realme|vivo|iqoo|mi_ext|miui|xiaomi|nubia|redmagic|redmagic|lenovo|zui|yoga|asus|rog|samsung|sec|huawei|honor|meizu|zte|motorola|moto|sony|sharp|blackshark|legion|y700)"

    RED = "\033[1;31m"
    YELLOW = "\033[1;33m"
    RESET = "\033[0m"
}

{
    line = $0
    if (line ~ /^[[:space:]]*$/) next

    idx = index(line, " - ")
    if (idx == 0) next

    left = substr(line, 1, idx-1)
    right = substr(line, idx+3)

    split(left, lf)
    mount_point = lf[5]
    mount_opts = lf[6]
    
        split(right, rf)
    fs_type = rf[1]
    source = rf[2]
    super_opts = rf[3]

    if (mount_point == "/data_mirror" || mount_point ~ "^/data_mirror/") next

    if (mount_point ~ ro_prefix_regex) {
        if (mount_opts ~ /(^|,)rw(,|$)/) {
            printf "%s⚠ 系统/只读分区出现可写挂载: %s (fs:%s, src:%s, opts:%s)%s\n", RED, mount_point, fs_type, source, mount_opts, RESET
            printf "    挂载行: %s\n", line
            found = 1
            next
        }
        if (source ~ "^/data/") {
            printf "%s⚠ 系统分区挂载源来自/data: %s (fs:%s, src:%s)%s\n", RED, mount_point, fs_type, source, RESET
            printf "    挂载行: %s\n", line
            found = 1
            next
        }
    }

    if (mount_point ~ "^/apex/" && mount_point != "/apex") {
        if ((fs_type " " source " " mount_opts " " super_opts) ~ sus_kw_regex) {
            printf "%s⚠ /apex 子挂载出现可疑特征: %s (fs:%s, src:%s)%s\n", RED, mount_point, fs_type, source, RESET
            printf "    挂载行: %s\n", line
            found = 1
            next
        }
    }

    if (fs_type == "overlay") {
        has_upper_work = (line ~ /upperdir=/ || line ~ /workdir=/)
        lowerdir_in_writable = (line ~ "lowerdir=([^,]*/)*(" writable_root_regex ")/")
        sus_keyword_match = (line ~ sus_kw_regex)

        is_critical = (mount_point ~ critical_regex || mount_point ~ ro_prefix_regex)

        if (is_critical) {
            if (has_upper_work || lowerdir_in_writable || sus_keyword_match) {
                printf "%s⚠ 发现可疑overlay覆盖: %s (src:%s)%s\n", RED, mount_point, source, RESET
                printf "    挂载行: %s\n", line
                found = 1
                next
            }
        } else {
            if (sus_keyword_match) {
                printf "%s⚠ 发现可疑overlay覆盖(非关键分区但含关键词): %s (src:%s)%s\n", RED, mount_point, source, RESET
                printf "    挂载行: %s\n", line
                found = 1
                next
            }
        }

        if (!has_upper_work && line ~ "lowerdir=([^,]*/)*(system|vendor|product|odm|apex|mnt)/" && line !~ "lowerdir=([^,]*/)*(" writable_root_regex ")/") {
            next
        }
    }

    if ((mount_point " " fs_type " " source " " mount_opts " " super_opts) ~ sus_kw_regex) {
        if (mount_point ~ ro_prefix_regex || source ~ "^/data/") {
            printf "%s⚠ 发现可疑挂载特征: %s (fs:%s, src:%s)%s\n", RED, mount_point, fs_type, source, RESET
            printf "    挂载行: %s\n", line
            found = 1
            next
        }
    }
}

END {
    if (found) exit 1
    exit 0
}
'
    local out1
    out1=$(cat "$mountinfo_file" | awk "$awk_scan" 2>/dev/null)
    local ret1=$?

    if [ $ret1 -eq 0 ] && [ -z "$out1" ]; then
        echo "${GREEN}✓ 未检测到可疑挂载点${RESET}"
        return 0
    fi

    sleep 1
    local out2
    out2=$(cat "$mountinfo_file" | awk "$awk_scan" 2>/dev/null)
    local ret2=$?

    sleep 1
    local out3
    out3=$(cat "$mountinfo_file" | awk "$awk_scan" 2>/dev/null)
    local ret3=$?

    if [ "$out1" != "$out2" ] || [ "$out2" != "$out3" ]; then
        echo "${YELLOW}⚠ 检测到挂载状态在短时间内发生变化（可能存在挂载间隙/短暂注入）${RESET}"
        echo "$out1"
        return 1
    else
        echo "$out1"
        return 1
    fi
}

detect_uname_spoofing() {
    local found=0
    local real_uname
    local proc_version
    real_uname=$(uname -a 2>/dev/null)
    if [ -f /proc/version ]; then
        proc_version=$(cat /proc/version 2>/dev/null)
        if [ -n "$real_uname" ] && [ -n "$proc_version" ]; then
            if ! echo "$proc_version" | grep -q "$(uname -r)"; then
                echo "${RED}⚠ 检测到Linux uname欺骗${RESET}"
                echo "    uname -a: $real_uname"
                echo "    /proc/version: $proc_version"
                found=1
            fi
        fi
    fi
    if [ -f /proc/sys/kernel/ostype ] && [ -f /proc/sys/kernel/osrelease ]; then
        local ostype=$(cat /proc/sys/kernel/ostype 2>/dev/null)
        local osrelease=$(cat /proc/sys/kernel/osrelease 2>/dev/null)
        if [ "$ostype" != "Linux" ] 2>/dev/null; then
            echo "${RED}⚠ 检测到ostype异常: $ostype${RESET}"
            found=1
        fi
        if [ "$osrelease" != "$(uname -r)" ] 2>/dev/null; then
            echo "${RED}⚠ 检测到osrelease与内核版本不一致: $osrelease vs $(uname -r)${RESET}"
            found=1
        fi
    fi
    if [ $found -eq 0 ]; then
        echo "${GREEN}✓ uname信息正常${RESET}"
        return 0
    else
        return 1
    fi
}

