detect_avb_disabled() {
    local disabled=0
    local uncertain=0
    local veritymode vbmeta_state verified_state dm_verity

    veritymode=$(getprop ro.boot.veritymode 2>/dev/null)
    vbmeta_state=$(getprop ro.boot.vbmeta.device_state 2>/dev/null)
    verified_state=$(getprop ro.boot.verifiedbootstate 2>/dev/null)
    dm_verity=$(getprop ro.boot.enable_dm_verity 2>/dev/null)

    case "$veritymode" in
        disabled) disabled=1 ;;
        ""|"unknown"|"null") uncertain=1 ;;
    esac

    case "$vbmeta_state" in
        unlocked|unlocked*) disabled=1 ;;
        locked|locked*) : ;;
        ""|"unknown"|"null") uncertain=1 ;;
    esac

    case "$verified_state" in
        green) : ;;
        orange|yellow|red) disabled=1 ;;
        ""|"unknown"|"null") uncertain=1 ;;
    esac

    case "$dm_verity" in
        0|false|disabled) disabled=1 ;;
        1|true|enabled) : ;;
        ""|"unknown"|"null") uncertain=1 ;;
    esac

    local props="vendor.boot.veritymode vendor.boot.vbmeta.device_state vendor.boot.verifiedbootstate ro.boot.dmverity ro.boot.dm_verity ro.boot.flash.locked ro.secureboot.lockstate ro.boot.secureboot ro.boot.selinux ro.build.selinux"
    local prop val
    for prop in $props; do
        val=$(getprop "$prop" 2>/dev/null)
        [ -n "$val" ] || { uncertain=1; continue; }
        case "$prop" in
            vendor.boot.veritymode|ro.boot.veritymode)
                case "$val" in disabled) disabled=1 ;; enforcing|eio|logging) : ;; *) uncertain=1 ;; esac
                ;;
            vendor.boot.vbmeta.device_state|ro.boot.vbmeta.device_state)
                case "$val" in unlocked|unlocked*) disabled=1 ;; locked|locked*) : ;; *) uncertain=1 ;; esac
                ;;
            vendor.boot.verifiedbootstate|ro.boot.verifiedbootstate)
                case "$val" in green) : ;; orange|yellow|red) disabled=1 ;; *) uncertain=1 ;; esac
                ;;
            ro.boot.dmverity|ro.boot.dm_verity)
                case "$val" in 0|false|disabled) disabled=1 ;; 1|true|enabled) : ;; *) uncertain=1 ;; esac
                ;;
            ro.boot.flash.locked|ro.secureboot.lockstate)
                case "$val" in 0|false|unlocked) disabled=1 ;; 1|true|locked) : ;; *) : ;; esac
                ;;
            ro.boot.secureboot)
                case "$val" in 0|false|disabled|off|no) disabled=1 ;; 1|true|enabled|on|yes) : ;; *) uncertain=1 ;; esac
                ;;
            ro.boot.selinux|ro.build.selinux)
                case "$val" in enforcing|1) : ;; permissive|0) disabled=1 ;; *) uncertain=1 ;; esac
                ;;
        esac
    done

    if [ $disabled -eq 1 ]; then
        echo "${RED}⚠ AVB/Verity可能异常${RESET}"
        return 1
    fi

    if [ $uncertain -eq 1 ]; then
        echo "${YELLOW}⚠ AVB状态无法完全判断(属性缺失/非标准)${RESET}"
        return 0
    fi

    echo "${GREEN}✓ AVB验证状态正常${RESET}"
    return 0
}

detect_adb_debug() {
    local adb_enabled adb_wifi_enabled adb_port adbd_status adb_tls_enable usb_state usb_config persist_usb_config tcp_port adb_root persist_adb_enable
    adb_enabled=$(settings get global adb_enabled 2>/dev/null)
    adb_wifi_enabled=$(settings get global adb_wifi_enabled 2>/dev/null)
    adb_port=$(settings get global adb_port 2>/dev/null)
    adbd_status=$(getprop init.svc.adbd 2>/dev/null)
    adb_tls_enable=$(getprop persist.adb.tls_server.enable 2>/dev/null)
    usb_state=$(getprop sys.usb.state 2>/dev/null)
    usb_config=$(getprop sys.usb.config 2>/dev/null)
    persist_usb_config=$(getprop persist.sys.usb.config 2>/dev/null)
    tcp_port=$(getprop service.adb.tcp.port 2>/dev/null)
    adb_root=$(getprop service.adb.root 2>/dev/null)
    persist_adb_enable=$(getprop persist.service.adb.enable 2>/dev/null)

    local enabled=0
    local hints=""

    [ "$adb_enabled" = "1" ] && { enabled=1; hints="$hints adb_enabled=1"; }
    [ "$adb_wifi_enabled" = "1" ] && { enabled=1; hints="$hints adb_wifi=1"; }
    [ -n "$adb_port" ] && echo "$adb_port" | grep -Eq '^[0-9]+$' 2>/dev/null && [ "$adb_port" -gt 0 ] 2>/dev/null && { enabled=1; hints="$hints adb_port=$adb_port"; }

    csv_has "$usb_state" adb && { enabled=1; hints="$hints usb_state=adb"; }
    csv_has "$usb_config" adb && { enabled=1; hints="$hints usb_config=adb"; }

    [ "$persist_adb_enable" = "1" ] && { enabled=1; hints="$hints persist_adb_enable=1"; }

    if [ -n "$tcp_port" ] && echo "$tcp_port" | grep -Eq '^-?[0-9]+$' 2>/dev/null; then
        [ "$tcp_port" != "-1" ] && [ "$tcp_port" != "0" ] && { enabled=1; hints="$hints tcp_port=$tcp_port"; }
    fi

    [ "$adb_tls_enable" = "1" ] && { enabled=1; hints="$hints tls=1"; }

    if [ $enabled -eq 0 ]; then
        if csv_has "$persist_usb_config" adb && [ "$adbd_status" = "running" ]; then
            enabled=1
            hints="$hints persist_usb=adb adbd=running"
        fi
    fi

    if [ $enabled -eq 0 ]; then
        if [ "$adbd_status" = "running" ]; then
            enabled=1
            hints="$hints adbd=running"
        fi
    fi

    if [ $enabled -eq 0 ] && command -v dumpsys >/dev/null 2>&1; then
        local dsu
        dsu=$(dumpsys usb 2>/dev/null | tr -d '
')
        if echo "$dsu" | grep -qiE 'adb' 2>/dev/null; then
            if echo "$dsu" | grep -qiE 'enabled|true|1|adb' 2>/dev/null; then
                enabled=1
                hints="$hints dumpsys_usb=hit"
            fi
        fi
        local dsa
        dsa=$(dumpsys adb 2>/dev/null | tr -d '
')
        if [ -n "$dsa" ] && echo "$dsa" | grep -qiE 'enabled|debugging|wireless|adb' 2>/dev/null; then
            enabled=1
            hints="$hints dumpsys_adb=hit"
        fi
    fi

    if [ $enabled -eq 1 ]; then
        [ "$adb_root" = "1" ] && hints="$hints adb_root=1"
        echo "${RED}⚠ ADB调试已开启${RESET}"
        echo "${YELLOW}  细节:${RESET}${hints} adbd=${adbd_status:-unknown}"
        return 1
    fi

    echo "${GREEN}✓ ADB调试未开启${RESET}"
    return 0
   }

detect_usb_debug() {
    local usb_debug=0
    local usb_state usb_config persist_usb_config adb_enabled adbd_status adb_disabled_prop persist_adb_enable

    usb_state=$(getprop sys.usb.state 2>/dev/null)
    usb_config=$(getprop sys.usb.config 2>/dev/null)
    persist_usb_config=$(getprop persist.sys.usb.config 2>/dev/null)
    adb_enabled=$(settings get global adb_enabled 2>/dev/null)
    adbd_status=$(getprop init.svc.adbd 2>/dev/null)
    adb_disabled_prop=$(getprop sys.usb.adb.disabled 2>/dev/null)
    persist_adb_enable=$(getprop persist.service.adb.enable 2>/dev/null)

    csv_has "$usb_state" adb && usb_debug=1
    csv_has "$usb_config" adb && usb_debug=1

    if [ $usb_debug -eq 0 ]; then
        if [ "$adb_enabled" = "1" ] && csv_has "$persist_usb_config" adb && [ "$adbd_status" = "running" ]; then
            usb_debug=1
        fi
    fi

    if [ $usb_debug -eq 0 ]; then
        if [ "$persist_adb_enable" = "1" ] && [ "$adbd_status" = "running" ]; then
            if csv_has "$usb_state" adb || csv_has "$usb_config" adb || csv_has "$persist_usb_config" adb; then
                usb_debug=1
            fi
        fi
    fi

    if [ -n "$adb_disabled_prop" ]; then
        if [ "$adb_disabled_prop" = "0" ] && [ "$adb_enabled" = "1" ]; then
            usb_debug=1
        fi
        if [ "$adb_disabled_prop" = "1" ] && [ $usb_debug -eq 1 ]; then
            usb_debug=0
        fi
    fi

    if [ $usb_debug -eq 0 ] && command -v dumpsys >/dev/null 2>&1; then
        local dsu
        dsu=$(dumpsys usb 2>/dev/null | tr -d '
')
        if echo "$dsu" | grep -qiE 'sys\.usb\.state|sys\.usb\.config|adb' 2>/dev/null; then
            if echo "$dsu" | grep -qiE 'adb' 2>/dev/null; then
                usb_debug=1
            fi
        fi
    fi

    if [ $usb_debug -eq 1 ]; then
        echo "${RED}⚠ USB调试已开启${RESET}"
        echo "${YELLOW}  细节:${RESET} usb_state=${usb_state:-unknown} usb_config=${usb_config:-unknown} adbd=${adbd_status:-unknown}"
        return 1
    fi

    echo "${GREEN}✓ USB调试未开启${RESET}"
    return 0
}

