/storage/emulated/0/Android/data/com.omarea.scene
"
    for d in $scene_dirs; do
        path_exists "$d"
        if [ $? -eq 0 ]; then
            if echo "$d" | grep -qE "/data/.*scene|/data/.*omarea|/data/.*vtools"; then
                echo "${RED}⚠ 检测到Scene关键目录: $d${RESET}"
                real_risk=1
            else
                echo "${YELLOW}⚠ 提示: 检测到Scene目录 ($d)${RESET}"
