persist.scene.thermal
persist.scene.io
persist.scene.gpu
persist.scene.cpu
persist.omarea.vm
"
    for prop in $scene_props; do
        local val
        val=$(getprop "$prop" 2>/dev/null)
        if [ -n "$val" ]; then
            echo "${YELLOW}⚠ 提示: 检测到Scene系统属性: $prop = $val${RESET}"
            found=1
        fi
    done

    if command -v ps >/dev/null 2>&1; then
        local scene_processes=""
        if ps -A 2>/dev/null | grep -E "com\.omarea\.[a-z]+|com\.scene\." >/dev/null; then
            scene_processes=$(ps -A 2>/dev/null | grep -E "com\.omarea\.[a-z]+|com\.scene\." | awk '{print $NF}' | head -3 | tr '\n' ' ')
            echo "${YELLOW}⚠ 提示: 检测到Scene相关进程: $scene_processes${RESET}"
            found=1
        fi
    fi

    if [ $real_risk -eq 1 ]; then
