detect_emulator() {
    local found=0
    local emu_files="
/system/bin/qemu-props
/dev/socket/qemud
/dev/qemu_pipe
/system/lib/libc_malloc_debug_qemu.so
/sys/qemu_trace
/system/bin/androVM-prop
/system/bin/microvirt-prop
"
    for f in $emu_files; do
        path_exists "$f"
        if [ $? -eq 0 ]; then
            echo "${RED}⚠ 检测到模拟器特征文件: $f${RESET}"
            found=1
        fi
    done

    local emu_props="
ro.kernel.qemu
ro.hardware
ro.product.manufacturer
ro.product.model
ro.build.fingerprint
"
    for p in $emu_props; do
        val=$(getprop "$p" 2>/dev/null)
        case "$p" in
            ro.kernel.qemu)
                [ "$val" = "1" ] && echo "${RED}⚠ 检测到模拟器属性: $p=$val${RESET}" && found=1
                ;;
            ro.hardware)
                echo "$val" | grep -qiE "goldfish|ranchu|vbox|qemu" && echo "${RED}⚠ 检测到模拟器硬件: $p=$val${RESET}" && found=1
                ;;
            ro.product.manufacturer)
                echo "$val" | grep -qiE "Genymotion" && echo "${RED}⚠ 检测到模拟器厂商: $p=$val${RESET}" && found=1
                ;;
            ro.product.model)
                echo "$val" | grep -qiE "sdk_gphone|Android SDK built for x86" && echo "${RED}⚠ 检测到模拟器型号: $p=$val${RESET}" && found=1
                ;;
            ro.build.fingerprint)
                echo "$val" | grep -qiE "sdk_gphone|generic_x86|generic_arm64" && echo "${RED}⚠ 检测到模拟器指纹: $p=$val${RESET}" && found=1
                ;;
        esac
    done

    path_exists "/dev/vboxguest"
    if [ $? -eq 0 ]; then
        echo "${RED}⚠ 检测到VirtualBox模拟器特征${RESET}"
        found=1
    fi

    if [ -f /proc/cpuinfo ]; then
        if grep -qi "goldfish" /proc/cpuinfo 2>/dev/null; then
            echo "${RED}⚠ 检测到CPU信息包含goldfish (模拟器特征)${RESET}"
            found=1
        fi
    fi

    if command -v ip >/dev/null 2>&1; then
        if ip link show | grep -q "eth0" 2>/dev/null; then
            echo "${YELLOW}⚠ 检测到网络接口eth0 (可能为模拟器)${RESET}"
            found=1
        fi
    fi

    if [ $found -eq 0 ]; then
        echo "${GREEN}✓ 未检测到模拟器特征${RESET}"
        return 0
    else
        return 1
    fi
}

detect_syscall_hooking() {
    local found=0

    if [ -r /proc/self/status ]; then
        local tracer
        tracer=$(grep -i "TracerPid:" /proc/self/status 2>/dev/null | awk '{print $2}')
        if [ -n "$tracer" ] && [ "$tracer" -ne 0 ] 2>/dev/null; then
            echo "${RED}⚠ 检测到进程被跟踪 (TracerPid=$tracer)，可能被调试或Hook${RESET}"
            found=1
        fi
    fi

    if [ -r /proc/self/maps ]; then
        local maps
        maps=$(cat /proc/self/maps 2>/dev/null)
        local hook_libs="frida-agent|frida-helper|frida-gadget|frida-32|frida-64|gum-js-loop|gmain|libriru|libxposed|libsandhook|libwhale|libcainiao|libnativehook|libkona|libinject|libgadget|lsposed|edxp|taichi|dobby|shadowhook|sandhook|bytehook|xhook|libreef|libshook"
        local matches
        matches=$(echo "$maps" | grep -E "$hook_libs" 2>/dev/null)
        if [ -n "$matches" ]; then
            echo "${RED}⚠ 检测到可疑Hook库:${RESET}"
            echo "$matches" | head -5 | while IFS= read -r line; do
                echo "    $line"
            done
            found=1
        fi

        local suspicious_regions
        suspicious_regions=$(echo "$maps" | grep -E "rw.*p" | grep -v "kgsl" | grep -v "ashmem" 2>/dev/null | head -5)
        if [ -n "$suspicious_regions" ]; then
            echo "${YELLOW}⚠ 检测到可写可执行内存区域:${RESET}"
            echo "$suspicious_regions" | head -3 | while IFS= read -r line; do
                echo "    $line"
            done
        fi
    fi

    if [ -f /proc/sys/kernel/yama/ptrace_scope ]; then
        local scope
        scope=$(cat /proc/sys/kernel/yama/ptrace_scope 2>/dev/null)
        if [ "$scope" = "0" ]; then
            echo "${YELLOW}⚠ 检测到ptrace_scope=0，允许任意进程跟踪，可能为Hook提供条件${RESET}"
        fi
    fi
         if command -v ps >/dev/null 2>&1; then
        local hook_procs
        hook_procs=$(ps -A 2>/dev/null | grep -E "frida|gum|js|linjector|lspd|edxp|taichi|dobby" | grep -v grep)
        if [ -n "$hook_procs" ]; then
            echo "${RED}⚠ 检测到Hook框架相关进程:${RESET}"
            echo "$hook_procs" | head -5 | while IFS= read -r line; do
                echo "    $line"
            done
            found=1
        fi
    fi

    if [ $found -eq 0 ]; then
        echo "${GREEN}✓ 未检测到系统调用层Hook痕迹${RESET}"
        return 0
    else
        return 1
    fi
}




