detect_device_spoofing_and_model_change() {
    local found=0

    local model_a model_b model_c model_d
    model_a=$(getprop ro.product.model 2>/dev/null)
    model_b=$(getprop ro.product.system.model 2>/dev/null)
    model_c=$(getprop ro.product.vendor.model 2>/dev/null)
    model_d=$(getprop ro.product.odm.model 2>/dev/null)

    local brand_a brand_b brand_c
    brand_a=$(getprop ro.product.brand 2>/dev/null)
    brand_b=$(getprop ro.product.system.brand 2>/dev/null)
    brand_c=$(getprop ro.product.vendor.brand 2>/dev/null)

    local manu_a manu_b manu_c
    manu_a=$(getprop ro.product.manufacturer 2>/dev/null)
    manu_b=$(getprop ro.product.system.manufacturer 2>/dev/null)
    manu_c=$(getprop ro.product.vendor.manufacturer 2>/dev/null)

    if [ -n "$model_b" ] && [ -n "$model_a" ] && [ "$model_a" != "$model_b" ]; then
        echo "${RED}⚠ 机型属性不一致: ro.product.model=$model_a vs ro.product.system.model=$model_b${RESET}"
        found=1
    fi
    if [ -n "$model_c" ] && [ -n "$model_a" ] && [ "$model_a" != "$model_c" ]; then
        echo "${RED}⚠ 机型属性不一致: ro.product.model=$model_a vs ro.product.vendor.model=$model_c${RESET}"
        found=1
    fi
    if [ -n "$model_d" ] && [ -n "$model_a" ] && [ "$model_a" != "$model_d" ]; then
        echo "${RED}⚠ 机型属性不一致: ro.product.model=$model_a vs ro.product.odm.model=$model_d${RESET}"
        found=1
    fi

    if [ -n "$brand_b" ] && [ -n "$brand_a" ] && [ "$brand_a" != "$brand_b" ]; then
        echo "${RED}⚠ 品牌属性不一致: ro.product.brand=$brand_a vs ro.product.system.brand=$brand_b${RESET}"
        found=1
    fi
    if [ -n "$brand_c" ] && [ -n "$brand_a" ] && [ "$brand_a" != "$brand_c" ]; then
        echo "${RED}⚠ 品牌属性不一致: ro.product.brand=$brand_a vs ro.product.vendor.brand=$brand_c${RESET}"
        found=1
    fi

    if [ -n "$manu_b" ] && [ -n "$manu_a" ] && [ "$manu_a" != "$manu_b" ]; then
        echo "${RED}⚠ 厂商属性不一致: ro.product.manufacturer=$manu_a vs ro.product.system.manufacturer=$manu_b${RESET}"
        found=1
    fi
    
      if [ -n "$manu_c" ] && [ -n "$manu_a" ] && [ "$manu_a" != "$manu_c" ]; then
        echo "${RED}⚠ 厂商属性不一致: ro.product.manufacturer=$manu_a vs ro.product.vendor.manufacturer=$manu_c${RESET}"
        found=1
    fi

    local fp device
    fp=$(getprop ro.build.fingerprint 2>/dev/null)
    device=$(getprop ro.product.device 2>/dev/null)
    if [ -n "$fp" ]; then
        local fp_brand fp_device
        fp_brand=$(echo "$fp" | cut -d"/" -f1)
        fp_device=$(echo "$fp" | cut -d"/" -f2)

        if [ -n "$brand_a" ] && [ -n "$fp_brand" ] && [ "$fp_brand" != "$brand_a" ]; then
            echo "${RED}⚠ 指纹品牌与系统品牌不匹配: fp_brand=$fp_brand vs ro.product.brand=$brand_a${RESET}"
            found=1
        fi
        if [ -n "$device" ] && [ -n "$fp_device" ] && [ "$fp_device" != "$device" ]; then
            echo "${RED}⚠ 指纹device与系统device不匹配: fp_device=$fp_device vs ro.product.device=$device${RESET}"
            found=1
        fi

        echo "$fp" | grep -qiE "test-keys|generic|unknown" && {
            echo "${RED}⚠ 指纹包含异常关键词(test-keys/generic/unknown): $fp${RESET}"
            found=1
        }
    fi

    local spoof_pkgs="
com.devicefaker
com.imei.changer
com.android.imei
com.fake.device
com.xposed.imei
"
    for pkg in $spoof_pkgs; do
        if path_exists "/data/user/0/$pkg"; then
            echo "${RED}⚠ 检测到疑似改机工具: $pkg${RESET}"
            found=1
        fi
    done

    if [ $found -eq 0 ]; then
        echo "${GREEN}✓ 未检测到改机/机型修改特征${RESET}"
        return 0
    else
        return 1
    fi
}


detect_system_properties() {
    local found=0

    local kv_props="
ro.debuggable
ro.secure
ro.build.tags
ro.build.type
ro.build.selinux
ro.boot.selinux
persist.sys.usb.config
persist.service.adb.enable
service.adb.root
persist.sys.root_access
ro.dalvik.vm.native.bridge
"
    local p v
    for p in $kv_props; do
        v=$(getprop "$p" 2>/dev/null)
        [ -n "$v" ] || continue
        case "$p" in
            ro.debuggable)
                [ "$v" = "1" ] && { echo "${RED}⚠ 系统属性异常: $p=$v (可调试)${RESET}"; found=1; }
                ;;
            ro.secure)
                [ "$v" = "0" ] && { echo "${RED}⚠ 系统属性异常: $p=$v (不安全)${RESET}"; found=1; }
                ;;
            ro.build.tags)
                echo "$v" | grep -qi "test-keys" && { echo "${RED}⚠ 系统属性异常: $p=$v (test-keys)${RESET}"; found=1; }
                ;;
            ro.build.type)
                echo "$v" | grep -qiE "userdebug|eng" && { echo "${RED}⚠ 系统属性异常: $p=$v (非user)${RESET}"; found=1; }
                ;;
            ro.build.selinux|ro.boot.selinux)
                echo "$v" | grep -qiE "permissive|0" && { echo "${RED}⚠ 系统属性异常: $p=$v (SELinux非enforcing)${RESET}"; found=1; }
                ;;
            persist.sys.usb.config)
                echo " $v " | grep -q "[, ]adb[ ,]" && { echo "${RED}⚠ 系统属性提示: $p=$v (含adb)${RESET}"; found=1; }
                ;;
            persist.service.adb.enable)
                [ "$v" = "1" ] && { echo "${RED}⚠ 系统属性异常: $p=$v (ADB持久开启)${RESET}"; found=1; }
                ;;
            service.adb.root)
                [ "$v" = "1" ] && { echo "${RED}⚠ 系统属性异常: $p=$v (adbd root)${RESET}"; found=1; }
                ;;
            persist.sys.root_access)
                [ "$v" != "0" ] && { echo "${RED}⚠ 系统属性异常: $p=$v (root_access)${RESET}"; found=1; }
                ;;
            ro.dalvik.vm.native.bridge)
                [ -n "$v" ] && [ "$v" != "0" ] && [ "$v" != "libhoudini.so" ] && { echo "${RED}⚠ 系统属性异常: $p=$v (NativeBridge异常)${RESET}"; found=1; }
                ;;
        esac
    done

    if command -v getprop >/dev/null 2>&1; then
        local hit
        hit=$(getprop 2>/dev/null | grep -Ei "magisk|\.magisk|zygisk|kernelsu|ksu|ksud|apatch|lspd|lsposed|riru|edxp|taichi|xposed|substrate|frida|dobby|sandhook|shadowhook|bytehook|xhook|resetprop|hide_my_applist|shamiko|zhuoying|zygote\.canary|ptrace" | head -20)
        if [ -n "$hit" ]; then
            echo "${RED}⚠ 系统属性命中可疑关键词(仅展示前20条):${RESET}"
            echo "$hit" | while IFS= read -r line; do echo "    $line"; done
            found=1
        fi
    fi

    [ $found -eq 0 ] && return 0
    return 1
}

detect_system_prop_consistency() {
    local found=0

    local props_sets="
ro.product.brand|ro.product.system.brand|ro.product.vendor.brand|ro.product.product.brand
ro.product.manufacturer|ro.product.system.manufacturer|ro.product.vendor.manufacturer|ro.product.product.manufacturer
ro.product.device|ro.product.system.device|ro.product.vendor.device|ro.product.product.device
ro.product.model|ro.product.system.model|ro.product.vendor.model|ro.product.product.model
ro.build.fingerprint|ro.system.build.fingerprint|ro.vendor.build.fingerprint|ro.product.build.fingerprint
"
    local line
    IFS=$'\n'
    for line in $props_sets; do
        local base_prop rest
        base_prop=${line%%|*}
        rest=${line#*|}
        local base_val
        base_val=$(getprop "$base_prop" 2>/dev/null)

        [ -n "$base_val" ] || continue

        local p v
        local mismatch_list=""
        local p_all="$base_prop|$rest"
        IFS="|"
        for p in $p_all; do
            v=$(getprop "$p" 2>/dev/null)
            [ -n "$v" ] || continue
            if [ "$v" != "$base_val" ]; then
                mismatch_list="${mismatch_list}\n    $p=$v"
            fi
        done
        IFS=$'\n'
        if [ -n "$mismatch_list" ]; then
            echo "${RED}⚠ 系统属性一致性异常: 基准 ${base_prop}=${base_val}${RESET}"
            echo -e "$mismatch_list"
            found=1
        fi
    done

    local fp brand device model
    fp=$(getprop ro.build.fingerprint 2>/dev/null)
    brand=$(getprop ro.product.brand 2>/dev/null)
    device=$(getprop ro.product.device 2>/dev/null)
    model=$(getprop ro.product.model 2>/dev/null)
    if [ -n "$fp" ]; then
        echo "$fp" | grep -qiE "generic|unknown" && {
            echo "${RED}⚠ 系统属性一致性异常: fingerprint包含generic/unknown: $fp${RESET}"
            found=1
        }
        [ -n "$brand" ] && echo "$fp" | grep -qi "$brand" || {
            echo "${RED}⚠ 系统属性可疑: fingerprint与brand不匹配(brand=$brand): $fp${RESET}"
            found=1
        }
        [ -n "$device" ] && echo "$fp" | grep -qi "$device" || {
            echo "${RED}⚠ 系统属性可疑: fingerprint与device不匹配(device=$device): $fp${RESET}"
            found=1
        }
    fi

    [ $found -eq 0 ] && return 0
    return 1
}

detect_interface_tampering() {
    local found=0

    local cmds="getprop pm settings mount ps su"
    local c
    for c in $cmds; do
        local t
        t=$(type -a "$c" 2>/dev/null | head -5)
        if [ -n "$t" ]; then
            echo "$t" | grep -qiE "is a function|is aliased" && {
                echo "${RED}⚠ 接口/命令可能被篡改: $c 被定义为函数/别名${RESET}"
                echo "$t" | while IFS= read -r line; do echo "    $line"; done
                found=1
                continue
            }
        fi

        local which_path
        which_path=$(command -v "$c" 2>/dev/null)
        [ -n "$which_path" ] || continue

        echo "$which_path" | grep -qE '^(/system/bin/|/system/xbin/|/vendor/bin/|/product/bin/|/apex/.*/bin/)' || {
            echo "${RED}⚠ 接口/命令可能被篡改: $c 路径异常 -> $which_path${RESET}"
            found=1
        }

        echo "$which_path" | grep -qE '^(/data/|/sdcard/|/storage/|/mnt/|/cache/|/metadata/|/dev/)' && {
            echo "${RED}⚠ 接口/命令高风险: $c 来自可写目录 -> $which_path${RESET}"
            found=1
        }
    done

    [ -n "$LD_PRELOAD" ] && {
        echo "${RED}⚠ 接口篡改疑似: LD_PRELOAD 已设置 -> $LD_PRELOAD${RESET}"
        found=1
    }
    [ -n "$LD_LIBRARY_PATH" ] && echo "$LD_LIBRARY_PATH" | grep -qE '(^|:)/data/|(^|:)/sdcard/|(^|:)/storage/' && {
        echo "${RED}⚠ 接口篡改疑似: LD_LIBRARY_PATH 含可写路径 -> $LD_LIBRARY_PATH${RESET}"
        found=1
    }

    local pth="/system/bin/getprop"
    if [ -e "$pth" ] 2>/dev/null; then
        if [ -L "$pth" ] 2>/dev/null; then
            local tgt
            tgt=$(readlink -f "$pth" 2>/dev/null)
            if [ -n "$tgt" ]; then
                echo "$tgt" | grep -qE '^(/system/bin/|/apex/.*/bin/)(toolbox|toybox)$' || {
                    echo "${RED}⚠ 接口篡改可疑: $pth 链接目标异常 -> $tgt${RESET}"
                    found=1
                }
            else
                echo "${RED}⚠ 接口篡改可疑: $pth 无法解析链接目标${RESET}"
                found=1
            fi
        else
            ls -l "$pth" 2>/dev/null | grep -qE '^-r..r..r..[[:space:]]+1[[:space:]]+root[[:space:]]+(shell|root)[[:space:]]+' || {
                echo "${RED}⚠ 接口篡改可疑: $pth 权限/归属异常$(ls -l "$pth" 2>/dev/null)${RESET}"
                found=1
            }
        fi
    fi

    [ $found -eq 0 ] && return 0
    return 1
}



detect_system_boot() {
    local found=0
    local bc sc dc br
    bc=$(getprop sys.boot_completed 2>/dev/null)
    dc=$(getprop dev.bootcomplete 2>/dev/null)
    sc=$(getprop sys.user.0.ce_available 2>/dev/null)
    br=$(getprop ro.boot.bootreason 2>/dev/null)
    if [ -n "$bc" ] && [ "$bc" != "1" ]; then
        echo "${RED}⚠ 系统启动状态异常: sys.boot_completed=$bc${RESET}"
        found=1
            fi
    if [ -n "$dc" ] && [ "$dc" != "1" ]; then
        echo "${RED}⚠ 系统启动状态异常: dev.bootcomplete=$dc${RESET}"
        found=1
    fi
    if [ -n "$sc" ] && [ "$sc" != "1" ]; then
        echo "${YELLOW}⚠ 提示: CE可能未就绪: sys.user.0.ce_available=$sc${RESET}"
    fi
    if [ -r /proc/uptime ]; then
        local up
        up=$(cut -d" " -f1 /proc/uptime 2>/dev/null)
        if [ -n "$up" ]; then
            local upi
            upi=${up%.*}
            if [ -n "$upi" ] && [ "$upi" -lt 60 ] 2>/dev/null; then
                echo "${YELLOW}⚠ 提示: 系统刚启动(uptime=${up}s)${RESET}"
            fi
        fi
    fi
    if [ -n "$br" ]; then
        echo "${YELLOW}⚠ 启动原因: ro.boot.bootreason=$br${RESET}"
    fi

    local s
    s=$(getprop | grep -E '^init\.svc\.' 2>/dev/null | grep -Ei 'magisk|zygisk|kernelsu|ksu|apatch|lspd|lsposed|riru|edxp|taichi|xposed|frida' | head -10)
    if [ -n "$s" ]; then
        echo "${RED}⚠ 检测到可疑启动服务:${RESET}"
        echo "$s" | while IFS= read -r line; do echo "    $line"; done
        found=1
    fi

    [ $found -eq 0 ] && { echo "${GREEN}✓ 系统启动状态正常${RESET}"; return 0; }
    return 1
}

detect_proc_sys() {
    local found=0
    local k
    local v

    k="/proc/sys/kernel/yama/ptrace_scope"
    if [ -r "$k" ]; then
        v=$(cat "$k" 2>/dev/null)
        [ "$v" = "0" ] && { echo "${RED}⚠ /proc/sys 异常: kernel.yama.ptrace_scope=$v${RESET}"; found=1; }
    fi

    k="/proc/sys/kernel/kptr_restrict"
    if [ -r "$k" ]; then
        v=$(cat "$k" 2>/dev/null)
        [ "$v" = "0" ] && { echo "${RED}⚠ /proc/sys 异常: kernel.kptr_restrict=$v${RESET}"; found=1; }
    fi

    k="/proc/sys/kernel/dmesg_restrict"
    if [ -r "$k" ]; then
        v=$(cat "$k" 2>/dev/null)
        [ "$v" = "0" ] && { echo "${RED}⚠ /proc/sys 异常: kernel.dmesg_restrict=$v${RESET}"; found=1; }
    fi

    k="/proc/sys/kernel/randomize_va_space"
    if [ -r "$k" ]; then
        v=$(cat "$k" 2>/dev/null)
        [ "$v" != "2" ] && { echo "${RED}⚠ /proc/sys 异常: kernel.randomize_va_space=$v${RESET}"; found=1; }
    fi

    k="/proc/sys/fs/protected_hardlinks"
    if [ -r "$k" ]; then
        v=$(cat "$k" 2>/dev/null)
        [ "$v" != "1" ] && { echo "${RED}⚠ /proc/sys 异常: fs.protected_hardlinks=$v${RESET}"; found=1; }
    fi

    k="/proc/sys/fs/protected_symlinks"
    if [ -r "$k" ]; then
        v=$(cat "$k" 2>/dev/null)
        [ "$v" != "1" ] && { echo "${RED}⚠ /proc/sys 异常: fs.protected_symlinks=$v${RESET}"; found=1; }
    fi

k="/proc/sys/kernel/perf_event_paranoid"
if [ -r "$k" ]; then
    v=$(cat "$k" 2>/dev/null)
    if echo "$v" | grep -Eq "^-?[0-9]+$"; then
        if [ "$v" -lt -1 ] 2>/dev/null || [ "$v" -gt 3 ] 2>/dev/null; then
            echo "${RED}⚠ /proc/sys 异常: kernel.perf_event_paranoid=$v${RESET}"
            found=1
        fi
    else
        [ -n "$v" ] && { echo "${RED}⚠ /proc/sys 异常: kernel.perf_event_paranoid=$v${RESET}"; found=1; }
    fi
fi

    k="/proc/sys/net/ipv4/ip_forward"
    if [ -r "$k" ]; then
        v=$(cat "$k" 2>/dev/null)
        [ "$v" = "1" ] && echo "${YELLOW}⚠ 提示: net.ipv4.ip_forward=1${RESET}"
    fi

    [ $found -eq 0 ] && { echo "${GREEN}✓ /proc/sys 关键项正常${RESET}"; return 0; }
    return 1
}

DETECTION_TASKS=(
    "detect_root: Root 状态"
    "detect_bl: Bootloader 状态"
    "detect_emulator: 模拟器特征检测"
    "detect_virtualization: 虚拟机/多开检测"
    "detect_mt2_folder: MT2 文件夹扫描"
    "detect_mt_manager: MT 管理器检测"
    "detect_byyoung: 爱玩机工具箱残留检测"
    "detect_hma_config: HMA 配置文件检测"
    "detect_wechat_xposed: 微信Xposed模块残留检测"
    "detect_local_tmp_residue: /data/local/tmp 残留检测"
    "detect_hyperceiler_prop: 工具模块属性检测"
    "detect_flash_prop: 刷机属性残留检测"
    "detect_system_properties: 系统属性检测"
    "detect_system_prop_consistency: 系统属性一致性对比"
    "detect_interface_tampering: 接口篡改检测"
    "detect_system_boot: 系统启动检测"
    "detect_proc_sys: /proc/sys 检测"
    "detect_vold_data_isolation: Vold数据隔离持久化属性检测"
    "detect_inode_issue: /data/local/tmp inode 状态"
    "detect_kernel_drivers: 内核/驱动残留检测"
    "detect_tampered_attestation: 指纹篡改检测"
    "detect_device_spoofing_and_model_change: 改机/机型修改检测"
    "detect_hidden_api_policy: 隐藏API策略修改检测"
    "detect_suspicious_mounts: 可疑挂载点检测"
    "detect_uname_spoofing: Uname 欺骗检测"
    "detect_abnormal_files: 全盘扫盘"
    "detect_forbidden_folders: 违规文件夹检测"
    "detect_forbidden_apps: 违规应用检测"
    "detect_avb_disabled: AVB验证状态检测"
    "detect_adb_debug: ADB调试状态检测"
    "detect_usb_debug: USB调试状态检测"
    "detect_scene_traces: Scene痕迹检测"
    "detect_lsp_traces: LSPosed/EdXposed/TaiChi特征检测"
    "detect_root_residue: 通用Root残留检测"
    "detect_ab_cleaner_traces: 异常内容痕迹检测"
    "detect_hook_frameworks: Hook框架检测"
    "detect_syscall_hooking: 系统调用层Hook检测"
)

total=${#DETECTION_TASKS[@]}
current=0
RESULTS=""

for task in "${DETECTION_TASKS[@]}"; do
    IFS=":" read -r func_name title <<< "$task"
    current=$((current + 1))
    percent=$((current * 100 / total))
    printf "\r\033[K[%3d%%] 正在检测: %s..." $percent "$title"
    
    output=$(eval "$func_name" 2>&1)
    ret=$?
    
    if [ $ret -eq 1 ]; then
        RESULTS="${RESULTS}\n${BOLD}${title}${RESET}\n${output}\n${LINE}\n"
    fi
done

printf "\r\033[K[100%%] 检测完成！\n\n"

if [ -n "$RESULTS" ]; then
    echo -e "${BOLD}${RED}检测到以下可疑环境：${RESET}
"
    echo -e "$RESULTS"
else
    echo -e "${GREEN}✓ 未检测到可疑环境${RESET}
"
fi

echo -e "${LINE}"
echo -e "\n${GREEN} 检测完成${RESET}"
exit 0   

            ;;
            
            
        "环境检测v3")

#!/system/bin/sh

GREEN="\033[1;32m"
RED="\033[1;31m"
YELLOW="\033[1;33m"
CYAN="\033[1;36m"
BLUE="\033[1;34m"
PURPLE="\033[1;35m"
BOLD="\033[1m"
RESET="\033[0m"
BLINK="\033[5m"
NC="\033[0m"
LINE="${BLUE}------------------------------------------------${RESET}"

path_exists() {
    [ -e "$1" ] 2>/dev/null && return 0
    return 1
}

has_visible_output() {
    local text="$1"
    local cleaned=""
    cleaned=$(printf '%s' "$text" | tr -d '' | sed 's/\\[[0-9;]*[[:alpha:]]//g' 2>/dev/null | tr -d '
	 ')
    [ -n "$cleaned" ]
}

csv_has() {
    local v="$1"
    local t="$2"
    [ -n "$v" ] || return 1
    v=$(echo "$v" | tr ' ' ',' 2>/dev/null)
    case ",$v," in
        *",$t,"*) return 0 ;;
        *) return 1 ;;
    esac
}

PM_LIST_CACHE=""

pm_list_all() {
    if [ -n "$PM_LIST_CACHE" ]; then
        printf '%s\n' "$PM_LIST_CACHE"
        return 0
    fi
    command -v pm >/dev/null 2>&1 || return 1
    PM_LIST_CACHE=$(pm list packages 2>/dev/null)
    [ -n "$PM_LIST_CACHE" ] || return 1
    printf '%s\n' "$PM_LIST_CACHE"
    return 0
}

pm_has_pkg() {
    local pkg="$1"
    [ -n "$pkg" ] || return 1
    pm_list_all >/dev/null 2>&1 || return 1
    echo "$PM_LIST_CACHE" | grep -q "^package:${pkg}$"
}

resolve_path() {
    readlink -f "$1" 2>/dev/null || readlink "$1" 2>/dev/null
}

maps_keyword_hits() {
    local regex="$1"
    [ -r /proc/self/maps ] || return 1
    grep -Ei "$regex" /proc/self/maps 2>/dev/null | head -5
}

mountinfo_keyword_hits() {
    local regex="$1"
    [ -r /proc/self/mountinfo ] || return 1
    grep -Ei "$regex" /proc/self/mountinfo 2>/dev/null | head -5
}

sample_dir_entries() {
    local dir="$1"
    [ -d "$dir" ] 2>/dev/null || return 1
    ls -A "$dir" 2>/dev/null | head -3
}

count_unique_nonempty_lines() {
    awk 'NF && !seen[$0]++ { c++ } END { print c + 0 }'
}

sample_mount_namespace_id() {
    local ns
    ns=$(readlink /proc/self/ns/mnt 2>/dev/null)
    if [ -n "$ns" ]; then
        printf '%s
' "$ns"
        return 0
    fi
    ns=$(ls -l /proc/self/ns/mnt 2>/dev/null | awk '{print $NF}')
    [ -n "$ns" ] || return 1
    printf '%s
' "$ns"
    return 0
}

collect_critical_mount_signature() {
    collect_mount_signature_from_file /proc/self/mountinfo
}
extract_kernel_date_string() {
    local text="$*"
    [ -n "$text" ] || return 1
    printf '%s
' "$text" | grep -oE '(Mon|Tue|Wed|Thu|Fri|Sat|Sun) [A-Z][a-z][a-z] [ 0-9][0-9] [0-9][0-9]:[0-9][0-9]:[0-9][0-9]( [A-Z0-9_+:-]+)? [0-9][0-9][0-9][0-9]' 2>/dev/null | head -1
}

parse_date_to_epoch() {
    local ds="$*"
    local out=""
    [ -n "$ds" ] || return 1

    out=$(date -u -d "$ds" +%s 2>/dev/null)
    case "$out" in
        ''|*[!0-9-]*) ;;
        *) printf '%s
' "$out"; return 0 ;;
    esac

    if command -v toybox >/dev/null 2>&1; then
        out=$(toybox date -u -d "$ds" +%s 2>/dev/null)
        case "$out" in
            ''|*[!0-9-]*) ;;
            *) printf '%s
' "$out"; return 0 ;;
        esac
    fi

    if command -v busybox >/dev/null 2>&1; then
        out=$(busybox date -u -D '%a %b %d %T %Z %Y' -d "$ds" +%s 2>/dev/null)
        case "$out" in
            ''|*[!0-9-]*) ;;
            *) printf '%s
' "$out"; return 0 ;;
        esac
        out=$(busybox date -u -D '%a %b %e %T %Z %Y' -d "$ds" +%s 2>/dev/null)
        case "$out" in
            ''|*[!0-9-]*) ;;
            *) printf '%s
' "$out"; return 0 ;;
        esac
    fi

    return 1
}

format_epoch_utc() {
    local ts="$1"
    local out=""
    [ -n "$ts" ] || return 1

    out=$(date -u -d "@$ts" '+%Y-%m-%d %H:%M:%S UTC' 2>/dev/null)
    [ -n "$out" ] && { printf '%s
' "$out"; return 0; }

    if command -v toybox >/dev/null 2>&1; then
        out=$(toybox date -u -d "@$ts" '+%Y-%m-%d %H:%M:%S UTC' 2>/dev/null)
        [ -n "$out" ] && { printf '%s
' "$out"; return 0; }
    fi

    printf '%s
' "$ts"
    return 0
}

sleep_small_jitter() {
    local d
    d=$(awk 'BEGIN{srand(); printf "%.1f\n", 0.3 + rand() * 0.9}' </dev/null 2>/dev/null)
    [ -n "$d" ] || d="1"
    sleep "$d" 2>/dev/null || sleep 1
}

sample_pid_mount_namespace_id() {
    local pid="$1"
    local ns
    [ -n "$pid" ] || return 1
    ns=$(readlink "/proc/$pid/ns/mnt" 2>/dev/null)
    if [ -n "$ns" ]; then
        printf '%s
' "$ns"
        return 0
    fi
    ns=$(ls -l "/proc/$pid/ns/mnt" 2>/dev/null | awk '{print $NF}')
    [ -n "$ns" ] || return 1
    printf '%s
' "$ns"
    return 0
}


collect_mount_signature_from_file() {
    local mountinfo_file="$1"
    [ -r "$mountinfo_file" ] || return 1
    awk '
BEGIN {
    target_regex = "^(/(/|$)|/system(/|$)|/system_root(/|$)|/system_ext(/|$)|/vendor(/|$)|/product(/|$)|/odm(/|$)|/vendor_dlkm(/|$)|/odm_dlkm(/|$)|/system_dlkm(/|$)|/apex(/|$)|/proc(/|$)|/sys(/|$)|/dev(/|$)|/metadata(/|$)|/mnt(/|$)|/data(/|$))"
}
function sort_csv(v,    n,i,j,a,tmp,out) {
    n = split(v, a, ",")
    for (i = 1; i <= n; i++) if (a[i] == "") a[i] = "-"
    for (i = 1; i <= n; i++) {
        for (j = i + 1; j <= n; j++) {
            if (a[j] < a[i]) { tmp = a[i]; a[i] = a[j]; a[j] = tmp }
        }
    }
    out = ""
    for (i = 1; i <= n; i++) out = out (i == 1 ? "" : ",") a[i]
    return out
}
{
    line = $0
    idx = index(line, " - ")
    if (idx == 0) next

    left = substr(line, 1, idx - 1)
    right = substr(line, idx + 3)
    split(left, lf, " ")
    split(right, rf, " ")

    mount_id = lf[1]
    parent_id = lf[2]
    majmin = lf[3]
    root = lf[4]
    mount_point = lf[5]
    mount_opts = sort_csv(lf[6])

    if (mount_point !~ target_regex) next

    optional = ""
    for (i = 7; i <= length(lf); i++) {
        if (lf[i] == "") continue
        optional = optional (optional == "" ? "" : ",") lf[i]
    }

    fs_type = rf[1]
    source = rf[2]
    super_opts = sort_csv(rf[3])

    printf "%s|%s|%s|%s|%s|%s|%s|%s|%s\n", mount_point, mount_id, parent_id, root, fs_type, source, mount_opts, super_opts, optional
}' "$mountinfo_file" 2>/dev/null | sort 2>/dev/null
}
port_listen_hit_hex() {
    local port_regex="$1"
    local tbl hit=""
    [ -n "$port_regex" ] || return 1
    for tbl in /proc/net/tcp /proc/net/tcp6; do
        [ -r "$tbl" ] || continue
        hit=$(awk -v re="$port_regex" 'NR > 1 && $4 == "0A" && $2 ~ ":" re "$" { print $0 }' "$tbl" 2>/dev/null | head -5)
        if [ -n "$hit" ]; then
            printf '%s
' "$hit"
            return 0
        fi
    done
    return 1
}

maps_wx_hits() {
    [ -r /proc/self/maps ] || return 1
    awk '$2 ~ /w/ && $2 ~ /x/ && $0 !~ /ashmem|kgsl|jit-cache|jit-zygote|memfd:jit-cache|webview_zygote|app_process|dalvik-jit-code-cache/ {print}' /proc/self/maps 2>/dev/null | head -5
}

