path_runtime_library_allowed() {
    case "$1" in
        /data/data/*/files/usr/lib*|/data/user/*/*/files/usr/lib*|/mnt/expand/*/user/*/*/files/usr/lib*|/mnt/expand/*/user_de/*/*/files/usr/lib*|/data/app/*|/mnt/expand/*/app/*)
            return 0
