path_high_risk_injection_location() {
    local p="$1"
    path_runtime_shell_allowed "$p" && return 1
    path_runtime_library_allowed "$p" && return 1
    printf '%s\n' "$p" | grep -qE '^(/data/local/tmp/|/data/adb/|/cache/|/metadata/|/persist/|/sdcard/|/storage/|/mnt/(user|runtime|media_rw)/)'
}

library_path_has_high_risk_entry() {
    local oldifs entry
    oldifs="$IFS"
    IFS=':'
    for entry in $1; do
        [ -n "$entry" ] || continue
        path_runtime_library_allowed "$entry" && continue
        printf '%s\n' "$entry" | grep -qE '^(/data/local/tmp/|/data/adb/|/cache/|/metadata/|/persist/|/sdcard/|/storage/|/mnt/(user|runtime|media_rw)/)' && {
            IFS="$oldifs"
            return 0
        }
    done
    IFS="$oldifs"
