}

mountinfo_has_android_app_data_isolation() {
    local f="$1"
    [ -r "$f" ] || return 1
    awk '
    index($0, " - ") > 0 {
        split(substr($0, 1, index($0, " - ") - 1), lf, " ")
        split(substr($0, index($0, " - ") + 3), rf, " ")
        mp = lf[5]
        root = lf[4]
        fs = rf[1]
        src = rf[2]
        if ((mp == "/data/data" || mp == "/data/user" || mp == "/data/user_de" || mp ~ "^/mnt/expand/[^/]+/user(_de)?$") && fs == "tmpfs" && src == "tmpfs") {
            ok = 1
            exit
        }
        if ((mp ~ "^/data/(data|user/0|user_de/0)/[^/]+" || mp ~ "^/mnt/expand/[^/]+/user(_de)?/[0-9]+/[^/]+") && (root ~ "^/data_mirror/data_(ce|de)/" || src ~ "^/data_mirror/data_(ce|de)/")) {
            ok = 1
            exit
        }
    }
    END { exit(ok ? 0 : 1) }
    ' "$f" 2>/dev/null
}

map_line_is_high_risk_injection() {
