task_name_keyword_hits() {
    local regex="$1"
    [ -d /proc/self/task ] || return 1
    (
        for f in /proc/self/task/*/comm; do
            [ -r "$f" ] || continue
            name=$(cat "$f" 2>/dev/null)
            [ -n "$name" ] || continue
            printf '%s %s\n' "${f%/comm}" "$name"
        done
    ) | grep -Ei "$regex" 2>/dev/null | head -8
}

proc_fd_link_keyword_hits() {
    local regex="$1"
    [ -d /proc/self/fd ] || return 1
    ls -l /proc/self/fd 2>/dev/null | grep -Ei "$regex" | head -8
}

collect_mounts_signature_from_file() {
    local mounts_file="$1"
    [ -r "$mounts_file" ] || return 1
    awk '
BEGIN {
    target_regex = "^(/(/|$)|/system(/|$)|/system_root(/|$)|/system_ext(/|$)|/vendor(/|$)|/product(/|$)|/odm(/|$)|/vendor_dlkm(/|$)|/odm_dlkm(/|$)|/system_dlkm(/|$)|/apex(/|$)|/proc(/|$)|/sys(/|$)|/dev(/|$)|/metadata(/|$)|/mnt(/|$)|/data(/|$))"
}
$2 ~ target_regex {
    printf "%s|%s|%s|%s\\n", $2, $3, $1, $4
}' "$mounts_file" 2>/dev/null | sort 2>/dev/null
}

critical_mount_duplicate_hits_from_file() {
    local mountinfo_file="$1"
    [ -r "$mountinfo_file" ] || return 1
    awk '
BEGIN {
    target_regex = "^(/(/|$)|/system(/|$)|/system_root(/|$)|/system_ext(/|$)|/vendor(/|$)|/product(/|$)|/odm(/|$)|/vendor_dlkm(/|$)|/odm_dlkm(/|$)|/system_dlkm(/|$)|/apex(/|$)|/proc(/|$)|/sys(/|$)|/dev(/|$)|/metadata(/|$)|/mnt(/|$)|/data(/|$))"
    writable_path_regex = "(^|/)(data|cache|metadata|mnt/user|mnt/runtime|mnt/expand|mnt/media_rw|storage|sdcard|persist)(/|$)"
    high_risk_kw_regex = "magisk|\.magisk|zygisk|zygisknext|kernelsu|(^|[^a-z])ksu([^a-z]|$)|ksud|apatch|susfs|lspd|lsposed|riru|shamiko|frida|mount_mask|mount_mark|hidemyapplist|hide[_-]?my[_-]?applist|resetprop"
}
{
    idx = index($0, " - ")
    if (idx == 0) next
    left = substr($0, 1, idx - 1)
    right = substr($0, idx + 3)
    split(left, lf, " ")
    split(right, rf, " ")
    mount_point = lf[5]
    mount_opts = lf[6]
    fs_type = rf[1]
    source = rf[2]
    super_opts = rf[3]
    lower = tolower($0)
    if (mount_point !~ target_regex) next
    cnt[mount_point]++
    has_rw = (mount_opts ~ /(^|,)rw(,|$)/)
    has_upper = ($0 ~ /(^|,)upperdir=[^,]+/ || super_opts ~ /(^|,)upperdir=[^,]+/)
    has_work = ($0 ~ /(^|,)workdir=[^,]+/ || super_opts ~ /(^|,)workdir=[^,]+/)
    has_lower = ($0 ~ /(^|,)lowerdir=[^,]+/ || super_opts ~ /(^|,)lowerdir=[^,]+/)
    super_ro = (super_opts ~ /(^|,)ro(,|$)/)
    lowerdir_writable = ($0 ~ "lowerdir=[^,]*" writable_path_regex || super_opts ~ "lowerdir=[^,]*" writable_path_regex)
    ro_target = (mount_point ~ /^\/(system(\/|$)|system_root(\/|$)|system_ext(\/|$)|vendor(\/|$)|product(\/|$)|odm(\/|$)|vendor_dlkm(\/|$)|odm_dlkm(\/|$)|system_dlkm(\/|$)|apex(\/|$))/)
    benign_overlay = (ro_target && fs_type == "overlay" && source == "overlay" && has_rw && super_ro && has_lower && !has_upper && !has_work && !lowerdir_writable && lower !~ high_risk_kw_regex)
    if (benign_overlay) benign[mount_point]++
}
END {
    for (k in cnt) {
        non_benign = cnt[k] - benign[k]
        if (cnt[k] > 1 && non_benign > 1) printf "%s|%d\n", k, cnt[k]
    }
}' "$mountinfo_file" 2>/dev/null | sort 2>/dev/null
}

