detect_root() {
    if [ "$(id -u)" -eq 0 ]; then
        echo "${RED}✗ 已Root (当前Shell)${RESET}"
        return 1
    fi

    if command -v su >/dev/null 2>&1; then
        if su -c id 2>/dev/null | grep -q "uid=0"; then
            echo "${RED}✗ 已Root (su命令可用)${RESET}"
            return 1
        fi
    fi

    echo "${GREEN}✓ 未检测到Root${RESET}"
    return 0
}

detect_bl() {
    local unlock_count=0
    local lock_count=0
    props=(
        "ro.boot.verifiedbootstate"
        "ro.boot.flash.locked"
        "ro.boot.vbmeta.device_state"
        "ro.boot.veritymode"
        "ro.boot.bootlock"
        "ro.oem_unlock_supported"
        "sys.oem_unlock_allowed"
        "ro.boot.warranty_bit"
        "ro.boot.secureboot"
        "ro.boot.dmverity"
        "ro.boot.enable_dm_verity"
    )
    for prop in "${props[@]}"; do
        value=$(getprop "$prop" 2>/dev/null)
        if [ -n "$value" ]; then
            case "$value" in
                "orange"|"yellow"|"0"|"unlocked"|"0x0"|"false"|"disabled")
                    unlock_count=$((unlock_count + 1))
                    ;;
                "green"|"1"|"locked"|"enforcing"|"0x1"|"true"|"enabled")
                    lock_count=$((lock_count + 1))
                    ;;
            esac
        fi
    done
    if [ $unlock_count -gt $lock_count ]; then
        echo "${RED}🔓 已解锁${RESET}"
        return 1
    elif [ $lock_count -gt $unlock_count ]; then
        echo "${GREEN}🔒 已锁定${RESET}"
        return 0
    elif [ $unlock_count -eq 0 ] && [ $lock_count -eq 0 ]; then
        echo "${RED}❓ 无法判断${RESET}"
        return 1
    else
        echo "${RED}⚠ 特征冲突${RESET}"
        return 1
    fi
}

