detect_hidden_api_policy() {
    local found=0
    local unreadable=0
    local prop val

    for prop in hidden_api_policy hidden_api_policy_p_apps hidden_api_policy_pre_p_apps; do
        if val=$(settings_get_global_safe "$prop"); then
            case "$val" in
                ""|"null")
                    ;;
                0|1)
                    echo "${RED}⚠ 检测到隐藏API策略放宽: global $prop = $val${RESET}"
                    found=1
                    ;;
                2|3)
                    echo "${YELLOW}⚠ 提示: 检测到显式隐藏API策略: global $prop = $val${RESET}"
                    ;;
                *)
                    echo "${RED}⚠ 检测到异常隐藏API策略值: global $prop = $val${RESET}"
                    found=1
                    ;;
            esac
        else
            echo "${YELLOW}⚠ 提示: 无法读取 global $prop，已跳过判定${RESET}"
            unreadable=1
        fi
    done

    if val=$(settings_get_global_safe hidden_api_blacklist_exemptions); then
        if [ -n "$val" ] && [ "$val" != "null" ]; then
            echo "${RED}⚠ 检测到隐藏API豁免名单: global hidden_api_blacklist_exemptions = $val${RESET}"
            found=1
        fi
    else
        echo "${YELLOW}⚠ 提示: 无法读取 global hidden_api_blacklist_exemptions，已跳过判定${RESET}"
        unreadable=1
    fi

    if [ $found -eq 0 ]; then
        [ $unreadable -eq 1 ] && echo "${YELLOW}⚠ 提示: 隐藏API策略存在读取失败项，本次未将其视为风险${RESET}"
        echo "${GREEN}✓ 未检测到隐藏API策略被放宽${RESET}"
        return 0
    fi
    return 1
}

detect_suspicious_mounts() {
    local mountinfo_file="/proc/self/mountinfo"
    [ -r "$mountinfo_file" ] || { echo "${YELLOW}⚠ 提示: 当前无法读取挂载信息${RESET}"; return 0; }

    local out1 out2 out3
    local ret1 ret2 ret3
    local merged_out=""
    local awk_scan='
BEGIN {
    ro_mount_regex = "^(/system(/|$)|/system_root(/|$)|/system_ext(/|$)|/vendor(/|$)|/product(/|$)|/odm(/|$)|/vendor_dlkm(/|$)|/odm_dlkm(/|$)|/system_dlkm(/|$)|/apex(/|$))"
    writable_path_regex = "(^|/)(data|cache|metadata|mnt/user|mnt/runtime|mnt/expand|mnt/media_rw|storage|sdcard|persist)(/|$)"
    high_risk_kw_regex = "magisk|\.magisk|zygisk|zygisknext|kernelsu|(^|[^a-z])ksu([^a-z]|$)|ksud|apatch|susfs|lspd|lsposed|riru|shamiko|frida|mount_mask|mount_mark|hidemyapplist|hide[_-]?my[_-]?applist|resetprop"
    RED = "\033[1;31m"
    RESET = "\033[0m"
}
{
    line = $0
    if (line ~ /^[[:space:]]*$/) next
    idx = index(line, " - ")
    if (idx == 0) next

    left = substr(line, 1, idx - 1)
    right = substr(line, idx + 3)

    split(left, lf, " ")
    split(right, rf, " ")

    mount_point = lf[5]
    mount_opts = lf[6]
    root = lf[4]
    fs_type = rf[1]
    source = rf[2]
    super_opts = rf[3]

    has_rw = (mount_opts ~ /(^|,)rw(,|$)/)
    has_upper = (line ~ /(^|,)upperdir=[^,]+/ || super_opts ~ /(^|,)upperdir=[^,]+/)
    has_work = (line ~ /(^|,)workdir=[^,]+/ || super_opts ~ /(^|,)workdir=[^,]+/)
    has_lower = (line ~ /(^|,)lowerdir=[^,]+/ || super_opts ~ /(^|,)lowerdir=[^,]+/)
    super_ro = (super_opts ~ /(^|,)ro(,|$)/)
    lowerdir_writable = (line ~ "lowerdir=[^,]*" writable_path_regex || super_opts ~ "lowerdir=[^,]*" writable_path_regex)
    mount_text = tolower(mount_point " " fs_type " " source " " mount_opts " " super_opts " " root)
    apex_root_tmpfs_rw_whitelist = (mount_point == "/apex" && root == "/" && fs_type == "tmpfs" && source == "tmpfs" && has_rw && !has_upper && !has_work)
    readonly_overlay_stack = (mount_point ~ ro_mount_regex && fs_type == "overlay" && source == "overlay" && has_rw && super_ro && has_lower && !has_upper && !has_work && !lowerdir_writable && mount_text !~ high_risk_kw_regex)

    if (mount_point ~ ro_mount_regex && has_rw) {
        if (apex_root_tmpfs_rw_whitelist || readonly_overlay_stack) next
        printf "%s⚠ 关键只读区域出现 rw 挂载: %s (fs:%s src:%s opts:%s)%s\n", RED, mount_point, fs_type, source, mount_opts, RESET
        printf "    挂载行: %s\n", line
        found = 1
        next
    }

    if (fs_type == "overlay" && (has_upper || has_work)) {
        printf "%s⚠ overlay 出现 upperdir/workdir: %s (src:%s)%s\n", RED, mount_point, source, RESET
        printf "    挂载行: %s\n", line
        found = 1
        next
    }

    if (fs_type == "overlay" && lowerdir_writable) {
        printf "%s⚠ overlay 的 lowerdir 指向可写路径: %s (src:%s)%s\n", RED, mount_point, source, RESET
        printf "    挂载行: %s\n", line
        found = 1
        next
    }

    if (mount_point == "/proc/sys" && has_rw) {
        printf "%s⚠ /proc/sys 被单独挂成可写: %s%s\n", RED, mount_point, RESET
        printf "    挂载行: %s\n", line
        found = 1
        next
    }

    if (mount_text ~ high_risk_kw_regex) {
        printf "%s⚠ 挂载行命中高风险关键词: %s (fs:%s src:%s)%s\n", RED, mount_point, fs_type, source, RESET
        printf "    挂载行: %s\n", line
        found = 1
        next
    }
}
END { if (found) exit 1; exit 0 }'

    out1=$(awk "$awk_scan" "$mountinfo_file" 2>/dev/null); ret1=$?
    sleep_small_jitter
    out2=$(awk "$awk_scan" "$mountinfo_file" 2>/dev/null); ret2=$?
    sleep_small_jitter
    out3=$(awk "$awk_scan" "$mountinfo_file" 2>/dev/null); ret3=$?

    if [ -z "$out1" ] && [ -z "$out2" ] && [ -z "$out3" ] && { [ $ret1 -ne 0 ] || [ $ret2 -ne 0 ] || [ $ret3 -ne 0 ]; }; then
        local compat_raw=""
        compat_raw=$(grep -Ei ' /proc/sys(/| )| /system(/| )| /system_root(/| )| /system_ext(/| )| /vendor(/| )| /product(/| )| /odm(/| )| /vendor_dlkm(/| )| /odm_dlkm(/| )| /system_dlkm(/| )| /apex(/| )| overlay|magisk|\.magisk|zygisk|kernelsu|ksud|apatch|susfs|lspd|lsposed|riru|shamiko|frida|mount_mask|mount_mark|hidemyapplist|resetprop' "$mountinfo_file" 2>/dev/null | grep -Ei ' rw[, ]|upperdir=|workdir=|lowerdir=.*(/data/|/cache/|/metadata/|/mnt/user/|/mnt/runtime/|/mnt/expand/|/mnt/media_rw/|/storage/|/sdcard/|/persist/)|magisk|\.magisk|zygisk|kernelsu|ksud|apatch|susfs|lspd|lsposed|riru|shamiko|frida|mount_mask|mount_mark|hidemyapplist|resetprop' | grep -Eiv '^[0-9]+ [0-9]+ [0-9]+:[0-9]+ / /apex rw,[^ ]* - tmpfs tmpfs rw' | head -20)
        echo "${YELLOW}⚠ 可疑挂载点检测器执行异常，结构化扫描失败${RESET}"
        echo "    awk_exit_codes: ${ret1}/${ret2}/${ret3}"
        if [ -n "$compat_raw" ]; then
            echo "${YELLOW}  兼容模式命中原始挂载行:${RESET}"
            echo "$compat_raw"
            return 1
        fi
        return 2
    fi

    merged_out=$(printf '%s\n%s\n%s\n' "$out1" "$out2" "$out3" | sed '/^$/d' | awk '!seen[$0]++' 2>/dev/null)

    if [ -n "$merged_out" ]; then
        echo "$merged_out"
        return 1
    fi

    if [ $ret1 -eq 0 ] && [ $ret2 -eq 0 ] && [ $ret3 -eq 0 ]; then
        echo "${GREEN}✓ 未检测到可疑挂载点${RESET}"
        return 0
    fi

    return 2
}

detect_global_mount_isolation() {
    local found=0
    local hinted=0
    local mountinfo_file="/proc/self/mountinfo"
    local init_mountinfo_file="/proc/1/mountinfo"
    local real_data_data="" link_data_data=""
    local mount_out1="" mount_out2="" mount_out3="" self_out="" init_out="" maps_hit=""
    local self_ns="" init_ns=""

    if [ -e /data/data ] 2>/dev/null || [ -L /data/data ] 2>/dev/null; then
        real_data_data=$(resolve_path /data/data)
        link_data_data=$(readlink /data/data 2>/dev/null)
        if [ -L /data/data ] 2>/dev/null && [ -n "$real_data_data" ] && [ "$real_data_data" != "/data/user/0" ] && [ "$real_data_data" != "/data/data" ]; then
            echo "${RED}⚠ /data/data 解析目标异常: $real_data_data${RESET}"
            found=1
        fi
    fi

    if [ -r "$mountinfo_file" ]; then
        local awk_scan='
BEGIN {
    target_regex = "^(/data/(data|user|user/0|user_de|user_de/0|app|adb)(/|$)|/mnt/expand/[^/]+/user(_de)?(/|$))"
    strong_kw_regex = "hidemyapplist|hide[_-]?my[_-]?applist|mount_mask|mount_mark|force[_-]?isolation|magic[_-]?mount|magisk|zygisk|kernelsu|(^|[^a-z])ksu([^a-z]|$)|apatch"
    RED = "\033[1;31m"
    RESET = "\033[0m"
}
{
    line = $0
    idx = index(line, " - ")
    if (idx == 0) next
    left = substr(line, 1, idx - 1)
    right = substr(line, idx + 3)
    split(left, lf, " ")
    split(right, rf, " ")
    mount_point = lf[5]
    root = lf[4]
    mount_opts = lf[6]
    fs_type = rf[1]
    source = rf[2]
    super_opts = rf[3]

    lower = tolower(line)
    has_kw = (lower ~ strong_kw_regex)
    has_upper = (line ~ /(^|,)upperdir=[^,]+/ || super_opts ~ /(^|,)upperdir=[^,]+/)
    has_work = (line ~ /(^|,)workdir=[^,]+/ || super_opts ~ /(^|,)workdir=[^,]+/)
    has_tmpfs = (fs_type == "tmpfs" && source == "tmpfs")
    is_target = (mount_point ~ target_regex || source ~ target_regex || root ~ target_regex)

    normal_data_mount = ((mount_point == "/data/data" || mount_point == "/data/user/0" || mount_point == "/data/user" || mount_point == "/data/user_de" || mount_point == "/data/user_de/0") && (fs_type == "f2fs" || fs_type == "ext4" || fs_type == "erofs") && source ~ "^/dev/block/" && !has_kw && !has_upper && !has_work)

    app_data_isolation_tmpfs = ((mount_point == "/data/data" || mount_point == "/data/user" || mount_point == "/data/user_de" || mount_point ~ "^/mnt/expand/[^/]+/user(_de)?$") && has_tmpfs && !has_kw && !has_upper && !has_work)

    app_data_isolation_bind = (((mount_point ~ "^/data/(data|user/0|user_de/0)/[^/]+" || mount_point ~ "^/mnt/expand/[^/]+/user(_de)?/[0-9]+/[^/]+") && (root ~ "^/data_mirror/data_(ce|de)/" || source ~ "^/data_mirror/data_(ce|de)/")) && !has_kw && !has_upper && !has_work)

    app_data_alias_bind = (((mount_point == "/data/data" && (source ~ "^/data/user/0$" || root ~ "^/data/user/0$")) || ((mount_point == "/data/user/0" || mount_point == "/data/user_de/0") && (source == "none" || source ~ "^/data_mirror/data_(ce|de)$" || root ~ "^/data_mirror/data_(ce|de)$"))) && !has_kw && !has_upper && !has_work)

    if (!is_target && !has_kw) next
    if (normal_data_mount || app_data_isolation_tmpfs || app_data_isolation_bind || app_data_alias_bind) next

    if ((mount_point == "/data/data" || mount_point == "/data/user/0" || mount_point == "/data/user" || mount_point == "/data/user_de" || mount_point == "/data/user_de/0") &&
        (has_kw || fs_type == "overlay" || has_upper || has_work || source ~ "^/mnt/" || (source ~ "^/data_mirror/" && source !~ "^/data_mirror/data_(ce|de)$"))) {
        printf "%s⚠ /data 关键目录可疑挂载: %s (fs:%s src:%s)%s
", RED, mount_point, fs_type, source, RESET
        printf "    挂载行: %s
", line
        found = 1
        next
    }

    if (has_kw && (mount_point ~ "^/data/" || source ~ "^/data/" || root ~ "^/data/" || source ~ "^/mnt/" || mount_point ~ "^/mnt/")) {
        printf "%s⚠ /data 相关隔离关键词挂载: %s (fs:%s src:%s)%s
", RED, mount_point, fs_type, source, RESET
        printf "    挂载行: %s
", line
        found = 1
    }
}
END { if (found) exit 1; exit 0 }'
        mount_out1=$(awk "$awk_scan" "$mountinfo_file" 2>/dev/null)
        sleep_small_jitter
        mount_out2=$(awk "$awk_scan" "$mountinfo_file" 2>/dev/null)
        sleep_small_jitter
        mount_out3=$(awk "$awk_scan" "$mountinfo_file" 2>/dev/null)

        self_out=$(printf '%s
%s
%s
' "$mount_out1" "$mount_out2" "$mount_out3" | sed '/^$/d' | awk '!seen[$0]++' 2>/dev/null)
        self_ns=$(sample_pid_mount_namespace_id self 2>/dev/null)
        init_ns=$(sample_pid_mount_namespace_id 1 2>/dev/null)

        if [ -r "$init_mountinfo_file" ]; then
            init_out=$(awk "$awk_scan" "$init_mountinfo_file" 2>/dev/null)
        fi

        if [ -n "$self_out" ]; then
            if [ "$mount_out1" != "$mount_out2" ] || [ "$mount_out2" != "$mount_out3" ]; then
                echo "${YELLOW}⚠ 提示: /data 相关挂载在短时间内发生变化${RESET}"
                hinted=1
            fi

            if [ -n "$init_out" ] || { [ -n "$self_ns" ] && [ -n "$init_ns" ] && [ "$self_ns" = "$init_ns" ]; }; then
                echo "$self_out"
                [ -n "$init_out" ] && [ "$init_out" != "$self_out" ] && {
                    echo "${YELLOW}⚠ 提示: init 命名空间亦存在 /data 可疑挂载痕迹${RESET}"
                }
                found=1
            else
                echo "${YELLOW}⚠ 提示: 当前进程命中 /data 隔离挂载形态，但 init 命名空间未命中；已按应用私有挂载命名空间降级为提示${RESET}"
                echo "${YELLOW}  当前进程命名空间:${RESET} ${self_ns:-未知}"
                echo "${YELLOW}  init 命名空间:${RESET} ${init_ns:-未知}"
                hinted=1
            fi
        fi
    fi

    maps_hit=$(maps_keyword_hits 'hidemyapplist|hide[_-]?my[_-]?applist|mount_mask|mount_mark|force[_-]?isolation|magic[_-]?mount|magisk|zygisk|kernelsu|(^|[^a-z])ksu([^a-z]|$)|apatch')
    if [ -n "$maps_hit" ]; then
        if [ $found -eq 1 ]; then
            echo "${RED}⚠ 检测到挂载隔离相关内存特征:${RESET}"
            echo "$maps_hit" | while IFS= read -r line; do [ -n "$line" ] && echo "    $line"; done
        else
            echo "${YELLOW}⚠ 提示: 命中挂载隔离相关内存关键词，但未发现对应异常挂载${RESET}"
            echo "$maps_hit" | while IFS= read -r line; do [ -n "$line" ] && echo "    $line"; done
            hinted=1
        fi
        [ $found -eq 1 ] && found=1
    fi

    if [ $found -eq 0 ]; then
        [ $hinted -eq 1 ] && echo "${YELLOW}⚠ 提示: 已忽略 Android 官方应用数据隔离挂载形态${RESET}"
        echo "${GREEN}✓ 未检测到 /data 挂载隔离特征${RESET}"
        return 0
    fi
    return 1
}

detect_dynamic_mount_changes() {
    local mountinfo_file="/proc/self/mountinfo"
    local mounts_file="/proc/self/mounts"
    [ -r "$mountinfo_file" ] || { echo "${YELLOW}⚠ 提示: 当前无法读取挂载信息${RESET}"; return 0; }

    local found=0 hinted=0
    local base_ns cur_ns pid1_ns=""
    local base_sig cur_sig pid1_sig="" pid1_cur_sig=""
    local base_msig cur_msig
    local base_count cur_count
    local base_overlay cur_overlay
    local base_dups cur_dups
    local i sig_drift=0 msig_drift=0 count_drift=0 overlay_drift=0 pid1_drift=0
    local private_ns=0 allow_private_delta=0

    base_ns=$(sample_pid_mount_namespace_id self 2>/dev/null)
    base_sig=$(collect_mount_signature_from_file "$mountinfo_file" 2>/dev/null)
    base_msig=$(collect_mounts_signature_from_file "$mounts_file" 2>/dev/null)
    base_count=$(wc -l < "$mountinfo_file" 2>/dev/null | tr -d ' ')
    base_overlay=$(mount_sig_count_overlays "$base_sig")
    base_dups=$(critical_mount_duplicate_hits_from_file "$mountinfo_file" 2>/dev/null)

    if [ -r /proc/1/mountinfo ] 2>/dev/null; then
        pid1_ns=$(sample_pid_mount_namespace_id 1 2>/dev/null)
        [ -n "$base_ns" ] && [ -n "$pid1_ns" ] && [ "$base_ns" != "$pid1_ns" ] && private_ns=1
        mountinfo_has_android_app_data_isolation "$mountinfo_file" && allow_private_delta=1
        pid1_sig=$(collect_mount_signature_from_file /proc/1/mountinfo 2>/dev/null)
    fi

    if [ -n "$base_dups" ]; then
        if [ $private_ns -eq 1 ] && [ $allow_private_delta -eq 1 ]; then
            echo "${YELLOW}⚠ 提示: 当前命名空间存在重复挂载点，但已按 Android 应用私有数据隔离降级${RESET}"
            hinted=1
        else
            echo "${RED}⚠ 检测到关键路径存在重复挂载点（疑似 overmount / bind 影子挂载）${RESET}"
            echo "$base_dups" | while IFS='|' read -r mp cnt; do [ -n "$mp" ] && echo "    $mp 重复 $cnt 次"; done
            found=1
        fi
    fi

    if [ -n "$pid1_sig" ] && [ -n "$base_sig" ] && [ "$pid1_sig" != "$base_sig" ]; then
        if [ $private_ns -eq 1 ] && [ $allow_private_delta -eq 1 ]; then
            echo "${YELLOW}⚠ 提示: 当前进程关键挂载视图与 init 不一致，但命中 Android 应用私有挂载命名空间形态${RESET}"
            echo "    当前命名空间: ${base_ns:-未知}"
            echo "    init 命名空间: ${pid1_ns:-未知}"
            hinted=1
        else
            echo "${RED}⚠ 当前进程关键挂载视图与 init 进程不一致${RESET}"
            echo "    当前命名空间: ${base_ns:-未知}"
            echo "    init 命名空间: ${pid1_ns:-未知}"
            echo "${YELLOW}  当前进程关键挂载(前6行):${RESET}"
            printf '%s
' "$base_sig" | sed '/^$/d' | head -6 | while IFS= read -r line; do [ -n "$line" ] && echo "    $line"; done
            echo "${YELLOW}  init 进程关键挂载(前6行):${RESET}"
            printf '%s
' "$pid1_sig" | sed '/^$/d' | head -6 | while IFS= read -r line; do [ -n "$line" ] && echo "    $line"; done
            found=1
        fi
    fi

    i=1
    while [ $i -le 12 ]; do
        sleep_small_jitter
        cur_ns=$(sample_pid_mount_namespace_id self 2>/dev/null)
        cur_sig=$(collect_mount_signature_from_file "$mountinfo_file" 2>/dev/null)
        cur_msig=$(collect_mounts_signature_from_file "$mounts_file" 2>/dev/null)
        cur_count=$(wc -l < "$mountinfo_file" 2>/dev/null | tr -d ' ')
        cur_overlay=$(mount_sig_count_overlays "$cur_sig")
        cur_dups=$(critical_mount_duplicate_hits_from_file "$mountinfo_file" 2>/dev/null)

        if [ -n "$base_ns" ] && [ -n "$cur_ns" ] && [ "$base_ns" != "$cur_ns" ]; then
            echo "${RED}⚠ 检测到挂载命名空间发生切换${RESET}"
            echo "    基线命名空间: $base_ns"
            echo "    当前命名空间: $cur_ns"
            found=1
            break
        fi

        if [ -n "$base_sig" ] && [ -n "$cur_sig" ] && [ "$base_sig" != "$cur_sig" ]; then
            sig_drift=$((sig_drift + 1))
        fi
        if [ -n "$base_msig" ] && [ -n "$cur_msig" ] && [ "$base_msig" != "$cur_msig" ]; then
            msig_drift=$((msig_drift + 1))
        fi
        if [ -n "$base_overlay" ] && [ -n "$cur_overlay" ] && [ "$base_overlay" != "$cur_overlay" ]; then
            overlay_drift=$((overlay_drift + 1))
        fi
        if [ -n "$base_count" ] && [ -n "$cur_count" ] && [ "$base_count" != "$cur_count" ]; then
            count_drift=$((count_drift + 1))
        fi

        if [ -n "$cur_dups" ]; then
            if [ $private_ns -eq 1 ] && [ $allow_private_delta -eq 1 ]; then
                hinted=1
            else
                echo "${RED}⚠ 采样期间检测到关键路径重复挂载点${RESET}"
                echo "$cur_dups" | while IFS='|' read -r mp cnt; do [ -n "$mp" ] && echo "    $mp 重复 $cnt 次"; done
                found=1
                break
            fi
        fi

        if [ -n "$pid1_ns" ] && [ -r /proc/1/mountinfo ] 2>/dev/null; then
            pid1_cur_sig=$(collect_mount_signature_from_file /proc/1/mountinfo 2>/dev/null)
            if [ -n "$pid1_cur_sig" ] && [ -n "$pid1_sig" ] && [ "$pid1_cur_sig" != "$pid1_sig" ]; then
                pid1_drift=$((pid1_drift + 1))
            fi
        fi

        i=$((i + 1))
    done

    if [ $found -eq 0 ] && { [ $sig_drift -gt 0 ] || [ $msig_drift -gt 1 ] || [ $overlay_drift -gt 0 ] || [ $pid1_drift -gt 0 ]; }; then
        if [ $private_ns -eq 1 ] && [ $allow_private_delta -eq 1 ] && [ $pid1_drift -eq 0 ] && [ $sig_drift -le 2 ] && [ $overlay_drift -eq 0 ]; then
            echo "${YELLOW}⚠ 提示: 当前私有挂载命名空间发生轻微视图漂移，已按 Android 应用数据隔离降级${RESET}"
            echo "    mountinfo 关键签名漂移次数: $sig_drift"
            echo "    mounts 关键签名漂移次数: $msig_drift"
            hinted=1
        elif [ $sig_drift -ge 2 ] || [ $overlay_drift -gt 0 ] || [ $pid1_drift -gt 0 ]; then
            echo "${RED}⚠ 检测到动态挂载切换/关键挂载视图漂移${RESET}"
            echo "    mountinfo 关键签名漂移次数: $sig_drift"
            echo "    mounts 关键签名漂移次数: $msig_drift"
            echo "    overlay 数量漂移次数: $overlay_drift"
            [ $pid1_drift -gt 0 ] && echo "    init 挂载视图漂移次数: $pid1_drift"
            echo "${YELLOW}  基线关键挂载(前6行):${RESET}"
            printf '%s
' "$base_sig" | sed '/^$/d' | head -6 | while IFS= read -r line; do [ -n "$line" ] && echo "    $line"; done
            echo "${YELLOW}  最后一次关键挂载(前6行):${RESET}"
            printf '%s
' "$cur_sig" | sed '/^$/d' | head -6 | while IFS= read -r line; do [ -n "$line" ] && echo "    $line"; done
            found=1
        else
            echo "${YELLOW}⚠ 提示: 关键挂载签名出现瞬时漂移，但未达到异常阈值${RESET}"
            hinted=1
        fi
    fi

    if [ $found -eq 1 ]; then
        return 1
    fi

    if [ $count_drift -gt 0 ]; then
        hinted=1
        echo "${YELLOW}⚠ 提示: 挂载总数在短时间内波动 $count_drift 次，但三重关键签名稳定${RESET}"
    fi
    [ $hinted -eq 1 ] && echo "${YELLOW}⚠ 提示: 动态挂载已启用命名空间 + mountinfo + mounts 三重检测${RESET}"
    echo "${GREEN}✓ 未检测到动态挂载切换/挂载间隙${RESET}"
    return 0
}

detect_kernel_version_consistency() {
    local found=0 hinted=0
    local uname_r uname_a uname_s osrelease proc_version kernel_version proc_release
    local direct_uname_r busybox_uname_r uname_path
    local sample1 sample2 sample3 os1 os2 os3 du1 du2 du3 keyword_hits

    uname_r=$(uname -r 2>/dev/null)
    uname_a=$(uname -a 2>/dev/null)
    uname_s=$(uname -s 2>/dev/null)
    osrelease=$(cat /proc/sys/kernel/osrelease 2>/dev/null)
    proc_version=$(cat /proc/version 2>/dev/null)
    kernel_version=$(cat /proc/sys/kernel/version 2>/dev/null)
    proc_release=$(kernel_release_from_proc_version "$proc_version")
    uname_path=$(command -v uname 2>/dev/null)

    if [ -x /system/bin/uname ] 2>/dev/null; then
        direct_uname_r=$(/system/bin/uname -r 2>/dev/null)
    elif command -v toybox >/dev/null 2>&1; then
        direct_uname_r=$(toybox uname -r 2>/dev/null)
    else
        direct_uname_r=""
    fi

    if command -v busybox >/dev/null 2>&1; then
        busybox_uname_r=$(busybox uname -r 2>/dev/null)
    else
        busybox_uname_r=""
    fi

    if [ -z "$uname_r" ] && [ -z "$osrelease" ] && [ -z "$proc_release" ]; then
        echo "${RED}⚠ 无法获取内核版本主数据源${RESET}"
        return 1
    fi

    [ -z "$uname_r" ] && uname_r="$osrelease"
    [ -z "$uname_r" ] && uname_r="$proc_release"

    if ! printf '%s
' "$uname_r" | grep -Eq '^[0-9A-Za-z._:+/-]+$'; then
        echo "${RED}⚠ 内核版本字符串含异常字符: $uname_r${RESET}"
        found=1
    fi

    if [ -n "$uname_s" ] && [ "$uname_s" != "Linux" ]; then
        echo "${RED}⚠ uname -s 异常: $uname_s${RESET}"
        found=1
    fi

    if [ -n "$osrelease" ] && [ "$uname_r" != "$osrelease" ]; then
        echo "${RED}⚠ uname -r 与 /proc/sys/kernel/osrelease 不一致: $uname_r <> $osrelease${RESET}"
        found=1
    fi

    if [ -n "$proc_release" ] && [ "$uname_r" != "$proc_release" ]; then
        echo "${RED}⚠ uname -r 与 /proc/version 解析出的 release 不一致: $uname_r <> $proc_release${RESET}"
        found=1
    fi

    if [ -n "$direct_uname_r" ] && [ "$uname_r" != "$direct_uname_r" ]; then
        echo "${RED}⚠ 当前 uname 调用链结果不一致: uname -r=$uname_r, 直接调用=$direct_uname_r${RESET}"
        found=1
    fi

    if [ -n "$busybox_uname_r" ] && [ "$uname_r" != "$busybox_uname_r" ]; then
        echo "${YELLOW}⚠ 提示: busybox uname -r 与当前 shell uname 不一致: $busybox_uname_r${RESET}"
        hinted=1
    fi

    if [ -n "$proc_version" ] && [ -n "$uname_r" ] && ! printf '%s
' "$proc_version" | grep -Fq "$uname_r"; then
        echo "${RED}⚠ /proc/version 未包含当前内核版本: $uname_r${RESET}"
        echo "    /proc/version: $proc_version"
        found=1
    fi

    if [ -n "$uname_a" ] && [ -n "$uname_r" ] && ! printf '%s
' "$uname_a" | grep -Fq "$uname_r"; then
        echo "${RED}⚠ uname -a 未包含 uname -r 返回值${RESET}"
        echo "    uname -a: $uname_a"
        found=1
    fi

    if [ -n "$uname_path" ]; then
        path_high_risk_injection_location "$uname_path" && {
            echo "${RED}⚠ uname 命令路径位于高风险注入目录: $uname_path${RESET}"
            found=1
        }
        path_runtime_shell_allowed "$uname_path" && {
            echo "${YELLOW}⚠ 提示: uname 来自应用内用户态工具链: $uname_path${RESET}"
            hinted=1
        }
    fi

    keyword_hits=$(printf '%s
%s
%s
%s
