}

detect_kernel_build_time() {
    local found=0 hinted=0
    local proc_version uname_v kernel_version version_sig=""
    local proc_time uname_time version_time sig_time primary_time
    local proc_epoch uname_epoch version_epoch sig_epoch epoch now boot_utc diff human_epoch human_boot
    local parsed_count max_epoch min_epoch host1 host2
    local p1 p2 p3 u1 u2 u3 v1 v2 v3

    proc_version=$(cat /proc/version 2>/dev/null)
    uname_v=$(uname -v 2>/dev/null)
    kernel_version=$(cat /proc/sys/kernel/version 2>/dev/null)
    [ -r /proc/version_signature ] && version_sig=$(cat /proc/version_signature 2>/dev/null)

    proc_time=$(extract_kernel_date_string "$proc_version")
    uname_time=$(extract_kernel_date_string "$uname_v")
    version_time=$(extract_kernel_date_string "$kernel_version")
    sig_time=$(extract_kernel_date_string "$version_sig")

    if [ -z "$proc_version" ] && [ -z "$uname_v" ] && [ -z "$kernel_version" ] && [ -z "$version_sig" ]; then
        echo "${RED}⚠ 无法读取内核构建信息源${RESET}"
        return 1
    fi

    proc_epoch=$(parse_date_to_epoch "$proc_time")
    uname_epoch=$(parse_date_to_epoch "$uname_time")
    version_epoch=$(parse_date_to_epoch "$version_time")
    sig_epoch=$(parse_date_to_epoch "$sig_time")

    parsed_count=0
    for e in "$proc_epoch" "$uname_epoch" "$version_epoch" "$sig_epoch"; do
        [ -n "$e" ] && parsed_count=$((parsed_count + 1))
    done

    if [ "$parsed_count" -ge 2 ] 2>/dev/null; then
        max_epoch=""
        min_epoch=""
        for e in "$proc_epoch" "$uname_epoch" "$version_epoch" "$sig_epoch"; do
            [ -n "$e" ] || continue
            [ -z "$max_epoch" ] && max_epoch="$e"
            [ -z "$min_epoch" ] && min_epoch="$e"
            [ "$e" -gt "$max_epoch" ] 2>/dev/null && max_epoch="$e"
            [ "$e" -lt "$min_epoch" ] 2>/dev/null && min_epoch="$e"
        done
        if [ -n "$max_epoch" ] && [ -n "$min_epoch" ] && [ $((max_epoch - min_epoch)) -gt 172800 ] 2>/dev/null; then
            echo "${RED}⚠ 内核构建时间多源不一致${RESET}"
            [ -n "$proc_time" ] && echo "    /proc/version: $proc_time"
            [ -n "$uname_time" ] && echo "    uname -v: $uname_time"
            [ -n "$version_time" ] && echo "    /proc/sys/kernel/version: $version_time"
            [ -n "$sig_time" ] && echo "    /proc/version_signature: $sig_time"
            found=1
        fi
    elif [ "$parsed_count" -eq 0 ] 2>/dev/null; then
        echo "${YELLOW}⚠ 提示: 构建时间格式不可解析；可能是可复现构建/定制格式，不单独判定异常${RESET}"
        [ -n "$proc_version" ] && echo "    /proc/version: $proc_version"
        hinted=1
    fi

    primary_time="$proc_time"
    [ -n "$primary_time" ] || primary_time="$uname_time"
    [ -n "$primary_time" ] || primary_time="$version_time"
    [ -n "$primary_time" ] || primary_time="$sig_time"
    epoch="$proc_epoch"
    [ -n "$epoch" ] || epoch="$uname_epoch"
    [ -n "$epoch" ] || epoch="$version_epoch"
    [ -n "$epoch" ] || epoch="$sig_epoch"
    now=$(date +%s 2>/dev/null)

    if [ -n "$epoch" ] && [ -n "$now" ]; then
        human_epoch=$(format_epoch_utc "$epoch")
        if [ "$epoch" -gt $((now + 86400)) ] 2>/dev/null; then
            echo "${RED}⚠ 内核构建时间位于未来: $human_epoch${RESET}"
            found=1
        fi
        if [ "$epoch" -lt 1420070400 ] 2>/dev/null; then
            echo "${RED}⚠ 内核构建时间异常陈旧: $human_epoch${RESET}"
            found=1
        fi

        for prop in ro.bootimage.build.date.utc ro.system.build.date.utc ro.vendor.build.date.utc ro.product.build.date.utc ro.system_ext.build.date.utc; do
            boot_utc=$(getprop "$prop" 2>/dev/null)
            [ -n "$boot_utc" ] || continue
            echo "$boot_utc" | grep -Eq '^[0-9]+$' 2>/dev/null || continue
            if [ "$epoch" -ge "$boot_utc" ] 2>/dev/null; then diff=$((epoch - boot_utc)); else diff=$((boot_utc - epoch)); fi
            human_boot=$(format_epoch_utc "$boot_utc")
            if [ "$diff" -gt 315360000 ] 2>/dev/null; then
                echo "${RED}⚠ 内核构建时间与系统参考时间差过大${RESET}"
                echo "    内核构建时间: $human_epoch"
                echo "    参考属性: $prop = $human_boot"
                found=1
                break
            elif [ "$diff" -gt 63072000 ] 2>/dev/null; then
                echo "${YELLOW}⚠ 提示: 内核构建时间与系统参考时间偏差较大${RESET}"
                echo "    内核构建时间: $human_epoch"
                echo "    参考属性: $prop = $human_boot"
                hinted=1
                break
            fi
        done
    fi

    p1=$(extract_kernel_date_string "$(cat /proc/version 2>/dev/null)"); sleep_small_jitter
    p2=$(extract_kernel_date_string "$(cat /proc/version 2>/dev/null)"); sleep_small_jitter
    p3=$(extract_kernel_date_string "$(cat /proc/version 2>/dev/null)")
    if [ -n "$p1" ] && { [ "$p1" != "$p2" ] || [ "$p2" != "$p3" ]; }; then
        echo "${RED}⚠ /proc/version 构建时间在短时间内动态变化${RESET}"
        echo "    第1次: $p1"
        echo "    第2次: $p2"
        echo "    第3次: $p3"
        found=1
    fi

    u1=$(extract_kernel_date_string "$(uname -v 2>/dev/null)"); sleep_small_jitter
    u2=$(extract_kernel_date_string "$(uname -v 2>/dev/null)"); sleep_small_jitter
    u3=$(extract_kernel_date_string "$(uname -v 2>/dev/null)")
    if [ -n "$u1" ] && { [ "$u1" != "$u2" ] || [ "$u2" != "$u3" ]; }; then
        echo "${RED}⚠ uname -v 构建时间在短时间内动态变化${RESET}"
        echo "    第1次: $u1"
        echo "    第2次: $u2"
        echo "    第3次: $u3"
        found=1
    fi

    v1=$(extract_kernel_date_string "$(cat /proc/sys/kernel/version 2>/dev/null)"); sleep_small_jitter
    v2=$(extract_kernel_date_string "$(cat /proc/sys/kernel/version 2>/dev/null)"); sleep_small_jitter
    v3=$(extract_kernel_date_string "$(cat /proc/sys/kernel/version 2>/dev/null)")
    if [ -n "$v1" ] && { [ "$v1" != "$v2" ] || [ "$v2" != "$v3" ]; }; then
        echo "${RED}⚠ /proc/sys/kernel/version 构建时间在短时间内动态变化${RESET}"
        echo "    第1次: $v1"
        echo "    第2次: $v2"
        echo "    第3次: $v3"
        found=1
    fi

    host1=$(printf '%s
' "$proc_version" | grep -oE ' [^ ]+@[^ ]+ ' 2>/dev/null | head -1)
    host2=$(printf '%s
' "$kernel_version" | grep -oE ' [^ ]+@[^ ]+ ' 2>/dev/null | head -1)
    if [ -n "$host1" ] && [ -n "$host2" ] && [ "$host1" != "$host2" ]; then
        echo "${YELLOW}⚠ 提示: 构建者/主机字段不一致:${RESET}"
        echo "    /proc/version: $host1"
        echo "    kernel.version: $host2"
        hinted=1
    fi

    if [ $found -eq 0 ]; then
        [ -n "$primary_time" ] && echo "${GREEN}✓ 内核构建时间检测完成: $primary_time${RESET}"
        [ $hinted -eq 1 ] && echo "${YELLOW}⚠ 提示: 已输出构建时间旁证${RESET}"
        return 0
    fi
    return 1
}

detect_uname_spoofing() {
    local found=0
    local uname_a uname_r uname_v proc_version kernel_version ostype osrelease direct_uname_r busybox_uname_r

    uname_a=$(uname -a 2>/dev/null)
    uname_r=$(uname -r 2>/dev/null)
    uname_v=$(uname -v 2>/dev/null)
    proc_version=$(cat /proc/version 2>/dev/null)
    kernel_version=$(cat /proc/sys/kernel/version 2>/dev/null)
    ostype=$(cat /proc/sys/kernel/ostype 2>/dev/null)
    osrelease=$(cat /proc/sys/kernel/osrelease 2>/dev/null)

    if [ -x /system/bin/uname ] 2>/dev/null; then
        direct_uname_r=$(/system/bin/uname -r 2>/dev/null)
    elif command -v toybox >/dev/null 2>&1; then
        direct_uname_r=$(toybox uname -r 2>/dev/null)
    else
        direct_uname_r=""
    fi
    command -v busybox >/dev/null 2>&1 && busybox_uname_r=$(busybox uname -r 2>/dev/null)

    if [ -n "$proc_version" ] && [ -n "$uname_r" ] && ! printf '%s\n' "$proc_version" | grep -Fq "$uname_r"; then
        echo "${RED}⚠ uname -r 与 /proc/version 不一致${RESET}"
        echo "    uname -a: $uname_a"
        echo "    /proc/version: $proc_version"
        found=1
    fi

    if [ -n "$kernel_version" ] && [ -n "$uname_v" ] && [ "$kernel_version" != "$uname_v" ]; then
        echo "${RED}⚠ uname -v 与 /proc/sys/kernel/version 不一致${RESET}"
        echo "    uname -v: $uname_v"
        echo "    kernel.version: $kernel_version"
        found=1
    fi

    if [ -n "$direct_uname_r" ] && [ -n "$uname_r" ] && [ "$direct_uname_r" != "$uname_r" ]; then
        echo "${RED}⚠ shell uname 与系统二进制结果不一致${RESET}"
        echo "    当前 uname -r: $uname_r"
        echo "    直接调用结果: $direct_uname_r"
        found=1
    fi

    if [ -n "$busybox_uname_r" ] && [ -n "$uname_r" ] && [ "$busybox_uname_r" != "$uname_r" ]; then
        echo "${YELLOW}⚠ 提示: busybox uname -r 与当前 shell 结果不一致: $busybox_uname_r${RESET}"
    fi

    if [ -n "$ostype" ] && [ "$ostype" != "Linux" ] 2>/dev/null; then
        echo "${RED}⚠ ostype 异常: $ostype${RESET}"
        found=1
    fi

    if [ -n "$osrelease" ] && [ -n "$uname_r" ] && [ "$osrelease" != "$uname_r" ]; then
        echo "${RED}⚠ osrelease 与 uname -r 不一致: $osrelease <> $uname_r${RESET}"
        found=1
    fi

    if [ -f /etc/ld.so.preload ] 2>/dev/null; then
        echo "${RED}⚠ 全局 preload 文件存在，uname 调用链可信度下降: /etc/ld.so.preload${RESET}"
        found=1
    fi

    [ -n "$LD_PRELOAD" ] && {
        echo "${RED}⚠ LD_PRELOAD 已设置，uname 调用链可信度下降: $LD_PRELOAD${RESET}"
        found=1
    }

    if [ $found -eq 0 ]; then
        echo "${GREEN}✓ 未检测到明显 uname 欺骗特征${RESET}"
        return 0
    fi
    return 1
}
