detect_emulator() {
    local found=0
    local emu_files="
/system/bin/qemu-props
/dev/socket/qemud
/dev/qemu_pipe
/system/lib/libc_malloc_debug_qemu.so
/sys/qemu_trace
/system/bin/androVM-prop
/system/bin/microvirt-prop
"
    local f
    for f in $emu_files; do
        if path_exists "$f"; then
            echo "${RED}⚠ 检测到模拟器特征文件: $f${RESET}"
            found=1
        fi
    done

    local emu_props="
ro.kernel.qemu
ro.hardware
ro.product.manufacturer
ro.product.model
ro.build.fingerprint
"
    local p val
    for p in $emu_props; do
        val=$(getprop "$p" 2>/dev/null)
        case "$p" in
            ro.kernel.qemu)
                [ "$val" = "1" ] && echo "${RED}⚠ 检测到模拟器属性: $p=$val${RESET}" && found=1
                ;;
            ro.hardware)
                echo "$val" | grep -qiE "goldfish|ranchu|vbox|qemu" && echo "${RED}⚠ 检测到模拟器硬件: $p=$val${RESET}" && found=1
                ;;
            ro.product.manufacturer)
                echo "$val" | grep -qiE "Genymotion" && echo "${RED}⚠ 检测到模拟器厂商: $p=$val${RESET}" && found=1
                ;;
            ro.product.model)
                echo "$val" | grep -qiE "sdk_gphone|Android SDK built for x86" && echo "${RED}⚠ 检测到模拟器型号: $p=$val${RESET}" && found=1
                ;;
            ro.build.fingerprint)
                echo "$val" | grep -qiE "sdk_gphone|generic_x86|generic_arm64" && echo "${RED}⚠ 检测到模拟器指纹: $p=$val${RESET}" && found=1
                ;;
        esac
    done

    if path_exists "/dev/vboxguest"; then
        echo "${RED}⚠ 检测到VirtualBox模拟器特征${RESET}"
        found=1
    fi

    if [ -f /proc/cpuinfo ] && grep -qi "goldfish" /proc/cpuinfo 2>/dev/null; then
        echo "${RED}⚠ 检测到CPU信息包含goldfish (模拟器特征)${RESET}"
        found=1
    fi

    if command -v ip >/dev/null 2>&1 && ip link show 2>/dev/null | grep -q "eth0"; then
        echo "${YELLOW}⚠ 提示: 存在eth0网卡，单独不作为模拟器判定依据${RESET}"
    fi

    if [ $found -eq 0 ]; then
        echo "${GREEN}✓ 未检测到模拟器特征${RESET}"
        return 0
    fi
    return 1
}

detect_syscall_hooking() {
    local found=0
    local hinted=0
    local tracer scope maps matches suspicious_regions hook_procs preload_file env_preload env_audit env_libpath
    local unix_hits fd_hits task_hits port_hits suspect_writable_maps
    local strong_regex='frida|frida-agent|frida-gadget|gum-js-loop|pool-frida|linjector|lspd|lsposed|edxp|taichi|riru|hidemyapplist|hide[_-]?my[_-]?applist|zygisk|zygisknext|shamiko|xposed|magisk|kernelsu|(^|[^a-z])ksu([^a-z]|$)|ksud|apatch'

    if [ -r /proc/self/status ]; then
        tracer=$(grep -i '^TracerPid:' /proc/self/status 2>/dev/null | awk '{print $2}')
        if [ -n "$tracer" ] && [ "$tracer" -ne 0 ] 2>/dev/null; then
            echo "${RED}⚠ 检测到进程被跟踪 (TracerPid=$tracer)${RESET}"
            found=1
        fi
    fi

    env_preload="${LD_PRELOAD}"
    [ -n "$env_preload" ] || env_preload=$(read_environ_var_like LD_PRELOAD 2>/dev/null | sed 's/^LD_PRELOAD=//')
    env_audit="${LD_AUDIT}"
    [ -n "$env_audit" ] || env_audit=$(read_environ_var_like LD_AUDIT 2>/dev/null | sed 's/^LD_AUDIT=//')
    env_libpath="${LD_LIBRARY_PATH}"
    [ -n "$env_libpath" ] || env_libpath=$(read_environ_var_like LD_LIBRARY_PATH 2>/dev/null | sed 's/^LD_LIBRARY_PATH=//')

    [ -n "$env_preload" ] && { echo "${RED}⚠ LD_PRELOAD 已设置: $env_preload${RESET}"; found=1; }
    [ -n "$env_audit" ] && { echo "${RED}⚠ LD_AUDIT 已设置: $env_audit${RESET}"; found=1; }
    if [ -n "$env_libpath" ]; then
        if library_path_has_high_risk_entry "$env_libpath"; then
            echo "${RED}⚠ LD_LIBRARY_PATH 含高风险注入路径: $env_libpath${RESET}"
            found=1
        else
            echo "${YELLOW}⚠ 提示: LD_LIBRARY_PATH 已设置，但未命中高风险目录${RESET}"
            hinted=1
        fi
    fi

    if [ -f /etc/ld.so.preload ] 2>/dev/null; then
        preload_file=$(sed -n '1,10p' /etc/ld.so.preload 2>/dev/null)
        echo "${RED}⚠ 检测到全局 preload 文件: /etc/ld.so.preload${RESET}"
        [ -n "$preload_file" ] && echo "$preload_file" | while IFS= read -r line; do echo "    $line"; done
        found=1
    fi

    port_hits=$(port_listen_hit_hex '69A2|69A3')
    if [ -n "$port_hits" ]; then
        echo "${RED}⚠ 检测到疑似 Frida 端口监听 (27042/27043)${RESET}"
        echo "$port_hits" | while IFS= read -r line; do [ -n "$line" ] && echo "    $line"; done
        found=1
    fi

    unix_hits=$(proc_net_unix_keyword_hits "$strong_regex")
    if [ -n "$unix_hits" ]; then
        echo "${RED}⚠ 检测到本地 Unix Socket / 管道命中 Hook 关键字:${RESET}"
        echo "$unix_hits" | while IFS= read -r line; do [ -n "$line" ] && echo "    $line"; done
        found=1
    fi

    task_hits=$(task_name_keyword_hits 'gum-js-loop|pool-frida|frida|lsposed|zygisk|shamiko|kernelsu|apatch|xposed|taichi|edxp|riru|hidemyapplist|hide[_-]?my[_-]?applist')
    if [ -n "$task_hits" ]; then
        echo "${RED}⚠ 检测到线程名命中 Hook / 注入关键字:${RESET}"
        echo "$task_hits" | while IFS= read -r line; do [ -n "$line" ] && echo "    $line"; done
        found=1
    fi

    fd_hits=$(proc_fd_link_keyword_hits "$strong_regex")
    if [ -n "$fd_hits" ]; then
        echo "${RED}⚠ 检测到 fd 链接命中 Hook / 注入关键字:${RESET}"
        echo "$fd_hits" | while IFS= read -r line; do [ -n "$line" ] && echo "    $line"; done
        found=1
    fi

    if [ -r /proc/self/maps ]; then
        maps=$(cat /proc/self/maps 2>/dev/null)
        matches=$(printf '%s
' "$maps" | grep -Ei "$strong_regex" 2>/dev/null | head -12)
        if [ -n "$matches" ]; then
            echo "${RED}⚠ 检测到可疑 Hook/注入库:${RESET}"
            echo "$matches" | while IFS= read -r line; do [ -n "$line" ] && echo "    $line"; done
            found=1
        fi

        suspect_writable_maps=$(printf '%s
' "$maps" | awk '$NF != "" {print}' 2>/dev/null | while IFS= read -r line; do map_line_is_high_risk_injection "$line" && echo "$line"; done | head -8)
        if [ -n "$suspect_writable_maps" ]; then
            echo "${RED}⚠ 检测到来自高风险目录/关键字的映射库或文件:${RESET}"
            echo "$suspect_writable_maps" | while IFS= read -r line; do [ -n "$line" ] && echo "    $line"; done
            found=1
        fi

        suspicious_regions=$(maps_wx_hits)
        if [ -n "$suspicious_regions" ]; then
            echo "${RED}⚠ 检测到可写且可执行内存区域:${RESET}"
            echo "$suspicious_regions" | head -5 | while IFS= read -r line; do [ -n "$line" ] && echo "    $line"; done
            found=1
        fi
    fi

    if [ -f /proc/sys/kernel/yama/ptrace_scope ]; then
        scope=$(cat /proc/sys/kernel/yama/ptrace_scope 2>/dev/null)
        [ "$scope" = "0" ] && { echo "${YELLOW}⚠ 提示: ptrace_scope=0，环境更容易被调试/注入${RESET}"; hinted=1; }
    fi

    if command -v ps >/dev/null 2>&1; then
        hook_procs=$(ps -A 2>/dev/null | grep -Ei "$strong_regex" | grep -v grep | head -12)
        if [ -n "$hook_procs" ]; then
            echo "${RED}⚠ 检测到 Hook/注入相关进程:${RESET}"
            echo "$hook_procs" | while IFS= read -r line; do [ -n "$line" ] && echo "    $line"; done
            found=1
        fi
    fi

    if [ $found -eq 0 ]; then
        echo "${GREEN}✓ 未检测到系统调用层 Hook / 用户态注入痕迹${RESET}"
        return 0
    fi
    return 1
}
