    fi

    unix_hits=$(proc_net_unix_keyword_hits "$strong_regex")
    if [ -n "$unix_hits" ]; then
        echo "${RED}⚠ 检测到本地 Unix Socket / 命名管道命中框架关键字:${RESET}"
        echo "$unix_hits" | while IFS= read -r line; do [ -n "$line" ] && echo "    $line"; done
