    task_hits=$(task_name_keyword_hits 'gum-js-loop|pool-frida|frida|lsposed|zygisk|shamiko|kernelsu|apatch|xposed|taichi|edxp|riru|hidemyapplist|hide[_-]?my[_-]?applist')
    if [ -n "$task_hits" ]; then
