    if [ -n "$fd_hits" ]; then
        echo "${RED}⚠ 检测到 fd 链接命中 Hook 框架关键字:${RESET}"
        echo "$fd_hits" | while IFS= read -r line; do [ -n "$line" ] && echo "    $line"; done
        found=1
        real_risk=1
    fi

    if command -v ps >/dev/null 2>&1; then
        procs=$(ps -A 2>/dev/null | grep -Ei "$strong_regex" | grep -v grep | head -12)
        if [ -n "$procs" ]; then
            echo "${RED}⚠ 检测到 Hook 框架相关进程:${RESET}"
            echo "$procs" | while IFS= read -r line; do echo "    $line"; done
            found=1
            real_risk=1
        fi
    fi

    if [ -r /proc/self/maps ]; then
        maps_hit=$(grep -Ei "$strong_regex" /proc/self/maps 2>/dev/null | head -12)
        if [ -n "$maps_hit" ]; then
            echo "${RED}⚠ 检测到可疑 Hook 库映射:${RESET}"
            echo "$maps_hit" | while IFS= read -r line; do echo "    $line"; done
            found=1
            real_risk=1
        fi

        extra_maps=$(awk '$NF != "" {print}' /proc/self/maps 2>/dev/null | while IFS= read -r line; do map_line_is_high_risk_injection "$line" && echo "$line"; done | head -8)
        if [ -n "$extra_maps" ]; then
            echo "${RED}⚠ 检测到来自高风险目录/关键字的映射对象:${RESET}"
            echo "$extra_maps" | while IFS= read -r line; do echo "    $line"; done
            found=1
            real_risk=1
        fi

        wx_hits=$(maps_wx_hits)
        if [ -n "$wx_hits" ]; then
            echo "${RED}⚠ 检测到可写且可执行内存区域:${RESET}"
            echo "$wx_hits" | head -5 | while IFS= read -r line; do echo "    $line"; done
            found=1
            real_risk=1
        fi
    fi

    for base in /data/adb/modules /data/adb/ksu/modules /data/adb/ap/modules /data/adb/modules_update; do
        [ -d "$base" ] || continue
        dir_hits=$(find "$base" -maxdepth 2 \( -type d -o -type f \) 2>/dev/null | grep -Ei "$strong_regex" | head -12)
        if [ -n "$dir_hits" ]; then
            echo "${RED}⚠ 模块目录存在高风险框架:${RESET}"
            echo "$dir_hits" | while IFS= read -r line; do echo "    $line"; done
            found=1
            real_risk=1
        fi
    done

    if pm_list_all >/dev/null 2>&1; then
        pkg_hits=$(printf '%s
' "$PM_LIST_CACHE" | grep -Ei 'org\.lsposed|edxp|taichi|riru|zygisk|shamiko|kernelsu|apatch|hidemyapplist|xposed|frida' | head -12)
        if [ -n "$pkg_hits" ]; then
            echo "${RED}⚠ 已安装包命中 Hook/隐藏框架关键字:${RESET}"
            echo "$pkg_hits" | while IFS= read -r line; do echo "    $line"; done
            found=1
            real_risk=1
        fi
    fi

    [ -n "$LD_PRELOAD" ] && env_hits=1
    [ -n "$LD_AUDIT" ] && env_hits=1
    [ -n "$LD_LIBRARY_PATH" ] && library_path_has_high_risk_entry "$LD_LIBRARY_PATH" && env_hits=1
    if [ -n "$env_hits" ]; then
        echo "${RED}⚠ 检测到动态链接器注入环境/库路径${RESET}"
        [ -n "$LD_PRELOAD" ] && echo "    LD_PRELOAD=$LD_PRELOAD"
        [ -n "$LD_AUDIT" ] && echo "    LD_AUDIT=$LD_AUDIT"
        [ -n "$LD_LIBRARY_PATH" ] && echo "    LD_LIBRARY_PATH=$LD_LIBRARY_PATH"
        found=1
        real_risk=1
    fi

    if [ -f /etc/ld.so.preload ] 2>/dev/null; then
        preload_file=$(sed -n '1,10p' /etc/ld.so.preload 2>/dev/null)
        echo "${RED}⚠ 检测到全局 preload 文件: /etc/ld.so.preload${RESET}"
        [ -n "$preload_file" ] && echo "$preload_file" | while IFS= read -r line; do echo "    $line"; done
        found=1
        real_risk=1
    fi

    command -v resetprop >/dev/null 2>&1 && {
        echo "${RED}⚠ 检测到 resetprop 工具: $(command -v resetprop)${RESET}"
        found=1
        real_risk=1
    }

    if [ -r /proc/modules ]; then
        mod_hits=$(grep -Ei 'kernelsu|(^|_)ksu($|_)|ksud|susfs|apatch|magisk|kpatch|livepatch|zygisk|shamiko' /proc/modules 2>/dev/null | head -8)
        if [ -n "$mod_hits" ]; then
            echo "${RED}⚠ 检测到高风险内核模块特征:${RESET}"
            echo "$mod_hits" | while IFS= read -r line; do echo "    $line"; done
            found=1
            real_risk=1
        fi
    fi

    [ $real_risk -eq 1 ] && return 1
    [ $found -eq 0 ] && echo "${GREEN}✓ 未检测到 Hook 框架核心特征${RESET}"
    return 0
}

detect_kernel_hook_artifacts() {
    local found=0
    local hinted=0
    local tr_root cur filt pidf kp dyn up event_hits inst_hits graph_hits enabled_funcs live_dir live_hits live_enabled=0 module_hits bpffs_hits bpftool_prog_hits bpftool_link_hits

    tr_root=$(tracefs_root 2>/dev/null)
    if [ -n "$tr_root" ]; then
        cur=$(cat "$tr_root/current_tracer" 2>/dev/null)
        if [ -n "$cur" ] && [ "$cur" != "nop" ]; then
            echo "${YELLOW}⚠ 提示: tracefs 当前 tracer 非 nop: $cur${RESET}"
            hinted=1
        fi
        filt=$(sed -n '/./p' "$tr_root/set_ftrace_filter" 2>/dev/null | head -8)
        if [ -n "$filt" ]; then
            echo "${RED}⚠ ftrace filter 已配置:${RESET}"
            echo "$filt" | while IFS= read -r line; do [ -n "$line" ] && echo "    $line"; done
            found=1
        fi
        pidf=$(sed -n '/./p' "$tr_root/set_ftrace_pid" 2>/dev/null | head -8)
        if [ -n "$pidf" ]; then
            echo "${RED}⚠ ftrace PID filter 已配置:${RESET}"
            echo "$pidf" | while IFS= read -r line; do [ -n "$line" ] && echo "    $line"; done
            found=1
        fi
        graph_hits=$(sed -n '/./p' "$tr_root/set_graph_function" 2>/dev/null | head -8)
        if [ -n "$graph_hits" ]; then
            echo "${RED}⚠ function_graph 目标函数已配置:${RESET}"
            echo "$graph_hits" | while IFS= read -r line; do [ -n "$line" ] && echo "    $line"; done
            found=1
        fi
        enabled_funcs=$(sed -n '/./p' "$tr_root/enabled_functions" 2>/dev/null | head -12)
        if [ -n "$enabled_funcs" ]; then
            echo "${RED}⚠ tracefs enabled_functions 非空:${RESET}"
            echo "$enabled_funcs" | while IFS= read -r line; do [ -n "$line" ] && echo "    $line"; done
            found=1
        fi
        kp=$(sed -n '/./p' "$tr_root/kprobe_events" 2>/dev/null | head -8)
        if [ -n "$kp" ]; then
            echo "${RED}⚠ kprobe_events 已注册动态探针:${RESET}"
            echo "$kp" | while IFS= read -r line; do [ -n "$line" ] && echo "    $line"; done
            found=1
        fi
        up=$(sed -n '/./p' "$tr_root/uprobe_events" 2>/dev/null | head -8)
        if [ -n "$up" ]; then
            echo "${RED}⚠ uprobe_events 已注册动态探针:${RESET}"
            echo "$up" | while IFS= read -r line; do [ -n "$line" ] && echo "    $line"; done
            found=1
        fi
        dyn=$(grep -E '(^| )(p|r|f|t|u):' "$tr_root/dynamic_events" 2>/dev/null | head -8)
        if [ -n "$dyn" ]; then
            echo "${RED}⚠ dynamic_events 中存在运行时探针:${RESET}"
            echo "$dyn" | while IFS= read -r line; do [ -n "$line" ] && echo "    $line"; done
            found=1
        fi
        event_hits=$(find "$tr_root/events" -maxdepth 3 -type f \( -name enable -o -name filter \) 2>/dev/null | while IFS= read -r f; do
            val=$(sed -n '1p' "$f" 2>/dev/null)
            [ -n "$val" ] && [ "$val" != "0" ] && [ "$val" != "none" ] && echo "$f = $val"
        done | head -10)
        if [ -n "$event_hits" ]; then
            echo "${RED}⚠ trace 事件存在启用/过滤配置:${RESET}"
            echo "$event_hits" | while IFS= read -r line; do [ -n "$line" ] && echo "    $line"; done
            found=1
        fi
        inst_hits=$(find "$tr_root/instances" -mindepth 1 -maxdepth 2 \( -type d -o -type f \) 2>/dev/null | head -12)
        if [ -n "$inst_hits" ]; then
            echo "${YELLOW}⚠ 提示: tracefs instances 非空:${RESET}"
            echo "$inst_hits" | while IFS= read -r line; do [ -n "$line" ] && echo "    $line"; done
            hinted=1
        fi
    fi
    live_dir="/sys/kernel/livepatch"
    if [ -d "$live_dir" ] 2>/dev/null; then
        live_hits=$(find "$live_dir" -mindepth 1 -maxdepth 1 -type d 2>/dev/null | while IFS= read -r d; do
            name=$(basename "$d")
            enabled=$(cat "$d/enabled" 2>/dev/null)
            transition=$(cat "$d/transition" 2>/dev/null)
            [ -n "$enabled" ] || enabled="?"
            [ -n "$transition" ] || transition="?"
            [ "$enabled" = "1" ] && echo "! $name enabled=$enabled transition=$transition" || echo "$name enabled=$enabled transition=$transition"
        done | head -8)
        if [ -n "$live_hits" ]; then
            echo "$live_hits" | grep -q '^! ' && live_enabled=1
            if [ $live_enabled -eq 1 ]; then
                echo "${RED}⚠ 检测到已启用的 livepatch:${RESET}"
                echo "$live_hits" | sed 's/^! //' | while IFS= read -r line; do [ -n "$line" ] && echo "    $line"; done
                found=1
            else
                echo "${YELLOW}⚠ 提示: 存在 livepatch 目录，但当前未见 enabled=1:${RESET}"
                echo "$live_hits" | while IFS= read -r line; do [ -n "$line" ] && echo "    $line"; done
                hinted=1
            fi
        fi
    fi
    if [ -r /proc/modules ]; then
        module_hits=$(grep -Ei 'kernelsu|(^|_)ksu($|_)|ksud|susfs|apatch|kpatch|livepatch|magisk|zygisk|shamiko' /proc/modules 2>/dev/null | head -10)
        if [ -n "$module_hits" ]; then
            echo "${RED}⚠ 内核模块命中高风险关键词:${RESET}"
            echo "$module_hits" | while IFS= read -r line; do [ -n "$line" ] && echo "    $line"; done
            found=1
        fi
    fi
    if [ -d /sys/fs/bpf ] 2>/dev/null; then
        bpffs_hits=$(find /sys/fs/bpf -maxdepth 3 \( -type f -o -type l -o -type d \) 2>/dev/null | grep -Ei 'kprobe|uprobe|tracepoint|raw_tracepoint|tracing|fentry|fexit|lsm|perf_event|sys_enter|sys_exit|frida|magisk|kernelsu|(^|/)ksu(/|$)|apatch' | head -10)
        if [ -n "$bpffs_hits" ]; then
            echo "${RED}⚠ bpffs 中存在高风险条目:${RESET}"
            echo "$bpffs_hits" | while IFS= read -r line; do [ -n "$line" ] && echo "    $line"; done
            found=1
        elif [ -n "$(ls -A /sys/fs/bpf 2>/dev/null)" ]; then
            hinted=1
            echo "${YELLOW}⚠ 提示: bpffs 非空，但路径名未直接命中高风险关键字${RESET}"
        fi
    fi
    if command -v bpftool >/dev/null 2>&1; then
        bpftool_prog_hits=$(bpftool prog show 2>/dev/null | grep -Ei 'tracing|kprobe|uprobe|tracepoint|raw_tracepoint|fentry|fexit|lsm|perf_event|syscall|frida|magisk|kernelsu|apatch' | head -12)
        if [ -n "$bpftool_prog_hits" ]; then
            echo "${RED}⚠ bpftool 枚举到高风险 BPF 程序类型/名称:${RESET}"
            echo "$bpftool_prog_hits" | while IFS= read -r line; do [ -n "$line" ] && echo "    $line"; done
            found=1
        fi
        bpftool_link_hits=$(bpftool link show 2>/dev/null | grep -Ei 'tracing|kprobe|uprobe|tracepoint|fentry|fexit|lsm|perf_event|syscall' | head -12)
        if [ -n "$bpftool_link_hits" ]; then
            echo "${RED}⚠ bpftool 枚举到活动 BPF link:${RESET}"
            echo "$bpftool_link_hits" | while IFS= read -r line; do [ -n "$line" ] && echo "    $line"; done
            found=1
        fi
    fi
    if [ $found -eq 0 ]; then
        [ $hinted -eq 1 ] && echo "${YELLOW}⚠ 提示: 检测到弱内核插桩信号，请结合 Hook / /proc/sys / 动态挂载结果联合判断${RESET}"
        echo "${GREEN}✓ 未检测到内核运行时钩子/插桩核心特征${RESET}"
        return 0
    fi
    return 1
}
detect_system_properties() {
    local found=0
    local hinted=0

    local kv_props="
ro.debuggable
ro.secure
ro.build.tags
ro.build.type
ro.build.selinux
ro.boot.selinux
persist.sys.usb.config
persist.service.adb.enable
service.adb.root
persist.sys.root_access
ro.dalvik.vm.native.bridge
"
    local p v
    for p in $kv_props; do
        v=$(getprop "$p" 2>/dev/null)
        [ -n "$v" ] || continue
        case "$p" in
            ro.debuggable)
                [ "$v" = "1" ] && { echo "${RED}⚠ 系统属性异常: $p=$v (可调试)${RESET}"; found=1; }
                ;;
            ro.secure)
                [ "$v" = "0" ] && { echo "${RED}⚠ 系统属性异常: $p=$v (不安全)${RESET}"; found=1; }
                ;;
            ro.build.tags)
                echo "$v" | grep -qi "test-keys" && { echo "${RED}⚠ 系统属性异常: $p=$v (test-keys)${RESET}"; found=1; }
                ;;
            ro.build.type)
                echo "$v" | grep -qiE "userdebug|eng" && { echo "${YELLOW}⚠ 提示: $p=$v (开发构建类型)${RESET}"; hinted=1; }
                ;;
            ro.build.selinux|ro.boot.selinux)
                echo "$v" | grep -qiE "permissive|0" && { echo "${RED}⚠ 系统属性异常: $p=$v (SELinux非enforcing)${RESET}"; found=1; }
                ;;
            persist.sys.usb.config)
                echo " $v " | grep -qE "(^|[ ,])adb([ ,]|$)" && { echo "${YELLOW}⚠ 提示: $p=$v (含adb，可能为开发模式)${RESET}"; hinted=1; }
                ;;
            persist.service.adb.enable)
                [ "$v" = "1" ] && { echo "${RED}⚠ 系统属性异常: $p=$v (ADB持久开启)${RESET}"; found=1; }
                ;;
            service.adb.root)
                [ "$v" = "1" ] && { echo "${RED}⚠ 系统属性异常: $p=$v (adbd root)${RESET}"; found=1; }
                ;;
            persist.sys.root_access)
                [ "$v" != "0" ] && { echo "${RED}⚠ 系统属性异常: $p=$v (root_access)${RESET}"; found=1; }
                ;;
            ro.dalvik.vm.native.bridge)
                [ -n "$v" ] && [ "$v" != "0" ] && [ "$v" != "libhoudini.so" ] && {
                    echo "$v" | grep -qiE 'magisk|zygisk|kernelsu|apatch|frida|riru|xposed' && {
                        echo "${RED}⚠ 系统属性异常: $p=$v (NativeBridge命中高风险关键词)${RESET}"
                        found=1
                    } || {
                        echo "${YELLOW}⚠ 提示: $p=$v (存在 NativeBridge / 兼容层)${RESET}"
                        hinted=1
                    }
                }
                ;;
        esac
    done

    if command -v getprop >/dev/null 2>&1; then
        local hit
        hit=$(getprop 2>/dev/null | grep -Ei "magisk|\.magisk|zygisk|kernelsu|ksu|ksud|apatch|lspd|lsposed|riru|edxp|taichi|xposed|substrate|frida|dobby|sandhook|shadowhook|bytehook|xhook|resetprop|hide_my_applist|shamiko" | head -20)
        if [ -n "$hit" ]; then
            echo "${RED}⚠ 系统属性命中可疑关键词(仅展示前20条):${RESET}"
            echo "$hit" | while IFS= read -r line; do echo "    $line"; done
            found=1
        fi
    fi

    [ $found -eq 0 ] && return 0
    return 1
}

detect_interface_tampering() {
    local found=0
    local hinted=0
    local cmds="getprop pm settings mount ps su uname grep awk sed cat sh readlink stat ls id date toybox busybox"

    local c
    for c in $cmds; do
        local t
        t=$(type -a "$c" 2>/dev/null | head -5)
        if [ -n "$t" ] && echo "$t" | grep -qiE "is a function|is aliased"; then
            echo "${RED}⚠ 命令可能被篡改: $c 被定义为函数/别名${RESET}"
            echo "$t" | while IFS= read -r line; do echo "    $line"; done
            found=1
            continue
        fi

        local which_path
        which_path=$(command -v "$c" 2>/dev/null)
        [ -n "$which_path" ] || continue

        if path_runtime_shell_allowed "$which_path"; then
            echo "${YELLOW}⚠ 提示: $c 来自应用内用户态工具链: $which_path${RESET}"
            hinted=1
            continue
        fi

        echo "$which_path" | grep -qE '^(/system/bin/|/system/xbin/|/vendor/bin/|/product/bin/|/apex/.*/bin/|/bin/|/usr/bin/)' || {
            echo "${RED}⚠ 命令路径异常: $c -> $which_path${RESET}"
            found=1
        }

        path_high_risk_injection_location "$which_path" && {
            echo "${RED}⚠ 命令来自高风险注入目录: $c -> $which_path${RESET}"
            found=1
        }
    done

    [ -n "$LD_PRELOAD" ] && {
        echo "${RED}⚠ 接口调用链疑似被篡改: LD_PRELOAD=$LD_PRELOAD${RESET}"
        found=1
    }
    [ -n "$LD_AUDIT" ] && {
        echo "${RED}⚠ 接口调用链疑似被篡改: LD_AUDIT=$LD_AUDIT${RESET}"
        found=1
    }
    if [ -n "$LD_LIBRARY_PATH" ]; then
        if library_path_has_high_risk_entry "$LD_LIBRARY_PATH"; then
            echo "${RED}⚠ 接口调用链疑似被篡改: LD_LIBRARY_PATH 含高风险路径 -> $LD_LIBRARY_PATH${RESET}"
            found=1
        else
            echo "${YELLOW}⚠ 提示: LD_LIBRARY_PATH 已设置，但未命中高风险目录${RESET}"
            hinted=1
        fi
    fi

    if [ -f /etc/ld.so.preload ] 2>/dev/null; then
        echo "${RED}⚠ 全局 preload 文件存在: /etc/ld.so.preload${RESET}"
        found=1
    fi

    local pth="/system/bin/getprop"
    if [ -e "$pth" ] 2>/dev/null; then
        if [ -L "$pth" ] 2>/dev/null; then
            local tgt
            tgt=$(readlink -f "$pth" 2>/dev/null)
            if [ -n "$tgt" ]; then
                echo "$tgt" | grep -qE '^(/system/bin/|/apex/.*/bin/)(toolbox|toybox|getprop)$' || {
                    echo "${RED}⚠ getprop 链接目标异常: $tgt${RESET}"
                    found=1
                }
            else
                echo "${RED}⚠ getprop 链接目标不可解析${RESET}"
                found=1
            fi
        fi
    fi

    [ $found -eq 0 ] && return 0
    return 1
}
detect_system_boot() {
    local found=0
    local bc sc dc br upi
    bc=$(getprop sys.boot_completed 2>/dev/null)
    dc=$(getprop dev.bootcomplete 2>/dev/null)
    sc=$(getprop sys.user.0.ce_available 2>/dev/null)
    br=$(getprop ro.boot.bootreason 2>/dev/null)
    upi=""

    if [ -r /proc/uptime ]; then
        local up
        up=$(cut -d" " -f1 /proc/uptime 2>/dev/null)
        if [ -n "$up" ]; then
            upi=${up%.*}
            if [ -n "$upi" ] && [ "$upi" -lt 60 ] 2>/dev/null; then
                echo "${YELLOW}⚠ 提示: 系统刚启动(uptime=${up}s)${RESET}"
            fi
        fi
    fi

    if [ -n "$bc" ] && [ "$bc" != "1" ]; then
        if [ -n "$upi" ] && [ "$upi" -gt 180 ] 2>/dev/null; then
            echo "${RED}⚠ 系统启动状态异常: sys.boot_completed=$bc${RESET}"
            found=1
        else
            echo "${YELLOW}⚠ 提示: sys.boot_completed=$bc (可能仍在启动阶段)${RESET}"
        fi
    fi
    if [ -n "$dc" ] && [ "$dc" != "1" ]; then
        if [ -n "$upi" ] && [ "$upi" -gt 180 ] 2>/dev/null; then
            echo "${RED}⚠ 系统启动状态异常: dev.bootcomplete=$dc${RESET}"
            found=1
        else
            echo "${YELLOW}⚠ 提示: dev.bootcomplete=$dc (可能仍在启动阶段)${RESET}"
        fi
    fi
    if [ -n "$sc" ] && [ "$sc" != "1" ]; then
        echo "${YELLOW}⚠ 提示: CE可能未就绪: sys.user.0.ce_available=$sc${RESET}"
    fi
    if [ -n "$br" ]; then
        echo "${YELLOW}⚠ 启动原因: ro.boot.bootreason=$br${RESET}"
    fi

    local s
    s=$(getprop | grep -E '^init\.svc\.' 2>/dev/null | grep -Ei 'magisk|zygisk|kernelsu|ksu|apatch|lspd|lsposed|riru|edxp|taichi|xposed|frida|hidemyapplist|hide[_-]?my[_-]?applist' | head -10)
    if [ -n "$s" ]; then
        echo "${RED}⚠ 检测到可疑启动服务:${RESET}"
        echo "$s" | while IFS= read -r line; do echo "    $line"; done
        found=1
    fi

    [ $found -eq 0 ] && { echo "${GREEN}✓ 系统启动状态正常${RESET}"; return 0; }
    return 1
}

detect_proc_sys() {
    local found=0
    local hinted=0
    local strict_user=0
    local k v perf_v="" ubpf_v="" ftrace_v="" userns_v=""

    is_user_build_like && strict_user=1

    note_bad() {
        local msg="$1"
        echo "${RED}⚠ /proc/sys 异常: $msg${RESET}"
        found=1
    }
    note_hint() {
        local msg="$1"
        echo "${YELLOW}⚠ 提示: $msg${RESET}"
        hinted=1
    }
    check_eq_policy() {
        local path="$1" want="$2" key="$3" relax="$4"
        [ -r "$path" ] || return 0
        v=$(cat "$path" 2>/dev/null)
        [ -n "$v" ] || return 0
        if [ "$v" != "$want" ]; then
            if [ "$relax" = "hint" ] || [ $strict_user -eq 0 ]; then
                note_hint "$key=$v (参考期望 $want)"
            else
                note_bad "$key=$v (期望 $want)"
            fi
        fi
    }
    check_num_ge_policy() {
        local path="$1" want="$2" key="$3" relax="$4"
        [ -r "$path" ] || return 0
        v=$(cat "$path" 2>/dev/null)
        echo "$v" | grep -Eq '^-?[0-9]+$' || { [ -n "$v" ] && note_bad "$key=$v"; return 0; }
        if [ "$v" -lt "$want" ] 2>/dev/null; then
            if [ "$relax" = "hint" ] || [ $strict_user -eq 0 ]; then
                note_hint "$key=$v (参考应 >= $want)"
            else
                note_bad "$key=$v (应 >= $want)"
            fi
        fi
    }
    check_eq_policy "/proc/sys/kernel/yama/ptrace_scope" "1" "kernel.yama.ptrace_scope" "hint"
    check_num_ge_policy "/proc/sys/kernel/kptr_restrict" "1" "kernel.kptr_restrict" "hint"
    check_num_ge_policy "/proc/sys/kernel/dmesg_restrict" "1" "kernel.dmesg_restrict" "hint"
    check_eq_policy "/proc/sys/kernel/randomize_va_space" "2" "kernel.randomize_va_space" ""
    check_eq_policy "/proc/sys/fs/protected_hardlinks" "1" "fs.protected_hardlinks" ""
    check_eq_policy "/proc/sys/fs/protected_symlinks" "1" "fs.protected_symlinks" ""
    for k in /proc/sys/fs/protected_fifos /proc/sys/fs/protected_regular; do
        [ -r "$k" ] || continue
        v=$(cat "$k" 2>/dev/null)
        case "$v" in 1|2) ;; *) note_bad "${k#/proc/sys/}=$v" ;; esac
    done
    k="/proc/sys/kernel/perf_event_paranoid"
    if [ -r "$k" ]; then
        perf_v=$(cat "$k" 2>/dev/null)
        if echo "$perf_v" | grep -Eq '^-?[0-9]+$'; then
            case "$perf_v" in
                -1) note_hint "kernel.perf_event_paranoid=$perf_v" ;;
                0) note_hint "kernel.perf_event_paranoid=$perf_v" ;;
                1|2|3|4) ;;
                *) [ "$perf_v" -lt -1 ] 2>/dev/null && note_bad "kernel.perf_event_paranoid=$perf_v" ;;
            esac
        else
            [ -n "$perf_v" ] && note_bad "kernel.perf_event_paranoid=$perf_v"
        fi
    fi
    k="/proc/sys/kernel/unprivileged_bpf_disabled"
    if [ -r "$k" ]; then
        ubpf_v=$(cat "$k" 2>/dev/null)
        case "$ubpf_v" in
            1|2) ;;
            0) note_hint "kernel.unprivileged_bpf_disabled=$ubpf_v" ;;
            *) [ -n "$ubpf_v" ] && note_hint "kernel.unprivileged_bpf_disabled=$ubpf_v" ;;
        esac
    fi
    k="/proc/sys/kernel/modules_disabled"
    if [ -r "$k" ]; then
        v=$(cat "$k" 2>/dev/null)
        [ "$v" = "0" ] && note_hint "kernel.modules_disabled=0"
    fi
    for k in /proc/sys/vm/mmap_rnd_bits /proc/sys/vm/mmap_rnd_compat_bits; do
        [ -r "$k" ] || continue
        v=$(cat "$k" 2>/dev/null)
        if echo "$v" | grep -Eq '^[0-9]+$'; then
            [ "$v" -lt 16 ] 2>/dev/null && note_hint "${k#/proc/sys/}=$v 偏低"
        fi
    done
    k="/proc/sys/kernel/ftrace_enabled"
    if [ -r "$k" ]; then
        ftrace_v=$(cat "$k" 2>/dev/null)
        [ "$ftrace_v" = "1" ] && note_hint "kernel.ftrace_enabled=1"
    fi
    k="/proc/sys/user/max_user_namespaces"
    if [ -r "$k" ]; then
        userns_v=$(cat "$k" 2>/dev/null)
        if echo "$userns_v" | grep -Eq '^[0-9]+$'; then
            [ "$userns_v" -gt 0 ] 2>/dev/null && note_hint "user.max_user_namespaces=$userns_v"
        fi
    fi
    for k in /proc/sys/kernel/unprivileged_userns_clone /proc/sys/kernel/kexec_load_disabled /proc/sys/net/ipv4/ip_forward; do
        [ -r "$k" ] || continue
        v=$(cat "$k" 2>/dev/null)
        case "$k" in
            */unprivileged_userns_clone) [ "$v" = "1" ] && note_hint "${k#/proc/sys/}=$v" ;;
            */kexec_load_disabled) [ "$v" = "0" ] && note_hint "${k#/proc/sys/}=$v" ;;
            */ip_forward) [ "$v" = "1" ] && note_hint "${k#/proc/sys/}=$v" ;;
        esac
    done
    if [ "$perf_v" = "-1" ] && [ "$ubpf_v" = "0" ]; then
        note_bad "kernel.perf_event_paranoid=-1 且 kernel.unprivileged_bpf_disabled=0"
    fi
    if [ "$perf_v" = "-1" ] && [ "$ftrace_v" = "1" ]; then
        note_hint "perf 低限制 + ftrace 开启"
    fi
    if [ $found -eq 0 ]; then
        [ $hinted -eq 1 ] && echo "${YELLOW}⚠ 提示: /proc/sys 存在弱信号${RESET}"
        echo "${GREEN}✓ /proc/sys 关键项正常${RESET}"
        return 0
    fi
    return 1
}
