refresh_result_page() {
    if command -v clear >/dev/null 2>&1; then
        clear
    else
        printf '[2J[H'
    fi
}

total=${#DETECTION_TASKS[@]}
current=0
suspect_count=0
error_count=0
RESULTS=""
ERRORS=""

for task in "${DETECTION_TASKS[@]}"; do
    IFS=":" read -r func_name title <<< "$task"
    current=$((current + 1))
    percent=$((current * 100 / total))
    printf "
[K[%3d%%] 正在检测: %s..." "$percent" "$title"

    if command -v "$func_name" >/dev/null 2>&1; then
        output=$("$func_name" 2>&1)
        ret=$?
    else
        output="${RED}⚠ 检测函数不存在: $func_name${RESET}"
        ret=2
    fi

    if [ $ret -eq 1 ]; then
        if has_visible_output "$output"; then
            suspect_count=$((suspect_count + 1))
            RESULTS="${RESULTS}
${BOLD}${title}${RESET}
${output}
${LINE}
"
        else
            error_count=$((error_count + 1))
