#压缩算法测试

#!/system/bin/sh

TEST_DIR="/data/local/tmp/zram_final_test"
TEST_FILE="$TEST_DIR/test_data.bin"
STAT_TMP="/tmp/zram_stat_tmp.txt"
RESULT_TMP="/tmp/zram_result_tmp.txt"
SIZE_MB=512
TEST_TIMES=3
ZRAM_DEV="/dev/block/zram0"

ORIG_ALGO=""
ORIG_DISKSIZE=""
ORIG_SWAP_ON=""
RESULT_SUMMARY=""
USE_MMSTAT_COMPAT=0

get_precise_time() {
    read uptime _ < /proc/uptime
    echo "$uptime"
}

get_compress_stats() {
    if [ "$USE_MMSTAT_COMPAT" -eq 0 ]; then
        orig_size=$(cat /sys/block/zram0/orig_data_size)
        compr_size=$(cat /sys/block/zram0/compr_data_size)
    else
        read orig_size compr_size _ < /sys/block/zram0/mm_stat
    fi
    echo "$orig_size $compr_size"
}

get_file_size_mb() {
    FILE_PATH="$1"
    SIZE_KB=$(du -k "$FILE_PATH" 2>/dev/null | awk '{print $1}')
    SIZE_MB=$(awk "BEGIN {printf \"%d\", $SIZE_KB / 1024}")
    echo "$SIZE_MB"
}

printf "=============================================\n"
printf "       全算法性能测试脚本\n"
printf "=============================================\n"
echo  如果一直长时间卡在某个地方执行不动的话就放进内部存储执行
printf "目标测试算法：lzo、lzo-rle、lz4、zstd、zstdn、zstdn_o\n"
printf "测试数据大小：%sMB（中等可压缩真实场景）\n" "$SIZE_MB"
printf "单算法测试次数：%s次\n" "$TEST_TIMES"
printf "=============================================\n\n"

printf "[1/5] 前置环境全检查...\n"

if [ "$(id -u)" -ne 0 ]; then
    printf "[!] 错误：必须使用Root权限运行\n"
    exit 1
fi
printf "    ✅ Root权限检查通过\n"

if [ ! -b "$ZRAM_DEV" ]; then
    printf "[!] 错误：ZRAM设备 %s 不存在\n" "$ZRAM_DEV"
    exit 1
fi
printf "    ✅ ZRAM设备检查通过\n"

if [ -f /sys/block/zram0/orig_data_size ] && [ -f /sys/block/zram0/compr_data_size ]; then
    printf "    ✅ 检测到专用压缩率统计节点\n"
    USE_MMSTAT_COMPAT=0
else
    printf "    ⚠️  启用mm_stat兼容模式\n"
    if [ ! -f /sys/block/zram0/mm_stat ]; then
        printf "[!] 错误：内核缺少ZRAM统计节点\n"
        exit 1
    fi
    USE_MMSTAT_COMPAT=1
fi

mkdir -p "$TEST_DIR"
if [ ! -d "$TEST_DIR" ]; then
    printf "[!] 错误：测试目录创建失败\n"
    exit 1
fi
touch "$TEST_DIR/test.tmp" && rm -f "$TEST_DIR/test.tmp"
if [ $? -ne 0 ]; then
    printf "[!] 错误：测试目录无读写权限\n"
    exit 1
fi
printf "    ✅ 测试目录权限检查通过\n"

REQUIRED_SPACE_MB=$((SIZE_MB * 2))
printf "    检查分区剩余空间（需要至少%sMB）...\n" "$REQUIRED_SPACE_MB"
AVAIL_SPACE_KB=$(df -k "$TEST_DIR" 2>/dev/null | tail -n 1 | awk '{print $4}')
if [ -z "$AVAIL_SPACE_KB" ] || [ "$AVAIL_SPACE_KB" -eq 0 ]; then
    AVAIL_SPACE_KB=$(df -k "$TEST_DIR" 2>/dev/null | tail -n 1 | awk '{print $3}')
fi

if [ -n "$AVAIL_SPACE_KB" ] && [ "$AVAIL_SPACE_KB" -gt 0 ]; then
    AVAIL_SPACE_MB=$(awk "BEGIN {printf \"%d\", $AVAIL_SPACE_KB / 1024}")
    if [ "$AVAIL_SPACE_MB" -lt "$REQUIRED_SPACE_MB" ]; then
        printf "[!] 错误：/data分区剩余空间不足，需要至少%sMB，当前剩余%sMB\n" "$REQUIRED_SPACE_MB" "$AVAIL_SPACE_MB"
        exit 1
    else
        printf "    ✅ 分区空间检查通过，剩余%sMB\n" "$AVAIL_SPACE_MB"
    fi
else
    printf "    ⚠️  无法获取分区空间，跳过检查\n"
    printf "    ⚠️  请确保/data分区有至少%sMB空闲空间\n" "$REQUIRED_SPACE_MB"
fi

SUPPORTED_ALGOS=$(cat /sys/block/zram0/comp_algorithm)
printf "    内核支持的算法：%s\n" "$SUPPORTED_ALGOS"
printf "    所有前置检查完成！\n\n"

printf "[2/5] 备份原有ZRAM配置...\n"
ORIG_ALGO=$(cat /sys/block/zram0/comp_algorithm | awk '{for(i=1;i<=NF;i++) if($i ~ /^\[.*\]$/) {gsub(/[\[\]]/,"",$i); print $i; exit}}')
ORIG_DISKSIZE=$(cat /sys/block/zram0/disksize)
ORIG_SWAP_ON=$(grep -q "$ZRAM_DEV" /proc/swaps && echo "1" || echo "0")

printf "    原有激活算法：%s\n" "$ORIG_ALGO"
printf "    原有ZRAM大小：%sMB\n" "$((ORIG_DISKSIZE / 1024 / 1024))"
printf "    原有Swap状态：%s\n" "$([ "$ORIG_SWAP_ON" = "1" ] && echo "已启用" || echo "已禁用")"
printf "    备份完成！\n\n"

printf "[3/5] 生成真实场景测试数据...\n"

if [ ! -f "$TEST_FILE" ]; then
    COMPRESSIBLE_MB=$((SIZE_MB * 8 / 10))
    RANDOM_MB=$((SIZE_MB - COMPRESSIBLE_MB))
    COMPRESSIBLE_FILE="$TEST_DIR/compressible_part.bin"
    RANDOM_FILE="$TEST_DIR/random_part.bin"
    BASE_FILE="$TEST_DIR/base_block.bin"
    
    printf "    目标：%sMB中等可压缩数据 + %sMB随机数据\n" "$COMPRESSIBLE_MB" "$RANDOM_MB"

    printf "\n    生成基础特征块...\n"
    echo "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789" > "$BASE_FILE"
    echo "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz9876543210" >> "$BASE_FILE"
    echo "0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ" >> "$BASE_FILE"
    echo "9876543210ZYXWVUTSRQPONMLKJIHGFEDCBAzyxwvutsrqponmlkjihgfedcba" >> "$BASE_FILE"
    echo "AndroidRuntimeActivityThreadhandleBindApplicationpackageInfoandroidappLoadedApk" >> "$BASE_FILE"
    echo "LayoutInflaterinflateresource0x7f0a0123rootandroidwidgetLinearLayoutattachToRoottrue" >> "$BASE_FILE"

    if [ ! -s "$BASE_FILE" ]; then
        printf "[!] 错误：基础块生成失败\n"
        exit 1
    fi
    printf "    ✅ 基础特征块生成完成\n"

    printf "\n    生成可压缩主文件...\n"
    yes "$(cat "$BASE_FILE")" | dd of="$COMPRESSIBLE_FILE" bs=1024k count="$COMPRESSIBLE_MB" 2>/dev/null
    rm -f "$BASE_FILE"

    ACTUAL_COMP_MB=$(get_file_size_mb "$COMPRESSIBLE_FILE")
    if [ $? -eq 0 ] && [ -f "$COMPRESSIBLE_FILE" ] && [ "$ACTUAL_COMP_MB" -eq "$COMPRESSIBLE_MB" ]; then
        printf "    ✅ 可压缩数据生成完成\n"
    else
        printf "[!] 错误：可压缩数据生成失败\n"
        exit 1
    fi

    printf "\n    生成随机不可压缩数据...\n"
    dd if=/dev/urandom of="$RANDOM_FILE" bs=1024k count="$RANDOM_MB" 2>/dev/null
    ACTUAL_RAND_MB=$(get_file_size_mb "$RANDOM_FILE")
    if [ $? -eq 0 ] && [ -f "$RANDOM_FILE" ] && [ "$ACTUAL_RAND_MB" -eq "$RANDOM_MB" ]; then
        printf "    ✅ 随机数据生成完成\n"
    else
        printf "[!] 错误：随机数据生成失败\n"
        exit 1
    fi

    printf "\n    合并最终测试文件...\n"
    cat "$COMPRESSIBLE_FILE" "$RANDOM_FILE" > "$TEST_FILE"
    rm -f "$COMPRESSIBLE_FILE" "$RANDOM_FILE"
    
    ACTUAL_SIZE=$(get_file_size_mb "$TEST_FILE")
    if [ "$ACTUAL_SIZE" -ne "$SIZE_MB" ]; then
        printf "[!] 错误：测试文件大小不符\n"
        exit 1
    fi
    printf "    ✅ 真实场景测试数据生成完成\n"
else
    printf "    ✅ 测试文件已存在，跳过生成\n"
fi
printf "    数据准备完成！\n\n"

run_benchmark() {
    ALGO="$1"
    printf "=============================================\n"
    printf ">>> 测试算法：【%s】\n" "$ALGO"
    printf "=============================================\n"
    
    if ! echo "$SUPPORTED_ALGOS" | grep -qw "$ALGO"; then
        printf "   [!] 跳过：内核不支持 %s\n" "$ALGO"
        printf "=============================================\n\n"
        return
    fi

    printf "   - 初始化ZRAM设备...\n"
    swapoff "$ZRAM_DEV" >/dev/null 2>&1
    sleep 0.2
    echo 1 > /sys/block/zram0/reset 2>/dev/null
    if [ $? -ne 0 ]; then
        printf "   [!] 错误：ZRAM重置失败\n"
        printf "=============================================\n\n"
        return
    fi
    sleep 0.3

    echo "$ALGO" > /sys/block/zram0/comp_algorithm
    if [ $? -ne 0 ]; then
        printf "   [!] 错误：设置算法失败\n"
        printf "=============================================\n\n"
        return
    fi
    echo "$((SIZE_MB + 64))M" > /sys/block/zram0/disksize
    sleep 0.2
    printf "   ✅ ZRAM初始化完成\n"

    printf "   - 执行预热读写...\n"
    dd if="$TEST_FILE" of="$ZRAM_DEV" bs=1024k count="$SIZE_MB" 2>/dev/null
    dd if="$ZRAM_DEV" of=/dev/null bs=1024k count="$SIZE_MB" 2>/dev/null
    echo 1 > /sys/block/zram0/reset 2>/dev/null
    sleep 0.2
    echo "$ALGO" > /sys/block/zram0/comp_algorithm
    echo "$((SIZE_MB + 64))M" > /sys/block/zram0/disksize
    sleep 0.2
    printf "   ✅ 预热完成\n"

    total_write_time=0
    total_read_time=0
    compress_ratio=0
    orig_size_mb=0
    compr_size_mb=0

    i=1
    while [ $i -le "$TEST_TIMES" ]; do
        printf "\n   --- 第 %s 次测试 ---\n" "$i"

        printf "   写入测试（压缩）...\n"
        sync; echo 3 > /proc/sys/vm/drop_caches
        sleep 0.3

        start_time=$(get_precise_time)
        dd if="$TEST_FILE" of="$ZRAM_DEV" bs=1024k count="$SIZE_MB" 2>/dev/null
        dd_exit_code=$?
        end_time=$(get_precise_time)

        if [ $dd_exit_code -ne 0 ]; then
            printf "   [!] 警告：写入失败，跳过\n"
            i=$((i + 1))
            continue
        fi

        write_time=$(awk "BEGIN {print $end_time - $start_time}")
        write_speed=$(awk "BEGIN {printf \"%.2f\", $SIZE_MB / $write_time}")
        printf "   -> 写入耗时：%ss | 速度：%s MB/s\n" "$write_time" "$write_speed"
        total_write_time=$(awk "BEGIN {print $total_write_time + $write_time}")

        if [ $i -eq 1 ]; then
            sync; sleep 0.5
            get_compress_stats > "$STAT_TMP"
            read orig_size compr_size < "$STAT_TMP"
            rm -f "$STAT_TMP"

            if [ "$compr_size" -ne 0 ] && [ "$orig_size" -gt 0 ]; then
                compress_ratio=$(awk "BEGIN {printf \"%.2f\", $orig_size / $compr_size}")
                orig_size_mb=$(awk "BEGIN {printf \"%.1f\", $orig_size / 1024 / 1024}")
                compr_size_mb=$(awk "BEGIN {printf \"%.1f\", $compr_size / 1024 / 1024}")
                save_mb=$(awk "BEGIN {printf \"%.1f\", $orig_size_mb - $compr_size_mb}")
                printf "   -> 原始大小：%sMB | 压缩后：%sMB\n" "$orig_size_mb" "$compr_size_mb"
                printf "   -> 压缩比例：%s : 1 | 节省：%sMB\n" "$compress_ratio" "$save_mb"
            else
                printf "   [!] 警告：压缩率统计失败\n"
            fi
        fi

        printf "   读取测试（解压）...\n"
        sync; echo 3 > /proc/sys/vm/drop_caches
        sleep 0.3

        start_time=$(get_precise_time)
        dd if="$ZRAM_DEV" of=/dev/null bs=1024k count="$SIZE_MB" 2>/dev/null
        end_time=$(get_precise_time)

        read_time=$(awk "BEGIN {print $end_time - $start_time}")
        read_speed=$(awk "BEGIN {printf \"%.2f\", $SIZE_MB / $read_time}")
        printf "   -> 读取耗时：%ss | 速度：%s MB/s\n" "$read_time" "$read_speed"
        total_read_time=$(awk "BEGIN {print $total_read_time + $read_time}")

        if [ $i -lt "$TEST_TIMES" ]; then
            echo 1 > /sys/block/zram0/reset 2>/dev/null
            sleep 0.2
            echo "$ALGO" > /sys/block/zram0/comp_algorithm
            echo "$((SIZE_MB + 64))M" > /sys/block/zram0/disksize
            sleep 0.2
        fi

        i=$((i + 1))
    done

    avg_write_time=$(awk "BEGIN {printf \"%.3f\", $total_write_time / $TEST_TIMES}")
    avg_write_speed=$(awk "BEGIN {printf \"%.2f\", $SIZE_MB / $avg_write_time}")
    avg_read_time=$(awk "BEGIN {printf \"%.3f\", $total_read_time / $TEST_TIMES}")
    avg_read_speed=$(awk "BEGIN {printf \"%.2f\", $SIZE_MB / $avg_read_time}")

    printf "\n=============================================\n"
    printf "【%s】测试结果汇总\n" "$ALGO"
    printf "=============================================\n"
    printf "平均压缩速度：%s MB/s（平均耗时 %ss）\n" "$avg_write_speed" "$avg_write_time"
    printf "平均解压速度：%s MB/s（平均耗时 %ss）\n" "$avg_read_speed" "$avg_read_time"
    printf "压缩比例：%s : 1\n" "$compress_ratio"
    printf "=============================================\n\n"

    RESULT_SUMMARY="$RESULT_SUMMARY$ALGO $avg_write_speed $avg_read_speed $compress_ratio\n"
}

printf "[4/5] 开始全算法测试...\n"
printf "=============================================\n\n"

for algo in lzo lzo-rle lz4 zstd zstdn zstdn_o; do
