#应用冻结
#!/bin/bash
# 全局颜色定义（统一全局，避免重复冲突）
RED='\033[0;31m'
GREEN='\033[0;32m'
YELLOW='\033[1;33m'
YELLOW1='\033[33m'
BLUE='\033[0;34m'
NC='\033[0m'

# 全局对局结果标记
round_result=""
# 全局整局游戏胜利标记
game_total_win=0

# ------------------------------
# 新版石头剪刀布单局（你提供的原版逻辑）
# ------------------------------
single_round(){
    echo ""
    sleep 0.5
    echo "================ 对局开始 ================"
    
    options=("石头" "剪刀" "布")
    computer_choice=${options[$RANDOM % ${#options[@]}]}
    sleep 1.5
    echo -e "$GREEN●$NC电脑已做出选择..."
    sleep 0.5
    
    echo ""
    echo "请选择你的出招："
    echo "1.石头"
    echo "2.剪刀"
    echo "3.布"
    echo -n "请输入数字 [1-3]: "
    read user_input
    case $user_input in
        1)
            user_choice="石头"
            ;;
        2)
            user_choice="剪刀"
            ;;
        3)
            user_choice="布"
            ;;
        *)
            echo -e "$YELLOW输入无效，请重新输入！$NC"
            sleep 1
            clear
            single_round
            return
            ;;
    esac
    
    echo "你选择了: $user_choice"
    sleep 0.5
    echo "电脑选择了: $computer_choice"
    sleep 0.5
    
    # 判断本局胜负
    if [ "$user_choice" = "$computer_choice" ]; then
        echo -e "$YELLOW本局：平局！$NC"
        round_result="draw"
    elif { [ "$user_choice" = "石头" ] && [ "$computer_choice" = "剪刀" ]; } || \
         { [ "$user_choice" = "剪刀" ] && [ "$computer_choice" = "布" ]; } || \
         { [ "$user_choice" = "布" ] && [ "$computer_choice" = "石头" ]; }; then
        echo -e "$GREEN本局：你赢了！$NC"
        round_result="win"
    else
        echo -e "$RED本局：你输了！$NC"
        round_result="lose"
    fi
    sleep 2
}

# ------------------------------
# 完整游戏对局（三局/五局模式，你原版）
# ------------------------------
game() {
user_score=0
computer_score=0
round=1
while [ $round -le $total_rounds ]; do
    echo ""
    sleep 0.5
    echo " 第$round局开始 "
    
    # 调用单局，结果存round_result
    single_round
    if [ "$round_result" = "win" ]; then
        user_score=$((user_score + 1))
    elif [ "$round_result" = "lose" ]; then
        computer_score=$((computer_score + 1))
    fi
    
    clear
    echo "~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~"
    echo "当前分数："
    echo "玩家：$user_score分"
    echo "电脑：$computer_score分"
    echo "~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~"
    
    # 提前结束对局判断
    if [ $total_rounds -eq 3 ]; then
        if [ $user_score -eq 2 ]; then
            echo -e "$GREEN玩家提前获胜！$NC"
            break
        elif [ $computer_score -eq 2 ]; then
            echo -e "$RED电脑提前获胜！$NC"
            break
        fi
    elif [ $total_rounds -eq 5 ]; then
        if [ $user_score -eq 3 ]; then
            echo -e "$GREEN玩家提前获胜！$NC"
            break
        elif [ $computer_score -eq 3 ]; then
            echo -e "$RED电脑提前获胜！$NC"
            break
        fi
    fi
    
    round=$((round + 1))
done
clear
echo "== 游戏结算 =="
echo "最终比分："
echo "玩家：$user_score分"
echo "电脑：$computer_score分"
echo ""
# 总分平局 开启X/Y选择
if [ $user_score -gt $computer_score ]; then
    echo -e "$GREEN恭喜你获得了最终胜利！$NC"
    game_total_win=1
elif [ $user_score -lt $computer_score ]; then
    echo -e "$RED很遗憾，电脑获得了最终胜利。$NC"
    game_total_win=0
else
    echo -e "$YELLOW双方总分平局！请选择后续操作：$NC"
    echo "X - 进行加时一局决胜负"
    echo "Y - 接受平局，结束本局游戏"
    game_total_win=0
    while true; do
        echo -n "请输入 X / Y ："
        read tie_opt
        tie_opt=$(echo "$tie_opt" | tr '[:lower:]' '[:upper:]')
        if [ "$tie_opt" = "X" ]; then
            echo -e "$BLUE开始加时决胜局！$NC"
            single_round
            clear
            echo "================= 加时结算 ================"
            if [ "$round_result" = "win" ]; then
                echo -e "$GREEN加时胜利，你拿下整场游戏！$NC"
                game_total_win=1
            elif [ "$round_result" = "lose" ]; then
                echo -e "$RED加时落败，电脑拿下整场游戏！$NC"
                game_total_win=0
            else
                echo -e "$YELLOW加时依旧平局，本次判定为全场平局$NC"
                game_total_win=0
            fi
            break
        elif [ "$tie_opt" = "Y" ]; then
            echo -e "$YELLOW已接受平局，本场游戏结束$NC"
            break
        else
            echo -e "$RED输入错误，请仅输入 X 或 Y！$NC"
        fi
    done
fi
echo "======"
}

# 游戏暂停函数（改名避免和冻结工具stop重名）
game_stop() {
echo ""
echo -n "任意键继续，输入q退出: "
read user_input
if [ "$user_input" = "q" ] || [ "$user_input" = "Q" ]; then
    echo "游戏结束，返回主菜单"
    return
fi
clear
}

# 游戏独立菜单循环
start_game() {
while true; do
# 清屏（兼容无clear环境）
command -v clear >/dev/null 2>&1 && clear || printf "\033c"
    echo 石头剪刀布游戏 
    echo -e "人才别玩应用冻结 过来玩石头剪刀布吧"
    echo "请选择游戏模式："
    echo "1. 三局两胜制"
    echo "2. 五局三胜制"
    echo "0. 返回上层启动菜单"
    echo -n "请输入选择 [0-2]: "
    read choice
    case "$choice" in
        1)
            clear
            total_rounds=3
            sleep 0.5
            echo "选择三局两胜制，开始游戏！"
            sleep 0.5
            game
            game_stop
            ;;
        2)
            clear
            total_rounds=5
            sleep 0.5
            echo "选择五局三胜制，开始游戏！"
            sleep 0.5
            game
            game_stop
            ;;
        0)
            clear
            return
            ;;
        *)
            echo -e "$YELLOW输入无效，请重新输入！$NC"
            sleep 1
            clear
            ;;
    esac
done
}

# ------------------------------
# 应用冻结工具 完整源码（你的原版）
# ------------------------------
freeze_tool(){
# 单个冻结
freeze_app() {
    clear
    
    printf "请输入要冻结的应用包名："
    read package_name
    if [ -z "$package_name" ]; then
        echo -e "${RED}包名不能为空！${NC}"
        return
    fi
    
    pkg="$package_name"
    if ! pm list packages | grep -qw "package:$pkg"; then
        echo -e "${RED}该应用未安装${NC}"
        return 1
    fi
    if pm list packages -d | grep -qw "package:$pkg"; then
        echo -e "${YELLOW}应用已经处于冻结状态${NC}"
        return 1
    fi
    echo "正在冻结$package_name"
    sleep 0.5
    result=$(pm disable-user "$package_name" 2>&1)
    
    if echo "$result" | grep -q "new state: disabled"; then
        echo -e "${GREEN}操作成功 应用已冻结。${NC}"
    else
        echo -e "${RED}失败：$result${NC}"
        echo -e "${YELLOW}提示：如果是系统核心应用可能无法冻结${NC}"
    fi
}
# 查看已冻结
list_frozen() {
    clear
    echo -e "${YELLOW}如果有应用实际上并没有被冻结 就是该应用存在于系统分身导致的 且只会是系统应用 ${NC}"
    echo ""
    echo "-------------------------"
    # 获取已禁用包列表
    frozen_list=$(pm list packages -d | sed 's/package://g')
    multi_freeze_pkgs=""
    # 遍历已冻结包
    printf '%s\n' "$frozen_list" | while IFS= read -r pkg; do
        case " $multi_freeze_pkgs " in
            *" $pkg "*)
                echo -e "$pkg"
                ;;
            *)
                echo -e "$pkg"
                ;;
        esac
    done
    echo "-------------------------"
}
# 单个解冻
unfreeze_single() {
    clear
    printf "请输入要解冻的应用包名："
    read -r package_name
    if [ -z "$package_name" ]; then
        echo -e "${RED}包名不能为空！${NC}"
        return
    fi
    # 判断是否被冻结
    if ! pm list packages -d | grep -q "^package:$package_name$"; then
        echo -e "${RED}提示：该应用不存在或未处于冻结状态。${NC}"
        return
    fi
    echo "正在解冻$package_name"
    # 执行解冻
    result=$(pm enable "$package_name" 2>&1)
    if echo "$result" | grep -q "new state: enabled"; then
        echo -e "${GREEN}成功 应用已解冻${NC}"
    else
        echo -e "${RED}失败：$result${NC}"
    fi
}
# 解冻所有
unfreeze_all() {
    clear
    printf "确定要解冻所有已禁用的应用吗？(y/n)"
    read -r confirm
    if [ "$confirm" != "y" ] && [ "$confirm" != "Y" ]; then
        echo "操作已取消。"
        return
    fi
    packages=$(pm list packages -d | sed 's/package://g')
    if [ -z "$packages" ]; then
        echo "没有需要解冻的应用。"
        return
    fi
    count=0
    for pkg in $packages; do
        # 执行解冻
        result=$(pm enable "$pkg" 2>&1)
        if echo "$result" | grep -q "new state: enabled"; then
            echo "已解冻$pkg"
            count=$((count + 1))
        else
            echo -e "${RED}失败: $pkg ($result)${NC}"
        fi
    done
    echo -e "${GREEN}处理完成 共解冻$count个应用 ${NC}"
}
# 冻结工具暂停
stop() {
    echo ""
    echo -n "任意键继续..."
    read user_input
    clear
}
# 冻结工具主循环
# 清屏（兼容无clear环境）
command -v clear >/dev/null 2>&1 && clear || printf "\033c"
while true; do
    clear
    echo -e "●${YELLOW}应用冻结/解冻需要包名  如果你连包名都不知道就别用了 容易出岔子${NC}"
    echo -e "●${YELLOW}包名获取：MT提取安装包界面 点击对应软件就会出现包名  长按就可复制包名${NC}"
    echo -e "${GREEN}============================================${NC}"
    echo ""
    echo "1. 应用冻结"
    echo "2. 查看已冻结应用"
    echo "3. 选择应用解冻"
    echo "4. 退出程序"
    printf "请输入选项："
    read choice
    case $choice in
        1)
            freeze_app
            stop
            ;;
        2)
            list_frozen
            stop
            ;;
        3)
            while true; do
                clear
                echo "1. 输入包名解冻"
                echo "2. 一键解冻所有软件"
                echo "3. 返回"
                printf "请输入选项："
                read sub_choice
                case $sub_choice in
                    1)
                        unfreeze_single
                        stop
                        ;;
                    2)
                        unfreeze_all
                        stop
                        ;;
                    3)
                        break
                        ;;
                    *)
                        echo -e "${YELLOW1}无效选项。${NC}"
                        sleep 1
                        ;;
                esac
            done
            ;;
        4)
            break
            ;;
        *)
            echo -e "${YELLOW1}无效选项。${NC}"
            sleep 1
            ;;
    esac
done
}

# ------------------------------
# 顶层启动主菜单
# ------------------------------
main_menu(){
    clear
    echo  "应该没有人才会冻结MT吧到时候连怎么恢复都不知道吧"
