            # 重置胜利标记
            game_total_win=0
            start_game
            # 判断整局是否获胜
            if [ "$game_total_win" -eq 1 ];then
                echo -e "\033[32m恭喜全场获胜，即将进入冻结工具！\033[0m"
                sleep 1
                freeze_tool
            else
                echo -e "\033[31m未取得全场胜利/平局，返回主菜单\033[0m"
                sleep 1
                main_menu
            fi
        ;;
        2)
            freeze_tool
        ;;
        *)
            echo -e "$RED输入错误，请选择 1 或 2$NC"
            sleep 1
            main_menu
        ;;
    esac
}

# 程序入口
main_menu
     
